WordHunterWoW_QuestEN = WordHunterWoW_QuestEN or {}
WordHunterWoW_QuestEN[31167] = { title = "Family Tree", description = "So there you have it, traveler, or as much of it as would make for a proper introduction, hmm?\n\nWhat of you, then? Are your people so much different than mine?\n\nSurely, there must be things we share in common. Let us see...", objectives = "Light the Incense Bundle at the Circle of Stone.", progress = "A fine day we're having, wouldn't you say?", completion = "Not so different, you and I.\n\nI believe we can become good friends." }
WordHunterWoW_QuestEN[31168] = { title = "Calligraphed Sigil", description = "This sigil was given to me by a messenger from our Pandaren visitor, Laoxi. It seems he would have words with you when you have a moment. Read it and bring it to him afterwards.", objectives = "Speak to Laoxi inside Aldrassil in Shadowglen.", progress = "Ah, you have come. Good.\n\nI am learning so much - your people have a wealth of knowledge unmatched anywhere I have seen. As much as I am humbled by that fact, I hope that I may teach you of our ways, as well.", completion = "I was warned that not all of your people would be welcoming, but I have found quite the opposite - not only have I been welcomed, but I have learned so much from you.\n\nYou seem quite promising as a young <class>, and I hope I can teach you much of our ways, as your people have taught me of yours." }
WordHunterWoW_QuestEN[31169] = { title = "The Art of the Monk", description = "The true secret to the art of the monk is unlocking the knowledge and power hidden inside yourself.\n\nGo, get more experience, and learn a new skill. Then demonstrate it on one of the training dummies.", objectives = "Reach level 3 to learn Tiger's Palm. Look for a Training Dummy and practice using Tiger's Palm.", completion = "You've proven a capable student. When it is time to resume your training, return to me and I will show you other techniques." }
WordHunterWoW_QuestEN[31170] = { title = "Monk Training", description = "As you advance within your class, you will want to take advantage of the training that your class trainer can provide you.  For young monks here on Sunstrider Isle, your trainer is Pao, our Pandaren visitor.  Speak with her and see what training she has available for you.\n\nPao - as with all the trainers on Sunstrider Isle - is inside the Sunspire on the lower level.", objectives = "Speak with Pao, the Monk class trainer, inside the Sunspire on Sunstrider Isle.", completion = "Ah, welcome. I have been teaching your people the ways of the <class>, and they seem to be well suited for it. Perhaps you too will take to it as quickly as they." }
WordHunterWoW_QuestEN[31171] = { title = "Tiger Palm", description = "Good. You are off to a bright start. This road will be long, and as you become more accomplished, you will begin to discover that you can do things you could never have imagined before.\n\nGo, get more experience, and learn a new technique. Once you have, demonstrate it on one of the training dummies.", objectives = "Reach level 3 to learn Tiger Palm. Locate a Training Dummy outside the Sunspire and practice using it.", completion = "I think you've mastered the basics of the Tiger Palm technique, <name>. Perhaps you will impress me, after all." }
WordHunterWoW_QuestEN[31172] = { title = "Monk Training", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[31173] = { title = "The Tiger Palm", description = "I hope your people are all alright... the crash was unbelievably loud and destructive!\n\n<Mojo looks you over, evaluating your potential.>\n\nYes, you'll do fine. They've said that they need more people to fight, and they don't want me to hurt myself. I'm not afraid, but I don't want to intrude. So, I'll teach you.\n\nAs you may have discovered, your experiences in combat will unlock new potential within you. Go, see if you can master a new ability. Show it to me. You'll get the hang of things.", objectives = "Reach level 3 to learn Tiger Palm. Find a Training Dummy on the northwest side of the Crash Site and practice using it.", completion = "Keep that technique handy, <name>. You can use it to finish off strong opponents, or just to feel awesome, like a tiger." }
WordHunterWoW_QuestEN[31174] = { title = "The Dread Vos", description = "Another paragon calls to us..\n\nThis time, the emanations grow from The Dread Vos, an ancient lake to the south.\n\nFinding him will not be easy, for the way is guarded by our enemies.\n\nI give you this task. If you succeed, you will live.\n\nIf you fail, I will send another.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Kill 12 Enslaved Amberdiggers or Vos'thik Slavelashers, and release the paragon, Korven the Prime." }
WordHunterWoW_QuestEN[31175] = { title = "Skeer the Bloodseeker", description = "Our efforts to secure the shallows before Zan'vess have paid off.\n\nWe have spotted another paragon buried in amber, hidden in the waters to the southwest.\n\nAdding another paragon to our numbers is vital. Another champion from ages past could turn the tide in our favor.\n\nI would go immediately, but unfortunately, I am needed here.\n\nSince you are already a Wakener, you can carry out this task in my stead.", objectives = "Awaken Skeer the Bloodseeker in the underwater cave.", completion = "The hunger... they said it would be fierce, but I did not expect anything like this.\n\nIt is strange to feel so... weak." }
WordHunterWoW_QuestEN[31176] = { title = "A Strange Appetite", description = "Food. I must have food.\n\nIn my time, the meat of the starfish brought not only strength, but also clarity of mind. This is what I must eat.\n\nBring this to me from the nearby shallows.\n\nWait much longer, and I will devour you instead.", objectives = "Collect 12 Starfish Meat.", progress = "The juices of the starfish will clear my mind.", completion = "Yes, give it here! Well done, Wakener." }
WordHunterWoW_QuestEN[31177] = { title = "Fine Dining", description = "In my living years, I was the greatest warrior of the swarm.\n\nHelp me regain my strength, and I shall show you.\n\nI smell the salt sea nearby, and where you can find the sea, you will find briny clackers.\n\nBring me their tails. I must feast upon their flesh.", objectives = "Collect 8 Clacker Tails.", progress = "I have much work to do. The sooner I can fight, the sooner I can return to the Council.", completion = "Excellent. This shall give me the strength to vanquish my foes." }
WordHunterWoW_QuestEN[31178] = { title = "A Bloody Delight", description = "A warrior is not ready for battle until he tastes the blood of his enemies.\n\nI am still too weak to hunt, so you must go in my stead.\n\nOnly the blood from the fiercest predators will do. I can smell their presence in the waters outside this cave!\n\nBring this to me, and then perhaps you shall see why they call me the Bloodseeker.", objectives = "Collect 100 Volatile Blood from Dread Remoras.", progress = "By drinking the blood of your enemies, you acquire their strength.", completion = "Yes, this will do." }
WordHunterWoW_QuestEN[31179] = { title = "The Scent of Blood", description = "I'm afraid that I wet my hands with saurok blood while you were away.\n\nI'm sorry, but I could not help myself. Now, watch them attack me.\n\nPitiful!\n\nDo they think to take vengeance for their fallen? Do they come challenge ME?\n\nI, who have won a hundred wars? I, who stood alone against thousands and still shouted for my enemies to come?\n\nNo, these... saurok... will crumple before me like paper before the flame!\n\nI shall show you my might, Wakener. Fight alongside me and see.\n\nHere they come!", objectives = "Kill 12 Muckscale Flesheaters and the Muckscale Serpentus.", completion = "You have succeeded once again. Well done, Wakener." }
WordHunterWoW_QuestEN[31181] = { title = "Fresh Pots", description = "We got a load of empty crab pots out there that need fresh bait.\n\nNow, we COULD pull them one at a time and bait them up here in comfort. A nice chair to sit on, maybe a hot cup of tea to keep you warm. Sounds nice, doesn't it?\n\nNever gonna happen.\n\nHead to Lonesome Cove, immediately southeast, and bait those pots with two chunks of fresh sea monarch. By \"fresh\" I mean killed right there in the water.\n\nOh, and by \"pots\" I mean traps. If you wanna be part of the crew, you'd better learn the lingo.", objectives = "Bait 10 Empty Crab Pots in Lonesome Cove. Each pot requires 2 Sea Monarch Chunks.", progress = "What's wrong, green? You aren't afraid of the dark, icy sea are you?", completion = "Not bad, green, not bad." }
WordHunterWoW_QuestEN[31182] = { title = "You Otter Know", description = "You know what happened to the bait in those pots?\n\nOtters. That's what happened.\n\nThey prefer fresh clams, but they'll pick our crab traps clean if they're hungry enough.\n\nThe otters in Lonesome Cove are protected by law and we run a legitimate operation here. As much as I'd love to chum those little rats and call it a day, we just make sure they aren't hungry enough to raid the crab pots.\n\nToss 'em a few clams to keep them busy while you're out there.", objectives = "Use the Bag of Clams to feed 8 Coldwhisker Otters in Lonesome Cove.", progress = "In the words of my old deck boss: \"Do what I say, 'cause I said it!\"", completion = "That should keep their little whiskers out of our traps for awhile." }
WordHunterWoW_QuestEN[31183] = { title = "Meet the Cap'n", description = "Alright, {name}, I got another job for ya.\n\nYou see that lion seal in the pen over there? Name's Dog. He's been Soggy's pet for years.\n\nDog's acting up lately - I think he's getting restless in that pen. Why don't you go talk to Soggy and let him know.\n\nI'd say it's about time you meet the cap'n anyway.", objectives = "Speak with \"Soggy\" Su-Dao in Soggy's Gamble.", completion = "New deckhand, eh? We'll see about that.\n\nI run a tight ship - even if she IS at the bottom of the sea." }
WordHunterWoW_QuestEN[31184] = { title = "Old Age and Treachery", description = "Look, I ain't got reason to trust you, but there's a task I can't give to my crew.\n\nI need you to search the wreck of our old ship, the Mist-Hopper, and bring back the charter. It'd be sealed up in a silver tube, in a footlocker.\n\nIt's sort of, uh... incriminating. I can't risk any of the crew finding it if they decide to visit the ol' girl. She's resting on the Shelf of Mazu, to the west.\n\nI'd suggest riding a rip current out there, if you got the stomach. They're all over the shelf.", objectives = "Recover the charter from the Wreck of the Mist-Hopper.", progress = "To be honest, I hope a grouper ate the old charter.\n\nWait, then it might end up here anyway. Dang it!", completion = "That's the charter tube, alright. I guess you'd like to know what all the fuss is about, eh?\n\n<Soggy lets out a long sigh as he un-caps the tube.>\n\nMight as well get it over with." }
WordHunterWoW_QuestEN[31185] = { title = "Walking Dog", description = "Dog ain't my \"pet.\" He's a member of this crew, and my best friend. Saved my life more than once, you know.\n\nBut I'm gettin' too old to walk him anymore, and he still needs his exercise. Take Dog for a trip around the shelf for me, would ya?\n\nHe loves to swim through the hot geysers just southeast of the shallows.\n\nHe absolutely has to... er... \"leave his mark\" on the dead whale at the far western edge of the shelf.\n\nOh, and he'll want to visit our old shipwreck, too. He likes to reminisce.", objectives = "Take Dog to visit the hot geysers, the whale corpse, and the wreck of the Mist-Hopper on the Shelf of Mazu.", completion = "How did it go? I hope he didn't cause too much trouble!" }
WordHunterWoW_QuestEN[31186] = { title = "Dog Food", description = "<Dog whines as best as a lion seal can, feebly lifting one flipper toward his massive jaws.\n\nHe's hungry.\n\nThe Shelf of Mazu is covered in rockshell makrura that should make a fine meal for him.>", objectives = "Help Dog to eat the remains of 10 Rockshell Snapclaws.", progress = "<This has got to be the most pathetic lion seal you've ever seen.>", completion = "<Dog licks his chops happily, looking satisfied.>" }
WordHunterWoW_QuestEN[31187] = { title = "On the Crab", description = "I just got word that a string of pots we dropped this morning hit it BIG. We're on the crab!\n\nProblem is, the rips are getting stronger and we lost track of some of the pots. They're just sitting out there, filled with spiky blue GOLD!\n\nI need you back out there. Hook one of these buoys up to any of the full traps you find and send it to the surface for us.", objectives = "Attach a Mist-Hopper Buoy to 8 Full Crab Pots on the Shelf of Mazu.", completion = "Nice work out there!" }
WordHunterWoW_QuestEN[31188] = { title = "Shark Week", description = "Crabbing is our big money-maker, but we send all kinds of goods back around the wall. Oils, plants, even rare minerals - the sea's bounty is rich out here!\n\nRight now the big craze in the markets back home is thresher teeth. Apparently they make great necklaces?\n\nThreshers are all over the Shelf of Mazu to the west. Bring me lots of teeth!", objectives = "Collect 200 Thresher Teeth by pulling them from the jaws of Longfin Threshers on the Shelf of Mazu.", progress = "Having actually seen someone eaten by a thresher, I'm not sure why you'd willingly string their teeth around your neck, but whatever.", completion = "Those are perfect, just put them down over there. I'd rather not touch them myself. Creeps me out." }
WordHunterWoW_QuestEN[31189] = { title = "Reeltime Strategy", description = "I never thought I'd see the day, but for the first time since... well, EVER, Master Angler Ju Lien asked for some help with his lines.\n\nApparently the sea is going crazy today and he can't keep up. See if you can give him a hand. He's fishing just south of here.", objectives = "Assist Master Angler Ju Lien in Soggy's Gamble.", progress = "Go give Ju Lien a hand, would ya?", completion = "What happened out there?! I heard a scream and next thing I know these nasty things come rolling in on the next wave!" }
WordHunterWoW_QuestEN[31190] = { title = "The Mariner's Revenge", description = "I'm not gonna sit in a damn rocking chair while my crew gets devoured by a leviathan!\n\nCome on, let's get to the dock and launch a dinghy. I got a special one set up just for this kind of situation. My own little Mist-Hopper Jr.\n\nWe'll give that thing a case of harpoon fever.", objectives = "Launch the Mist-Hopper Jr. from the dock in Soggy's Gamble and use it to bring down Jiao.", progress = "Let's go!", completion = "Nice shooting out there!\n\nI knew we could do it. Never met anything that can't be killed with enough harpoons." }
WordHunterWoW_QuestEN[31194] = { title = "Slitherscale Suppression", description = "The Slitherscale take orders from their leader, the Slitherscale Lizard-Lord. He can be found celebrating his victories on the southeastern corner of Windward Isle.\n\nIf we can destroy this leader, we can deal their tribe a great blow.\n\nWithout their lord, the Slitherscale will think twice before attacking the gentle cloud serpents of the east.", objectives = "Kill the Slitherscale Lizard-Lord.", progress = "A snake without a head cannot strike.", completion = "Wonderful! I knew you could triumph against the Slitherscale lord." }
WordHunterWoW_QuestEN[31195] = { title = "Ooked the Dooker", description = "", objectives = "" }
WordHunterWoW_QuestEN[31196] = { title = "Sra'vess Wetwork", description = "The mantid outnumber us quite badly. Hundreds of them for each of us.\n\nAnd, they surround us on two sides - at Gao-Ran in the south we're holding them off, but to the west, on the island they call Sra'vess, they continue to mass unabated.\n\nWe're not stupid. We're not going to launch a full scale attack on them. We can't sustain an intense battle on multiple fronts.\n\nInstead, we're going to send you, and one of our Wu Kao, to do some dirty work. Sounds fun, doesn't it?", objectives = "Kill any 15 non-elite mantid near Sra'vess.", progress = "The mission isn't complete, <name>.", completion = "Good work. I think it's always best to strike while they're unprepared." }
WordHunterWoW_QuestEN[31197] = { title = "The Bigger They Come...", description = "Killing the smaller mantid works mostly as a distraction. It forces them to replenish their numbers before they consider any serious offensive.\n\nThe big ones, though - we kill a few of those, and we really disrupt operations on the island. That buys ourselves a substantial amount of time. With mantid, it's like their size is directly proportional to their importance in the empire.\n\nSo kill some of the big ones for me, while you're out there.", objectives = "Kill any 4 elite mantid at Sra'vess.", progress = "I don't think you're done yet.", completion = "Well done, well done. That should keep us safe for a few days, at least." }
WordHunterWoW_QuestEN[31198] = { title = "A Morale Victory", description = "The mantid have statues built on Sra'vess. We don't know exactly what they use them for. They may have some sort of religious significance, or maybe they assist with their sonic communication.\n\nWhen you fight your opponent, you don't just engage them physically, you also engage them mentally. Whatever they use them for, the fact is that those statues are important to them.\n\nWhich is why I want you to blow them up. Losing something important will be a substantial hit to morale.", objectives = "Destroy the Southern, Central, Eastern and Western Idols at Sra'vess.", progress = "The statues?", completion = "I'm sure they'll be upset without those statues. Right?" }
WordHunterWoW_QuestEN[31199] = { title = "Destroy the Siege Weapons!", description = "The mantid don't just attack in swarms. \n\nThey're smart. They use alchemy, bombs... and what's worst, they've got siege weapons. Those have the potential to be incredibly destructive if they attack with them.\n\nWe've got reports that they're building up a force of siege weapons to the west at Sra'vess. Go and destroy them.", objectives = "Destroy the four mantid siege weapons at Sra'vess in Townlong Steppes.", completion = "Those siege weapons won't be a problem. They may rebuild, but we've bought ourselves some time." }
WordHunterWoW_QuestEN[31200] = { title = "Fumigation", description = "Our alchemists have cooked up a set of gas bombs that will discourage mantid from staying anywhere that we set them off. \n\nIf we plant these in the critical structures of Sra'vess, they'll need to evacuate. That should sow some chaos and delay any action from the mantid there for days.\n\nGet to it, {name}.", objectives = "Plant Shado-Pan Gas Bombs within the 5 targeted structures on Sra'vess.", progress = "Have you planted the gas bombs?", completion = "Nice, I can see the smoke from here. That should definitely cause some confusion!" }
WordHunterWoW_QuestEN[31201] = { title = "Friends, Not Food!", description = "Our scouts have sent a very troubling report. \n\nThree of our trainees have gone missing, and our scouts found them... \n\nThey've been captured by the mantid and sent to their Kunchong pits. \n\nTheir Kunchong FEEDING pits. We're lucky that the Kunchong don't eat that often.\n\nI need you to get in there, give them these escape kites, and get them out!", objectives = "Rescue a Shado-Pan Trainee in each of the north, central and south Kunchong feeding pits.", progress = "The trainees, <name>! You have to save them!", completion = "Oh, thank goodness. I was worried about them!" }
WordHunterWoW_QuestEN[31203] = { title = "Target of Opportunity: Sra'thik Swarmlord", description = "While we're here, we should do one more thing.\n\nThe Sra'thik Swarmlord is responsible for directing the mantid forces from the air. If we leave it alive, it's going to cause trouble for the garrison.\n\nSo we're not going to leave it alive. Let's take it out, {name}.", objectives = "Kill the Sra'thik Swarmlord at Sra'vess in Townlong Steppes.", progress = "We need to take down the Swarmlord!", completion = "I heard you did a little... extra credit while you were out there. Good work, friend.\n\nCome back another day - I'm sure we'll have some more work for you." }
WordHunterWoW_QuestEN[31204] = { title = "Target of Opportunity: Sra'thik Hivelord", description = "Near the ocean, on the eastern side of Sra'vess, there is a cavern that leads to a network of caves.\n\nFrom there, the Sra'thik Hivelord maintains Sra'vess and plots against us. If we manage to take him out, we'll disrupt their operations for days.\n\nLet's go to it.", objectives = "Defeat the Sra'thik Hivelord.", progress = "We've got to kill the Hivelord.", completion = "Well done, <name>! Because you took on that extra work, you've bought us some respite from the mantid.\n\nI'm sure I'll have more work for you in the future, though. Come back later." }
WordHunterWoW_QuestEN[31205] = { title = "Lorewalker Cho Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[31206] = { title = "The Crucible of Carnage: The Bloodeye Bruiser!", description = "I'll tell you what, buddy, this place is a far cry from the rolling plains of Nagrand or the bloodbowl in Zul'Drak, but hey, I go where the gold's at! So welcome to Twi-Hi, pal.\n\nYou're new to this pit, so let me set you straight. I'm the fight promoter and this feisty troll next to me is Wodin, my bodyguard. You're the entertainment. When you wanna fight, let me know and I'll set up the match.\n\nIf you're ready and got a group of friends with you, we can start! What do you say?", objectives = "Get in the arena at the Crucible of Carnage and defeat Hurp'derp!" }
WordHunterWoW_QuestEN[31207] = { title = "The Arena of Annihilation", description = "Ah, I can still remember running fights out of a muddy hole in the ground back in Nagrand. We've come a long way, eh, Wodin?\n\nI tell you, there's nothing more these Tiger monks like than a good scrap. So much so that they've paid good coin for me to set up shop here and help draw the strongest fighters from all around!\n\nSo how about it? You and a couple friends up for a few rounds in the Arena of Annihilation...? Big money, big prizes!", objectives = "Enter and complete the Arena of Annihilation scenario. Afterwards, collect your reward from Wodin the Troll-Servant.", progress = "What are you waiting for? The monks are spoiling for a good show.", completion = "Gurgthock said you he'd make it worth your while, kid. Take your pick!" }
WordHunterWoW_QuestEN[31208] = { title = "Venomous Intent", description = "If we are to strike against the Empress, we must arm ourselves with weapons. My own choice of weapon is of a particularly toxic design.\n\nThe scorpions wandering the ledge produce a deadly venom that they store in their tails.\n\nBring me their stingers, and I will show you how I earned the title of paragon.", objectives = "Collect 8 Venomous Stingers.", progress = "Did you feel the venomtail's sting? Such lovely pain.", completion = "Well done, Wakener. I hope you handled these stingers carefully.\n\nThe natural poison from these scorpions is deadly, but slow." }
WordHunterWoW_QuestEN[31209] = { title = "Dark Wings, Dark Things", description = "I require another ingredient to create my first poison, Wakener.\n\nThis ingredient you can easily find on the scarabs nearby.\n\nKill them and bring me their wings.", objectives = "Collect 150 Scarab Wings.", progress = "Scarab wings can be crushed to produce a very fine white, deadly powder.", completion = "Yes, excellent, Wakener! These are perfect.\n\nHave you ever considered learning the poisoner's craft?" }
WordHunterWoW_QuestEN[31210] = { title = "A Shade of Dread", description = "The last ingredient is perhaps the deadliest.\n\nThe dreadshade flower grows all along these hills.\n\nIt is by eating these poisonous plants that the local wildlife has become so venomous.\n\nA single drop of dreadshade nectar can stop a kunchong's heart.\n\nGo and bring me some of these flowers. Do not be tempted to taste them.", objectives = "Collect 8 Dreadshade.", progress = "Sometimes, the most beautiful things are also the most dangerous.", completion = "Many would not know the value of what you hold.\n\nYou have done well, Wakener." }
WordHunterWoW_QuestEN[31211] = { title = "The Poisoned Mind", description = "Before we return to Klaxxi'vess, I wish to look upon the empire.\n\nThe Klaxxi Council told me that the enemy gathers outside the Empress's palace.\n\nMy poisons are ready. What better way to announce my return than with death and destruction?\n\nJust be careful not to mix the two serums... at least not while you're holding the vessels.\n\nSpeak to me when you are ready to fly.", objectives = "Speak to Xaril the Poisoned Mind. Kill 200 mantid and 3 kunchong while flying with him.", progress = "Fight from above.", completion = "Thank you for returning me home, Wakener, but I fear the war has just truly begun." }
WordHunterWoW_QuestEN[31212] = { title = "FLAG - Chose Tenwu", description = "", objectives = "" }
WordHunterWoW_QuestEN[31213] = { title = "FLAG - Chose Taoshi", description = "", objectives = "" }
WordHunterWoW_QuestEN[31214] = { title = "FLAG - Chose Nurong", description = "", objectives = "" }
WordHunterWoW_QuestEN[31216] = { title = "Dark Skies", description = "The swarm begins, Wakener! The mantid amass at the Heart of Fear.\n\nAlready they fill the skies with their wings and rend the earth with their claws. They shall not stop the dark march until their bodies are laid open and bleeding upon the ground.\n\nThis we shall gladly do. We will attack them from above. While I fly, use my poisons to destroy their advance.\n\nDo not mix the two serums until you are ready to attack. The reaction can be quite... violent.\n\nSpeak to me when you are ready to go.", objectives = "Kill 200 Mantid and 3 Kunchong or Dread Behemoths while flying with Xaril the Poisoned Mind.", progress = "Such wonderful destruction!", completion = "Well done, Wakener. You have a destroyer's aim." }
WordHunterWoW_QuestEN[31218] = { title = "FLAG - Unlocked Tenwu", description = "", objectives = "" }
WordHunterWoW_QuestEN[31219] = { title = "FLAG - Unlocked Nurong", description = "", objectives = "" }
WordHunterWoW_QuestEN[31220] = { title = "The Challenger's Ring: Hawkmaster Nurong", description = "You've really been building up respect with the Shado-Pan, {name}.\n\nNurong's interested in trying out his skills against you.\n\nThe good news is, if you win, I'll allow him to go with you on your missions.\n\nThe bad news is, I really don't think you'll win.", objectives = "Challenge Hawkmaster Nurong, and then defeat him in combat at Shado-Pan Garrison in Townlong Steppes.", progress = "Not up to the challenge? I understand.", completion = "Well, well, well. Looks like I was wrong.\n\nGood work. Nurong's looking forward to accompanying you on your missions." }
WordHunterWoW_QuestEN[31221] = { title = "The Challenger's Ring: Tenwu of the Red Smoke", description = "So... you've been challenged by the infamous Tenwu of the Red Smoke.\n\nThat's what he calls himself, at least. He's a good fighter, and a good rogue, but it's a wonder he manages to sneak up on anyone with how loudly he brags about himself.\n\nAnyways, I think you should answer the challenge. Maybe it'll give him a touch of humility. Maybe not. Either way, if you win, he'll probably be willing to go with you on your missions. \n\nAnd I get some entertainment.", objectives = "Challenge Tenwu of the Red Smoke, and then defeat him in combat at Shado-Pan Garrison in Townlong Steppes.", completion = "Wow! Well done. Glad to see you fought so well.\n\nMaybe if he's trying to keep up with your fighting it'll help keep his mouth shut." }
WordHunterWoW_QuestEN[31228] = { title = "Prophet Khar'zul", description = "Prophet Khar'zul is a powerful caster, but he is also underestimating your abilities.\n\nKhar'zul and his forces must be destroyed to protect this village. His death will send a strong message to the Thunder King that we will not be defeated!\n\nYou'll find him on the Isle of Reckoning.", objectives = "Defeat Prophet Kharzul.", progress = "Is Khar'zul dead?", completion = "These events should be learned from, <name>.\n\nIt is important that we learn from our history. Had we paid attention to the histories, we may have been able to head this off before it got this far.\n\nEverything that has happened was already foretold, we just didn't know how to read it." }
WordHunterWoW_QuestEN[31230] = { title = "Welcome to Dawn's Blossom", description = "Cho's off on another one of his adventures, and this one requires a big order of jade. I'm going to have to call in some favors.\n\nHow 'bout in the meantime you introduce yourself to some of the locals.\n\nKai Wanderbrew is a good guy to know, as is Master Windfur. Oh, and say hi to Peiji Goldendraft up at the inn.\n\nBetween the three of them, you should get the feel for life in Dawn's Blossom.", objectives = "Speak with Kai Wanderbrew, Master Windfur, and Peiji Goldendraft in Dawn's Blossom.", progress = "Any luck?", completion = "Good, good, good. You're going to fit right in." }
WordHunterWoW_QuestEN[31231] = { title = "Dreadspinner Extermination", description = "Back in Gurthani Terrace where you found me, dreadspinners continue to occupy the attention of Shado-Pan marksmen who could otherwise be thinning out this wretched swarm.\n\nEradicate those spiders and offer some relief to the archers on that wall.", objectives = "Slay 8 Dreadspinner Tenders in the Terrace of Gurthan. Speak with Kil'ruk the Wind-Reaver for an air-drop.", completion = "I never liked spiders. Filthy, mindless insects." }
WordHunterWoW_QuestEN[31232] = { title = "An Ancient Empire", description = "My brothers speak of an ancient mogu empire that once dwelled in the ruins to the east.\n\nOnce, this tribe knew untold secrets of sorcery and subjugation.\n\nI have a curious mind, Wakener, and I wish to learn of the empires that ruled after my time.\n\nKnowledge of the past will determine our future.\n\nGo search the ruins for their ancient tablets. I will study their secrets and make them our own.", objectives = "Collect 8 Gurthani Tablets.", progress = "What knowledge do you bring?", completion = "Good, Wakener. It will take me time to decipher these tablets, but all knowledge is worthy." }
WordHunterWoW_QuestEN[31233] = { title = "Sap Tapping", description = "I found a grove of young amber trees to the east, Wakener.\n\nI've placed tapping devices on these trees, but I have been too busy to retrieve the sap.\n\nI need someone to find the extractors. Activate them, then bring me samples of the amber.", objectives = "Collect 6 Amber Sap.", progress = "These trees are still young. They are not yet kypari.\n\nTheir sap is like water, while the sap of a true kypari tree is like wine.\n\nThey must be allowed to grow.", completion = "Ah yes, this is exactly what I needed.\n\nI will examine these samples. We must continue to monitor the health of these young kypari." }
WordHunterWoW_QuestEN[31234] = { title = "Putting An Eye Out", description = "Ah! Wakener! You must help me! (You will help me, or else I will help myself to you!)\n\nI need more materials for my experiments, yes yes! (Blood and guts, hearts and brains, tongues and eyes, eyes, eyes!)\n\nTo the west, I have seen creatures of mist and fog. They possess such big, round, wonderful globes! Big for seeing, round and unblinking!\n\nGo now, little Wakener. Bring me back a single pristine eye!", objectives = "Collect 1 Pristine Mire Beast Eye.", progress = "Ooooh, what wonderful, tasty parts have you brought me?", completion = "Yes, yes! Wonderful! Oh, so delicious!" }
WordHunterWoW_QuestEN[31235] = { title = "Nope Nope Nope", description = "I recovered this weapon on a recent scouting run near the wall. It would seem ideal for helping your Shado-Pan with their infestation problem in Gurthani Terrace.\n\nThe more they are focused on keeping spiders off the wall, the less time they are killing fear-gripped swarmborn.", objectives = "Use the Shado-Pan Dragon Gun to destroy 20 Dreadspinner Eggs in Gurthani Terrace.", completion = "A crude weapon, but it has its uses." }
WordHunterWoW_QuestEN[31237] = { title = "Debugging the Terrace", description = "If this Empress is truly possessed by fear and paranoia, she will have sent scouts to every corner of the land in order to cement her control.\n\nThese scout grubs are likely everywhere, but difficult to spot with the naked eye. Better to track them by the pheromone trails they leave behind.\n\nI've already... gifted you... a reactive toxin that will reveal these trails to you for a brief time after experiencing the thrill of victory.\n\nGo now to the Terrace of Gurthan and root out these spies.", objectives = "Stomp out 6 Eyes of the Empress around the Terrace of Gurthan. Killing anything will grant you Pheromone Tracking, helping you detect them.", progress = "Best not to ask how I afflicted you with the toxin - you have become quite useful to us, and it would be a shame if we drove you mad with horror just yet.", completion = "Information is power, <name>. We cannot allow the Empess to monitor our movements." }
WordHunterWoW_QuestEN[31238] = { title = "Brain Food", description = "Kovok is growing at an accelerated rate, but his brain may not be able to keep up. He'll require a special diet to ensure that he does not outgrow the capacity to control his own body.\n\nMushan tongue is rich in the nutrients that promote brain growth in kunchong, but they normally eat the beasts whole and fill up quickly. If we feed Kovok only mushan tongues every couple of days or so, it should balance out his growth.\n\nGreatback mushan graze the hills east of here, near the Gurthani Terrace.", objectives = "Bring 4 Mushan Tongues to Kaz'tik the Manipulator at Klaxxi'vess.", progress = "Have you found a suitable meal for Kovok?", completion = "Kovok was whining the whole time you were away. It was really quite pathetic." }
WordHunterWoW_QuestEN[31239] = { title = "What's in a Name Name?", description = "So, you wanna be a hozen. Huh, wikket?\n\nHozen defend their lands from enemies, like jinyu.\n\nKah Kah fought many jinyu fights, and won them all.\n\nHozen only give name name to good grookers. Go grook jinyu and maybe they call you {name} {name}.\n\nJinyu creepin' down by the river. Ook 'em in the dooker!", objectives = "Kill 7 Riverstride Jinyu.", completion = "Ha ha! Wikket Grooked ookin' Jinyu!" }
WordHunterWoW_QuestEN[31240] = { title = "Guo-Lai Infestation", description = "Anji came by and asked for you. Said she was heading to the northeast ruins.\n\nOh, Anji, such a fiery spirit, that girl! Probably better for your long-term health if you not keep her waiting.", objectives = "Speak to Anji Autumnlight at the Ruins of Guo-Lai.Anji came by and asked for you. Said she was heading to the northeast ruins.\n\nOh, Anji, such a fiery spirit, that girl! Probably better for your long-term health if you not keep her waiting.", completion = "Good, you're here.\n\nFor a while there, I was wondering if Ren would even deliver the message." }
WordHunterWoW_QuestEN[31241] = { title = "Wicked Wikkets", description = "{name} good wikket, they say...\n\n{name} help hozen, they say...\n\nNo more grookin' {name}, they say.\n\nThat ok. Look out there. Wicked wikkets fallin' like rain, ripe for the grookin'!\n\nGo, join the fun. But remember, Chief Kah Kah gets all the shinies! That's hozen rule number two.\n\n<Jeek Jeek scratches his head.>\n\nHmm, all hozen rules are number two...", objectives = "Collect 6 Alliance Service Medallions from Battleworn Paratroopers.", progress = "Whatcha got, wikket?", completion = "Wikket grookin' makin' hozen rich with shinies!\n\n<name> makin' a good second impression. And for hozen, number two is most important!" }
WordHunterWoW_QuestEN[31242] = { title = "Mistfall Village", description = "My scouts have spotted no mogu near Mistfall Village today, but I've been hearing of some troubles with local wildlife and spirits in the graveyard. I dispatched Che to assess the situation, but he'll most likely need your help.\n\nFind your way southwest to the village and meet Che there. Do what you can.", objectives = "Speak to Che Wildwalker at Mistfall Village.", completion = "Leven sent me a good one today! I must thank him later." }
WordHunterWoW_QuestEN[31243] = { title = "Attack on Mistfall Village", description = "Mogu have been sighted at Mistfall Village to the southwest. I dispatched Rook and Sun immediately, but I need another capable hand there as soon as possible.\n\nDon't delay. The villagers need you.", objectives = "Speak to Sun Tenderheart at Mistfall Village.", completion = "Oh, thank the celestials you're here! This is worse than we thought!" }
WordHunterWoW_QuestEN[31244] = { title = "Guo-Lai Encampment", description = "Leven came by in quite a huff! Said something about mogu in the ruins.\n\nBest be off to find him I think. Angry Leven is not a fun Leven.", objectives = "Speak to Leven Dawnblade at the Ruins of Guo-Lai.Leven came by in quite a huff! Said something about mogu in the ruins.\n\nBest be off to find him I think. Angry Leven is not a fun Leven.", completion = "Glad you're here. Let's get to work." }
WordHunterWoW_QuestEN[31245] = { title = "Mistfall Village", description = "Che stopped by on the way to the village and ask if I'd seen you. I told him no.\n\nYou can go see him if you want. But now you're not obligated to see him! I am so marvelously considerate, am I not?", objectives = "Speak to Che Wildwalker at Mistfall Village.Che stopped by on the way to the village and ask if I'd seen you. I told him no.\n\nYou can go see him if you want. But now you're not obligated to see him! I am so marvelously considerate, am I not?", completion = "Ren send you my way? He puts on playful air, but he follows through when it matters. Can't hold it against him much." }
WordHunterWoW_QuestEN[31246] = { title = "Attack on Mistfall Village", description = "I can see smoke from the village. And it's not my fault this time!\n\nBest go and help.", objectives = "Speak to Rook Stonetoe at Mistfall Village.I can see smoke from the village. And it's not my fault this time!\n\nBest go and help.", completion = "You come to help Rook?" }
WordHunterWoW_QuestEN[31247] = { title = "Setting Sun Garrison", description = "Anji and Kun stopped by on the way to the garrison. Lovely pair, don't you think? So different, yet so devoted to each other... ah, it makes my heart swoon just thinking about it.\n\nThey asked for you by name. Maybe they want to put you through some of the training paces? I certainly hope they don't have something more naughty in mind...", objectives = "Speak to Anji Autumnlight at the Setting Sun Garrison.", completion = "Well timed. I was just about to go put some recruits through their paces, but I'd be much more eager to see what you have to offer." }
WordHunterWoW_QuestEN[31248] = { title = "The Ruins of Guo-Lai", description = "I've instructed Anji and Kun to resume investigation of the Ruins of Guo-Lai. We have no reports of any significant mogu presence there today, but it seems to be one of their central interests here in the Vale, and want it under thorough watch consider their attack on the lake.\n\nThat's why I'm sending you as well.\n\nHead west, past the lake, to the ruins. Anji will instruct you further.", objectives = "Speak to Anji Autumnlight at the Ruins of Guo-Lai.", completion = "If it isn't one of my favorite paladins. Glad to have you with us." }
WordHunterWoW_QuestEN[31249] = { title = "Mistfall Village", description = "Everything I've heard suggests the village has been unaffected by the Shao-Tien offensive at the lake, but I won't take any risks.\n\nI'm dispatching you and Che Wildwalker to keep watch at the village, and aid the townsfolk while you're there.", objectives = "Speak to Che Wildwalker at Mistfall Village.", completion = "It is strange to be dispatched away from the combat, but Leven is right in that the villagers need our protection. We cannot afford any risks." }
WordHunterWoW_QuestEN[31250] = { title = "Setting Sun Garrison", description = "We've taken losses from the mogu forces descending the Golden Stair and their flanking attackers at Whitepetal Lake. Our lines are thin.\n\nI'm dispatching Anji and Kun to the Setting Sun Garrison to double our efforts at training new recruits. I'd like you there with them, {name}. Show them what a true {class} is made of.", objectives = "Speak to Anji Autumnlight at the Setting Sun Garrison.", completion = "Let's whip these recruits into shape." }
WordHunterWoW_QuestEN[31251] = { title = "Best Meals Anywhere!", description = "Yeah, yeah.\n\nEveryone knows us goblins do tinkering. And explosives. And... well, ya' know, the less reputable stuff.\n\nBut what nobody knows is that I'm really a great chef! It's a hobby of mine.\n\nGather us up some meaty bits from the creatures around here, and I'll cook us up the best meals ANYWHERE!\n\nAnd I promise, I'll only use three or four percent rocket fuel.", objectives = "Collect 160 Kun-Lai Meaty Bits.", progress = "The meaty bits, <name>? We need 'em!", completion = "You know what they say about cooking - GTL. Garnish, taste... and... laundry?" }
WordHunterWoW_QuestEN[31252] = { title = "Back to Westwind Rest", description = "Well, far as I figure, we've got quite a lot of rebuildin' to do.\n\nI'm not one for joining any big causes, but my farmhands aren't gonna have much to do 'round here, to be honest. And, since you helped them out, they want to join your \"Alliance.\" So, who am I to stop 'em?\n\nBring 'em with you, back to Farmhand Bo. I'll miss 'em, but they're better off with you.", objectives = "Return to Farmhand Bo at Westwind Rest in Kun-Lai Summit.", completion = "You did good, bringing these guys back. We'll have 'em farming you up some food in no time!" }
WordHunterWoW_QuestEN[31253] = { title = "Back to Eastwind Rest", description = "Well, far as I figure, we've got quite a lot of rebuildin' to do.\n\nI'm not one for joining any big causes, but my farmhands aren't gonna have much to do 'round here, to be honest. And, since you helped them out, they want to join your \"Horde\". So, who am I to stop 'em?\n\nBring 'em with you, back to Farmhand Ko. I'll miss 'em, but they're better off with you.", objectives = "Return to Farmhand Ko at Eastwind Rest in Kun-Lai Summit.", completion = "You did good, bringing these guys back. We'll have 'em farming you up some food in no time!" }
WordHunterWoW_QuestEN[31254] = { title = "The Road to Kun-Lai", description = "Ah! Greetings friend of Lorewalker Cho. I have a message for you.\n\n<The strange little creature hands you a battered scroll case.>\n\nThe Lorewalker waits for you in Kun-Lai. Very dangerous to travel there, yes, very dangerous.\n\nLook for guides along the road to help you find your way.", objectives = "Travel through the Veiled Stair to Binan Village.", progress = "More strangers? This day is testing my limits.", completion = "Oh, you are a friend of Cho's? Welcome! Welcome!\n\nI would serve you a banquet but as you can see we are in dire straights at the moment.\n\nSay, would you be willing to lend us a hand?" }
WordHunterWoW_QuestEN[31255] = { title = "The Road to Kun-Lai", description = "Ah! Greetings friend of Lorewalker Cho. I have a message for you.\n\n<The strange little creature hands you a battered scroll case.>\n\nThe Lorewalker waits for you in Kun-Lai. Very dangerous to travel there, yes, very dangerous.\n\nLook for guides along the road to help you find your way.\n", objectives = "Travel through the Veiled Stair to Binan Village.", progress = "More strangers? This day is testing my limits.", completion = "Oh, you are a friend of Cho's? Welcome! Welcome!\n\nI would serve you a banquet, but as you can see, we are in dire straights at the moment.\n\nSay, would you be willing to lend us a hand?" }
WordHunterWoW_QuestEN[31256] = { title = "Round 'Em Up", description = "Lok'tar, {class}.\n\nWe've made progress, but we're going to need mobility if we want to maintain our foothold here in Kun-Lai.\n\nI don't see many worgs, kodo, or the like around here. What I do see are yaks. Our pandaren allies have said they make good mounts, so they'll have to do.\n\nGo round some up and return them here, so we can get our people riding them!", objectives = "Round up 3 Wild Plains Yaks and return them to Eastwind Rest.", progress = "The yaks?", completion = "Well done! Well, they're plenty stubborn, I'll say that much. But they should do nicely." }
WordHunterWoW_QuestEN[31260] = { title = "Profit Mastery: Chasheen", description = "I am totally on to another great scam!\n\nWhen I was flying overhead I saw a really ancient tigress prowling about.\n\nDo you know how much her blood would go for on the black market? Not to mention if I convince some warlocks it adds extra potency to their summoning spells or something.\n\nIf you bring me back some of her blood I will cut you in on the scam. She was prowling about on the far side of the Dojani River from here.", objectives = "Collect Ancient Tiger's Blood.", progress = "I thought about taking that tiger on myself but to be honest I like living...", completion = "Impressive! Can you smell the money? Here's your end." }
WordHunterWoW_QuestEN[31261] = { title = "Captain Jack's Dead", description = "Gore from Captain Jack's head drips and mysteriously seeps into the ground as you examine your hard-won trophy.\n\nStrange, but no time to investigate that now. There's too much work to be done.\n\nThe chieftain of your newfound friends will doubtlessly be impressed with this proof of your grookin' skills.", objectives = "Bring Captain Jack's head to Chief Kah Kah at Grookin Hill.\n\nProvided item:", completion = "Ookin' grookin, wikket!" }
WordHunterWoW_QuestEN[31262] = { title = "Crane Mastery: Needlebeak", description = "So, now that you've got a vibe for how cranes fight, I've got a doozy for you.\n\nNeedlebeak!\n\nOr at least, that's what I'm calling him. Biggest crane I ever saw. And its beak is so sharp it's like a sword.\n\nNorthwest of here you'll find the big water fall that kicks off the Dojani River. Needlebeak likes to hang out by the waterfall.\n\nYou bring me its beak as a trophy and I will talk you up a good game to Nesingwary.", objectives = "Acquire the Needlebeak.", progress = "I watched that bird stab a tiger through the face. What kind of place is this where birds are the predators for tigers?", completion = "Now THAT is a trophy. Looks intimidating. Wait... is this your blood on it?" }
WordHunterWoW_QuestEN[31265] = { title = "Mazu's Breath", description = "Here to help, are ya? Well, first thing's first.\n\n<Arie rummages through her pockets for a moment before producing a small vial of glowing blue fluid.>\n\nHere it is! \"Mazu's Breath.\" Cap'n's own formula.\n\nWhat? You thought I'd send you out to sea without a means of breathin'? I need deckhands, not corpses!\n\nDown the hatch with it, green. This'll give you a fighting chance out there on the shelf.", objectives = "Drink the Potion of Mazu's Breath.", progress = "No, I don't have a \"chaser!\" Just drink it!", completion = "You'll thank me later." }
WordHunterWoW_QuestEN[31266] = { title = "Mogu Incursions", description = "We've heard reports of a group of Mogu infiltrating the coast here in Townlong. I have no idea what they are doing. Frankly, I don't care. \n\nYou've proven yourself, so we've decided to give this mission to you.\n\nWhat's going to happen is this - you're going to go, find them, and kill them.\n\nOur scouts reported the first group landed to the north, between here and Deadtalker's Plateau. Go there and wipe them out.", objectives = "Find and kill the Shan'ze Spymaster.", progress = "Why aren't they dead already?", completion = "It was just a decoy! They've moved to attack Niuzao Temple!" }
WordHunterWoW_QuestEN[31267] = { title = "Mistblade Destruction", description = "Korven has told me of his findings. There is an enormous amber deposit sitting at the bottom of the Lake of Stars.\n\nUnfortunately, a hostile saurok tribe lives at the edge of the lake, and revere the amber as their own.\n\nThey will not allow us to enter their territory easily.\n\nGo south to the lake. Kill the Mistblade saurok, so that we can more easily harvest the nearby amber.", objectives = "Kill 6 Mistblade Rippers.", completion = "Well done. With access to this amber, we shall be able to craft weapons to our cause." }
WordHunterWoW_QuestEN[31268] = { title = "A Little Brain Work", description = "Far to the south, the swarm breeds weapons of destruction - enormous, nearly unbreakable amber scorpions.\n\nLike all other creatures, they are subject to manipulation, but unlike other creatures, they have not yet submitted to my mind control.\n\nIt appears that further research is necessary before I can dominate them for our own purposes.\n\nI must study their brains, and you must retrieve some specimens for me.\n\nTake this sonic emitter. I have found it to be quite effective against the beasts.", objectives = "Collect 3 Amber-Encrusted Brains from Ik'thik Amberstingers.", progress = "They continue to resist my sonic manipulation. I must understand why.", completion = "My my, this is interesting indeed. They are unlike any other brains I have seen.\n\nI will study these carefully." }
WordHunterWoW_QuestEN[31269] = { title = "The Scale-Lord", description = "The saurok at the Lake of Stars take their orders from their Scale-Lord, a vicious, merciless leader who guards his territory fiercely.\n\nIf we can eliminate this leader, then we can gain access to the enormous amber lode beneath the lake.\n\nGo. Their leader gives his orders from his underground dwelling, at the southern edge of the lake.", objectives = "Kill the Mistblade Scale-Lord.", completion = "Good. I am glad to hear that he is dead." }
WordHunterWoW_QuestEN[31270] = { title = "The Fight Against Fear", description = "When we discovered the sha influence at Kypari Zar, I had hoped the corruption could still be cleansed.\n\nUnfortunately, the Klaxxi Council has confirmed that the sha of fear's corruption is deep-seated, and continues to spread.\n\nTo the south, I have observed some of the local wildlife consumed by an unnamed terror.\n\nThe sha can warp and twist its victims into unimaginable horrors.\n\nWe must stop the corruption before it becomes worse. Seek out the sha-infected Horrorscale Scorpids. Eliminate them.", objectives = "Kill 15 Horrorscale Scorpid.", completion = "You have purged the hills of the infected creatures? Good.\n\nThe sha is a merciless enemy. Thus must we be merciless in return." }
WordHunterWoW_QuestEN[31271] = { title = "Bad Genes", description = "Far to the south, Wakener, the Empress's genemancers set about their dark experiments. (Dark yes, but not as dark as mine!)\n\nThey dissect and mutate the nearby wildlife, breeding creatures of their own design. (Their design, which will become my design!)\n\nWe must not let them succeed! (No, no! Only I am allowed such power!)\n\nTheir mutations are already being unleashed for war. Go! Destroy them at any cost!", objectives = "Kill 3 Ik'thik Genemancers and 6 Ik'thik Egg-Drones.", progress = "Is it done? Are my competitio - I mean, our enemies - dead?", completion = "Yes, yes! They are dead!\n\nThank you, Wakener. Well done." }
WordHunterWoW_QuestEN[31272] = { title = "Infection", description = "The Empress's genemancers play with dangerous toys.\n\nTo the south, they are injecting local wildlife with pheromone-laden parasites, in an attempt to create monstrous mutations for war.\n\nCarelessly, they have allowed their parasitic worms to escape into the local ecosystem.\n\nLeft unchecked, the infection will spread from one animal to another, until we have an outbreak.\n\nI will inject you with a mild toxin. With it, you will be able to identify infected creatures.\n\nKill the carriers at once.", objectives = "Kill 6 infected wildlife. Infected wildlife may include Bonedust Moths, Bluehide Mushan, and Mutating Scorpid.", completion = "So the infection was spreading. You halted the spread just in time, it seems.\n\nI doubt that the genemancers will stop their outrageous experimentation, but we must continue to thwart their efforts." }
WordHunterWoW_QuestEN[31273] = { title = "Relics of the Swarm", description = "PH", objectives = "PH" }
WordHunterWoW_QuestEN[31274] = { title = "LFGDungeons - Mists - Raid Finder - 1st", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[31275] = { title = "LFGDungeons - Mists - Raid Finder - Nth", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[31277] = { title = "Surprise Attack!", description = "Those damnable Mogu...\n\nThose scouts were a distraction! While we were hunting their spies, the main force moved on Niuzao Temple. Corrupted serpents, Mogu everywhere... this is a disaster!\n\nThankfully, Ban was able to make it past their lines with the most elite members of our order. If you can slip past, too, meet up with him. We need to put a stop to this!", objectives = "Meet up with Ban Bearheart outside Niuzao Temple in Townlong Steppes, and put a stop to the Mogu Invasion there.", completion = "Niuzao has been saved. The Mogu pushed back. And you, friend, have been found worthy of a great honor. \n\nWe shall induct you into the Shado-Pan." }
WordHunterWoW_QuestEN[31278] = { title = "Figuring out how to make quests", description = "Whee!  You get to make a breadcrumb quest!  Now figure out what to do next.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Make a breadcrumb quest.Whee!  You get to make a breadcrumb quest!  Now figure out what to do next.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[31279] = { title = "Everything I Know About Cooking", description = "I'm so glad you enjoy my food. Are you interested in the recipes?  If so, you should learn them properly, from my teachers in Halfhill Market.  Everything I know about the kitchen, I learned from them.\n\nSay, if you happen to pass through there, would you deliver this note to Sungshin Ironpaw for me? She was my favorite teacher, and I want her to know that I miss her.", objectives = "Deliver the Letter to Sungshin Ironpaw. She teaches in Halfhill Market.", progress = "You have a letter for me?", completion = "My, that's so thoughtful. I love hearing from my old students." }
WordHunterWoW_QuestEN[31280] = { title = "Ways of Cooking", description = "There are many ways of cooking, and each creates dishes with unique properties. The Pandaren Ways of Cooking are the Ways of the Grill, the Wok, the Pot, the Steamer, the Oven and the Brew. You seem to already have the basics of each way, from your experience in faraway lands. If you wish to progress further, speak with my siblings and learn the first advanced recipe each of them teaches. Find out which Way suits you the best.You will receive:", objectives = "Learn the recipes for Charbroiled Tiger Steak, Jade Forest Fried Rice, Swirling Mist Soup, Shrimp Dumplings, Wildfowl Roast and Ginseng Tea from the masters in Halfhill Market." }
WordHunterWoW_QuestEN[31281] = { title = "So You Want to Be a Chef...", description = "You wish to be a chef? If you are dedicated, I can unlock your hidden potential, no matter how inexperienced you are.\n\nIf you wish to learn, show me you can at least follow basic instructions. Learn how to slice peaches and show me what you've learned.  I have fresh pandaren peaches which I will sell to you at a token price.", objectives = "Learn the recipe for Sliced Peaches from the Guide to the Ways and make 5 of them for her.", progress = "Show me that you can follow instructions.", completion = "Very well.  You are capable of learning.  There is much I can teach you, and I have most of the ingredients you need to learn. Train with me." }
WordHunterWoW_QuestEN[31282] = { title = "Kaz'tik Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[31283] = { title = "Theramore Destroyed Tracking", description = "", objectives = "" }
WordHunterWoW_QuestEN[31284] = { title = "FLAG - Ancient Pandaren Fishing Pole", description = "", objectives = "" }
WordHunterWoW_QuestEN[31285] = { title = "The Spring Drifter", description = "Nobody really travels up the Ancient Passage on foot. That is just asking for a faceful of saurok if you are not careful.\n\nTell you what, Egg Shell and I were just about to set off upriver to Binan Village. Want a lift?", objectives = "Survive a trip on the Spring Drifter.", progress = "It is always good luck to have a grummle aboard when traveling through a saurok infested cave.", completion = "Wheh, we made it. Welcome to Binan Village." }
WordHunterWoW_QuestEN[31286] = { title = "Robbing Robbers of Robbers", description = "Ah, a {class}. I could make good use of your skills.\n\nA convoy was struck just up the road by a band of marauding saurok. These marauders made off with some... merchandise... her ladyship, the Madam Goya, had a mind to sell.\n\nOne does not steal from her ladyship.\n\nIf you recover these items I will gladly provide you a finders fee.", objectives = "Recover 7 Black Market Merchandise.", progress = "Saurok are seldom this bold.", completion = "Ah, our merchandise. Madam Goya will be pleased. You have the gratitude of her ladyship." }
WordHunterWoW_QuestEN[31287] = { title = "Educating Saurok", description = "The Spring Road is under the protection of her ladyship, the esteemed Madam Goya.\n\nThe saurok of Hatescale Burrow northeast of here require \"education\" in this fact. We have warned them before but sadly they seem to have a very short memory.\n\nTravel northeast to this burrow and find their shaman leader. Eliminate him and you will have the gratitude of her ladyship. As well as an appropriate bounty.", objectives = "Defeat Leechfingers.", completion = "The deed is done and a debt must be paid. Here is your reward. You have our gratitude." }
WordHunterWoW_QuestEN[31288] = { title = "Research Project: The Mogu Dynasties", description = "Ah, an explorer. Just what I could use. I am on the verge of discovering the dark secrets of the mogu.\n\nNot all of the secrets, mind you. They kept a lot of dark secrets. But I am on the verge of discovering \"a\" secret at least.\n\nIf, in your travels, you come across some fragments of the mogu past, bring them to me and I will happily reimburse you for them.", objectives = "Obtain 20 Mogu Archaeology Fragments.", progress = "It is dangerous to forget our past.", completion = "Ah! Some fine pieces here. Very fine pieces indeed. My thanks, adventurer." }
WordHunterWoW_QuestEN[31289] = { title = "Research Project: The Pandaren Empire", description = "Ah, adventurer. You come at a most opportune time. My daughter and I are researching the history of our people and have hit a roadblock in our research.\n\nShould you come across fragments of the pandaren past, please, bring them to us here. We would benefit greatly from the additional information.", objectives = "Obtain 20 Pandaren Archaeology Fragments.", progress = "It is dangerous to forget our past.", completion = "Ah! Some fine pieces here. Very fine pieces indeed. My thanks, adventurer." }
WordHunterWoW_QuestEN[31291] = { title = "Uncovering the Past", description = "Interested in being a Lorewalker? There is lots of digging and reading and digging and more reading.\n\nI have entire days where I stare at a broken vase trying to figure out how it goes back together.\n\nShould give it a try. Go solve one artifact of Pandaria and we will appreciate you sharing the knowledge of how you did it.", objectives = "Solve 1 artifact from Pandaria.", progress = "I am beginning to wonder if I'll ever get the hang of this stuff.", completion = "Wow! You got the pieces to meld together so well. The quality of this restoration is amazing.\n\nHow did you do it?" }
WordHunterWoW_QuestEN[31292] = { title = "FLAG - Ancient Pandaren Woodcutter", description = "", objectives = "" }
WordHunterWoW_QuestEN[31293] = { title = "Mogu Make Poor House Guests", description = "Leven sent Rook here to stop mogu, but there are more than Rook can kill alone.\n\nYou help?  Rook will tell Leven you helped.  Promise.", objectives = "Kill 8 Shado-Tien attackers in Mistfall Village.", completion = "Rook can handle rest of mogu.  Thanks for help.  Good man." }
WordHunterWoW_QuestEN[31294] = { title = "The Ruins of Guo-Lai", description = "I have my heartfelt thanks for your continued aid. Anji awaits at the Ruins of Guo-Lai to northwest.\n\nGo with courage in your heart, young {class}.", objectives = "Speak to Angi Autumnlight at the Ruins of Guo-Lai.I have my heartfelt thanks for your continued aid. Anji awaits at the Ruins of Guo-Lai to northwest.\n\nGo with courage in your heart, young <class>.", completion = "Che sent you my way, did he?  Good to have you.\n\nThe ruins are crawling with things to be squashed." }
WordHunterWoW_QuestEN[31295] = { title = "Mogu within the Ruins of Guo-Lai", description = "Thank you for your help, {class}.\n\nI would enjoy your company for longer, but Leven is leading an attack on the mogu within the Ruins of Guo-Lai to the northwest, and awaits your capable hands.\n\nMay the celestials protect you, young one.", objectives = "Speak to Leven Dawnblade at the Ruins of Guo-Lai.Thank you for your help, <class>.\n\nI would enjoy your company for longer, but Leven is leading an attack on the mogu within the Ruins of Guo-Lai to the northwest, and awaits your capable hands.\n\nMay the celestials protect you, young one.", completion = "Good to see you.\n\nI don't know where the mogu mustered all these forces, but we need to hit them hard before they can push their advantage." }
WordHunterWoW_QuestEN[31296] = { title = "The Ruins of Guo-Lai", description = "The villagers seem to be safe and the mogu are losing their foothold. We should be able to handle the rest from here. Thank you for your kind aid, {name}.\n\nAnji lead a group to investigate and clear out the Ruins of Guo-Lai to the northwest this morning. I am certain she would appreciate someone as capable as yourself. You should go to her.", objectives = "Speak to Anji Autumnlight at the Ruins of Guo-Lai.The villagers seem to be safe and the mogu are losing their foothold. We should be able to handle the rest from here. Thank you for your kind aid, <name>.\n\nAnji lead a group to investigate and clear out the Ruins of Guo-Lai to the northwest this morning. I am certain she would appreciate someone as capable as yourself. You should go to her.", completion = "Sun is smart to send me the strong ones.  I'd accept nothing else." }
WordHunterWoW_QuestEN[31297] = { title = "Setting Sun Garrison", description = "The mogu will not be able to maintain this attack much longer. We should be able to handle it here, thanks to your kind aid.\n\nMight you be willing to find Anji at the Setting Sun Training Camp to the west? She's been tasked with preparing fresh-faced pandaren to aid the cause. You could show them a thing or two as well, I imagine.", objectives = "Speak to Anji Autumnlight at the Setting Sun Training Camp.", completion = "You I can work with. Let's show these trainees a thing or two about how a real <class> fights." }
WordHunterWoW_QuestEN[31298] = { title = "Zouchin Village - Intro Tracking", description = "", objectives = "" }
WordHunterWoW_QuestEN[31299] = { title = "Shomi Ruins Tracking", description = "", objectives = "" }
WordHunterWoW_QuestEN[31300] = { title = "Shomi Beach Tracking", description = "", objectives = "" }
WordHunterWoW_QuestEN[31301] = { title = "Shomi Strand Tracking", description = "", objectives = "" }
WordHunterWoW_QuestEN[31302] = { title = "Ready for Greatness", description = "You seem to know your way around the kitchen. Demonstrate to me your skills and make me 5 bowls of rice pudding.", objectives = "Make 5 Rice Pudding and give them to the Guide to the Ways.", progress = "I believe you have the potential to be a great chef, but the proof is in the pudding, so to speak.", completion = "You are ready. You are now a zen master cook." }
WordHunterWoW_QuestEN[31303] = { title = "The Seal is Broken", description = "<Cho looks at you in disbelief.>\n\nI... I thought Sha of this immensity were a myth - we all did. Just a story to keep our children from fighting.\n\nNo time to talk now. Those fissures - they're feeding it... it grows stronger by the moment!\n\nI must research the scrolls from my family archives. You, take this cannon and ride Mishi.\n\nYou must find a way to contain this horror that has been unleashed! ", objectives = "Seal 12 Sha Fissures to banish the Sha of Doubt.", completion = "I have much research to do in very little time.\n\nThe emperor's message only warned of the unique threat war would bring to our land - this... Sha.\n\nSadly, the time to heed his message has passed. And as for how to bring an end to the crisis, the Emperor's Omen is silent." }
WordHunterWoW_QuestEN[31304] = { title = "FLAG - Kafa Press", description = "", objectives = "" }
WordHunterWoW_QuestEN[31305] = { title = "The Way of the Grill", description = "If you wish to cook foods that make you stronger, go seek the Master of the Grill.  Cook him a skewered peanut chicken to show him that you have the basics.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Make a Skewered Peanut Chicken and give it to the Master of the Grill." }
WordHunterWoW_QuestEN[31306] = { title = "Seeker's Folly", description = "I'm sure your pandaren friend has some ideas about what the mogu are after.\n\nHe headed up the mountain a few days ago without a guide, and asked that only you be sent up after him. He was very specific:\n\n\"The {class} must endure the trek alone, with only his thoughts. He will honor each shrine before meeting me at the top.\"\n\nThe path is just northwest of the camp, marked by flags. Please be careful! Seeker's Folly is a dangerous trek even on a lucky day.", objectives = "Brave the path of Seeker's Folly to find Lorewalker Cho, stopping to reflect at the three shrines along the way.", completion = "Ah, you made it, and you honored the shrines.\n\nI knew you could handle it." }
WordHunterWoW_QuestEN[31307] = { title = "FLAG - Jade Infused Blade", description = "", objectives = "" }
WordHunterWoW_QuestEN[31308] = { title = "Learning the Ropes", description = "Now that you are a pet trainer, it's time to test your skills!\n\nHead out into the forest and pick a fight with a battle pet.  Make sure to use your Track Pets skill so you can see pets you can fight on the minimap.  Come back to me after you have won and I will continue your training. Good luck!", objectives = "Win a pet battle.", completion = "Nice work, <name>!  You're better with those pets than I thought!" }
WordHunterWoW_QuestEN[31309] = { title = "On The Mend", description = "Now that you have won a battle, we need to heal up your pets so they can fight another day!  Visit Erma, our local stable master, to heal and revive your pets.", objectives = "Heal your pets to full health by visiting Erma the Stable Master.", progress = "Are your pets feeling better?", completion = "Now those look like some healthy pets, <name>.  Remember, you can heal and revive your entire collection of pets at any time by visiting a stable master." }
WordHunterWoW_QuestEN[31310] = { title = "Interrogation Tracking", description = "", objectives = "" }
WordHunterWoW_QuestEN[31311] = { title = "Way of the Grill", description = "The Pandaren Way of the Grill produces foods that increase your physical strength. Bring some raw tiger steaks to the Master of the Grill, and he will teach you what you can do with them. There are many tigers in the Jade Forest and the Krasarang Wilds, but you can also find them in other places.", objectives = "Bring 5 Raw Tiger Steaks to the Master of the Grill.", progress = "If you wish to learn the Way of the Grill, bring me some raw tiger steaks.", completion = "Good cuts." }
WordHunterWoW_QuestEN[31312] = { title = "The Old Map", description = "The old, faded leather is falling apart, but still legible.\n\nScrawled on it is some kind of map, and the following lines:\n\n\nDeep in the valley where four winds blow,\nThe maiden laughs behind her golden fan.\nAt the feet of her ancestors' stair,\nShe whispers secrets into the echoing dark.", objectives = "Show the map to Fish Fellreed at Cattail Lake or Halfhill Market in the Valley of the Four Winds.\n\nProvided item:", completion = "Whoa! I think you found it, <name>! You found the map to Old Man Thistle treasure!" }
WordHunterWoW_QuestEN[31313] = { title = "Just A Folk Story", description = "What!?! This don't make any sense! <Fish's face falls.>\n\nWhat's this mumber jumber about a maiden and an ancestor and a buncha stairs?\n\nI can't make any reason outta this, can you?\n\nWell, there are lotsa folks 'round here who're much older than you and me, {name}.\n\nCan you go talk to the folks in Halfhill? I betcha they might know somethin'! ", objectives = "Speak to Grainsorter Pei, Stonecarver Mac, Mama Min, and Old Man Whitewhiskers.", completion = "Of course! It makes perfect sense. So the location of the treasure must be where the lake meets the mountains!" }
WordHunterWoW_QuestEN[31314] = { title = "Old Man Thistle's Treasure", description = "Well high golly! This is turning into a real life treasure hunt!\n\nThere's gotta be some kind of entrance or opening to the north, where the mountains meet Cattail Lake.\n\nI'll meet ya at the entrance! Let's go get that treasure!", objectives = "Find the cave entrance and recover Old Man Thistle's hidden treasure.", progress = "If I weren't seeing it fer myself, I could hardly believe it!", completion = "The chest's lid slides off with the lightest touch. You peer inside..." }
WordHunterWoW_QuestEN[31315] = { title = "The Heartland Legacy", description = "At the very bottom of the treasure chest, you find a stack of scrolls and a soft leather sack with seeds.\n\nUnrolling the scrolls, you see they contain detailed farming notes, drawings of plants, numbers and calculations, locations of nearby water springs, and countless other snippets.\n\nThere might be someone at the Tillers Union who would like to see this.", objectives = "Take Old Man Thistle's Almanac to Seedkeeper Shing Sing at Halfhill in the Valley of the Four Winds.", progress = "What do you have there?", completion = "Ah yes, I know the story of Old Man Thistle quite well, <race>.\n\nThere are all sorts of crazy tales about his quest for treasure.\n\nBut the truth of the matter is that he was a bit of a recluse, a bit eccentric, and an excellent farmer.\n\nAs he grew near the end of his life, he retreated up into the mountains and was never seen again.\n\nHe was just a man, and it seems that you have found his legacy.\n\nBut don't tell Fish the truth. Some stories are best left tall in the telling." }
WordHunterWoW_QuestEN[31316] = { title = "Julia, The Pet Tamer", description = "I can tell you have been honing your pet battle skills, {name}.  I think it's time for you to take on a real challenge.\n\nJulia Stevens can be found at the Maclure Vineyards south of Stormwind.  She is an up and coming wild pet tamer and I think it's time you faced her in battle!", objectives = "Defeat Julia Stevens in a pet battle.", progress = "How is your team coming along? I have two snakes so far!", completion = "You're better with those pets than I thought!" }
WordHunterWoW_QuestEN[31317] = { title = "Tracking Event: Found Entrance", description = "", objectives = "" }
WordHunterWoW_QuestEN[31318] = { title = "Tracking Event: Found Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[31319] = { title = "Emergency Response", description = "Your companions have made themselves at home in our land, and brought with them a dangerous conflict.\n\nThe full extent of their destruction here we cannot yet know. Already it is... unspeakable.\n\nNevertheless, to forsake your friends out of spite would be against our way. Any that yet live are doubtlessly wounded and in desperate need of care.\n\nThese fireworks were to celebrate the statue's completion. Use them near your companions to signal Mishi, and she will bear them off to safety.", objectives = "Use Cho's Fireworks near Admiral Taylor, Mishka and Sully.", completion = "My thoughts will be with your fallen companions, traveler.\n\nMay their wounds mend well." }
WordHunterWoW_QuestEN[31320] = { title = "Buy A Fish A Drink?", description = "Heeeey buddy, how'sh it goin'? You wanna buy a jinyu a drink?", objectives = "Bring 1 Four Wind Soju to Jogu the Drunk. Four Wind Soju can be purchased from most bartenders in Pandaria.", progress = "Thirsty...", completion = "Thanksh, buddy." }
WordHunterWoW_QuestEN[31321] = { title = "Buy A Fish A Round?", description = "Heeeey it's my friend, the {race}!\n\nI guesh you've seen me hanging 'round, but I should 'splain that I'm not drunk.\n\nI mean, look at me now! Shober as a freshwater fish!\n\nSure I like to drown my sorrowsh in some good brew now and then, but you can't inebriate a jinyu! Might as well try to drown a fish!\n\nNo, the brewsh make me shleepy, and when I shleep, I have vishions of the future.\n\n\n\nThe shtronger the brew, the more potent my dreamsh! If you bring me a drink, I'll owe you one.", objectives = "Bring 5 Pandaren Plum Wine to Jogu the Drunk. Pandaren Plum Wine can be purchased from most bartenders in Pandaria.", progress = "What do you mean I talk like I'm drunk? Thish ish how I shpeak!", completion = "Oooh, this is the shtuff." }
WordHunterWoW_QuestEN[31322] = { title = "Buy A Fish A Keg?", description = "My dreams grow dim recently, {race}.\n\nI need something powerful to kick myshelf back into gear!\n\nI heard there'sh a delishush drink that folksh are making nowadays.\n\nIt'sh called Jade Witch Brew.\n\nI'd sure like to taste some.", objectives = "Bring 10 Jade Witch Brew to Jogu the Drunk. Jade Witch Brew can be made using the cooking profession.", progress = "Any luck?", completion = "Oooh, that'sh got quite the kick! I'm growing shleepy..." }
WordHunterWoW_QuestEN[31323] = { title = "Buy A Fish A Brewery?", description = "All right, {name}, in order to continue my vishions, I must now have my own brewery.\n\n...\n\nJust kidding! You should have sheen your own face! Hilarioush... hic!\n\nAnyway, I heard of a new drink that is unlike any other, and I would like a tashte.\n\nHave you heard of the Mad Brewer'sh Breakfasht? If you can bring me some of thish shtuff, you will be my friend for life.", objectives = "Bring 20 Mad Brewer's Breakfast to Jogu the Drunk. Mad Brewer's Breakfasts can be made using the cooking profession.", progress = "Have you tried it?", completion = "Thank you, <name>! I will be shaving these for a rainy day... hic!" }
WordHunterWoW_QuestEN[31324] = { title = "Family Secrets", description = "Our secret recipes! I was gathering them up. But then... hozen?\n\n<Auntie looks very confused.>\n\nHow is Gao to brew anything? He needs those recipes or disaster is sure to strike!", objectives = "Collect 5 Stormstout Secrets.", progress = "Well, hello!", completion = "Ho ho, what's this?\n\n<Uncle Gao jiggles his fat brew belly at the sight of the family's recipes.>\n\nOoh, I knew I was adding too much corn!" }
WordHunterWoW_QuestEN[31325] = { title = "A Very Nice Necklace", description = "The beautiful necklace is only partly smudged by dirty hozen hands.\n\nThere's only one person in the Valley who would own such a beautiful piece of jewelry.", objectives = "Bring the necklace to Tina Mudclaw at Haohan's House or Halfhill Market in the Valley of the Four Winds.\n\nProvided item:", completion = "Oh my, this is my favorite necklace! I didn't even know it was missing! Thank you, <name>." }
WordHunterWoW_QuestEN[31326] = { title = "Tina's Tasteful Tiara", description = "It's a dazzling diamond tiara. Who in the valley would be wealthy enough to own such a piece of jewelry?\n\nWhoever it is, they might be willing to give a nice reward.", objectives = "Bring the Tasteful Tiara to Tina Mudclaw at Haohan's House or Halfhill Market in the Valley of the Four Winds.\n\nProvided item:", completion = "Oh, my tiara! It was missing, but wherever did you find it?" }
WordHunterWoW_QuestEN[31327] = { title = "Trouble Brewing", description = "With the brewery infested by hozen and... and who knows what else, I'm sure that the brewers are in trouble.\n\nWould you mind helping me find out what's going on, my friend?", objectives = "Kill Yan-Zhu the Uncasked.", completion = "A giant creature made of brew?! Who could have imagined such a thing?\n\nYou have my thanks for saving Gao from his own misguided brewing experiments." }
WordHunterWoW_QuestEN[31328] = { title = "An Exquisite Earring", description = "You unhook the earring off the furry creature's ear. It looks like he was having some fun wearing the dangly hoop. TOO much fun.\n\nPerhaps the owner of this dainty bauble would like to see it returned. You don't have to tell her where you found it... or who was wearing it.", objectives = "Bring the Exquisite Earring to Tina Mudclaw at Haohan's House or Halfhill Market in the Valley of the Four Winds.\n\nProvided item:", completion = "Oh my earring! Why, it matches the one I'm wearing today!\n\n<Tina hooks the earring onto her ear.>\n\nThank you, <name>!" }
WordHunterWoW_QuestEN[31329] = { title = "A Beautiful Brooch", description = "It is a very old, antique brooch with very detailed molding and filigree worked into the edges. It looks very valuable.\n\nThere's only one person who keeps losing jewelry to furry hooligans, and she would probably want to see this heirloom returned.", objectives = "Bring the Beautiful Brooch to Tina Mudclaw at Haohan's House or Halfhill Market in the Valley of the Four Winds.\n\nProvided item:", completion = "My grandmother's brooch! Oh, thank you for finding this! It's a family treasure." }
WordHunterWoW_QuestEN[31331] = { title = "Figuring out how to make quests", description = "Whee!  You get to make a breadcrumb quest!  Now figure out what to do next.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Make a breadcrumb quest.Whee!  You get to make a breadcrumb quest!  Now figure out what to do next.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[31332] = { title = "Lesson 1: Sliced Peaches", description = "I'm excited to start my training. We start with sliced peaches, right?", objectives = "Obtain a 5 Pandaren Peaches for Nomi's cooking lesson.", progress = "I really want to be a chef, but the other kids already started a couple of months ago. There's no way I can catch up without your help.", completion = "Here it is!  How did I do?" }
WordHunterWoW_QuestEN[31333] = { title = "Lesson 2: Instant Noodles", description = "Instant noodles aren't that hard to cook, right?", objectives = "Obtain 5 Instant Noodles for Nomi's Lesson.", progress = "It's so easy to overcook the noodles!", completion = "Here it is!  How did I do?" }
WordHunterWoW_QuestEN[31334] = { title = "Lesson 3: Toasted Fish Jerky", description = "Cooking is harder than I thought.  It's so easy to burn things.", objectives = "Obtain 5 Golden Carp for Nomi's Lesson.", progress = "I hope I don't burn myself.  Eep.", completion = "Here it is!  How did I do?" }
WordHunterWoW_QuestEN[31335] = { title = "Lesson 4: Dried Needle Mushrooms", description = "I'm not very fond of mushrooms... but I'll do my best to learn.", objectives = "Obtain 5 Needle Mushrooms for Nomi's Lesson.", progress = "Ick.", completion = "Here it is!  How did I do?" }
WordHunterWoW_QuestEN[31336] = { title = "Lesson 5: Pounded Rice Cake", description = "I love rice cakes.  I'll do my best to make good ones!", objectives = "Obtain 5 Rice for Nomi's Lesson.", progress = "I can't wait to see how they turn out!", completion = "Here it is!  How did I do?" }
WordHunterWoW_QuestEN[31337] = { title = "A Token of Appreciation", description = "Thanks for checking to make sure I'm doing well!  I've been able to help out the Ironpaws today, and they said I could give this to you.", objectives = "Receive Nomi's gift.Thanks for checking to make sure I'm doing well!  I've been able to help out the Ironpaws today, and they said I could give this to you.", completion = "You're my favorite teacher ever." }
WordHunterWoW_QuestEN[31338] = { title = "Lost Sheepie", description = "Chee Chee's prize sheep, Sheepie, is missing!\n\nThat bad sheep is always wandering off the farm.\n\nStupid sheep! I looked everywhere and couldn't find him.\n\nCan you help me, {race}?", objectives = "Find Sheepie and return him to Chee Chee.", progress = "Did you find my Sheepie? Oh, I was so worried.", completion = "Oh, you found him! Thank you!" }
WordHunterWoW_QuestEN[31339] = { title = "Lost Sheepie... Again", description = "That stupid sheep! He wandered off again!\n\nCan you find him for me again?", objectives = "Find Sheepie and bring him back to Chee Chee.", progress = "Oh, poor Sheepie. He's probably so scared and alone...", completion = "Sheepie, you make me so worried! Bad sheep! Chee Chee was so worried about you!" }
WordHunterWoW_QuestEN[31340] = { title = "Oh Sheepie...", description = "Sigh... you guessed it... Sheepie is gone... AGAIN.\n\nStupid sheep! Gives me so much trouble!\n\nI hate to ask you again, but I promise this will be the last time.\n\nCan you find him for me?", objectives = "Find Sheepie.", completion = "What? Sheepie is... gone?\n\n<Chee Chee's lip begins to quiver.>" }
WordHunterWoW_QuestEN[31341] = { title = "A Wolf In Sheep's Clothing", description = "AAAIIIIEEUUGGHHHH!!!! This is the last straw!\n\nThose stupid hozen on the mountain killed my SHEEPIE!\n\nI know exactly who did this, and it is time for REVENGE.\n\nIf you are willing to help me, take this old sheepskin.\n\nUse it to disguise yourself anywhere on the mountain to the north, wait for that little dooker Krungko to come out of hiding, and then break his bones!", objectives = "Use the old sheepskin anywhere in the Skyrange or Kunzen Village, then kill Krungko.", completion = "Thank you, <name>. It will not bring my Sheepie back, but at least this way, no more sheep will be lost." }
WordHunterWoW_QuestEN[31342] = { title = "The Path to Respect Lies in Violence", description = "You have proven yourself in battle.\n\nStill, if you would aid us further, I must ask something else of you.\n\nThe Sha of Violence awaits beyond within the Sealed Chambers. Destroy it if you would earn my respect.", objectives = "Kill the Sha of Violence.", completion = "You have defeated the Sha of Violence and saved the monastery. You have my respect.\n\nPerhaps we were wrong about your people, <name>." }
WordHunterWoW_QuestEN[31343] = { title = "Kovok Tracking", description = "", objectives = "" }
WordHunterWoW_QuestEN[31344] = { title = "Tracking Event: Chee Chee Exalted", description = "", objectives = "" }
WordHunterWoW_QuestEN[31345] = { title = "Tracking Event: Ella Exalted", description = "", objectives = "" }
WordHunterWoW_QuestEN[31346] = { title = "Tracking Event: Farmer Fung Exalted", description = "", objectives = "" }
WordHunterWoW_QuestEN[31347] = { title = "Tracking Event: Fish Fellreed Exalted", description = "", objectives = "" }
WordHunterWoW_QuestEN[31348] = { title = "Tracking Event: Gina Mudclaw Exalted", description = "", objectives = "" }
WordHunterWoW_QuestEN[31349] = { title = "Tracking Event: Haohan Mudclaw Exalted", description = "", objectives = "" }
WordHunterWoW_QuestEN[31350] = { title = "Tracking Event: Jogu the Drunk Exalted", description = "", objectives = "" }
WordHunterWoW_QuestEN[31351] = { title = "Tracking Event: Old Hillpaw Exalted", description = "", objectives = "" }
WordHunterWoW_QuestEN[31352] = { title = "Tracking Event: Sho Exalted", description = "", objectives = "" }
WordHunterWoW_QuestEN[31353] = { title = "Tracking Event: Tina Mudclaw Exalted", description = "", objectives = "" }
WordHunterWoW_QuestEN[31354] = { title = "Mazu's Bounty", description = "That was some amazing work you and the captain did out there, {name}! It's an honor to have you on the crew.\n\nOh! And Ju Lien survived! He swam ashore just after you started letting the harpoons fly. He was raving about some kind of gigantic egg or something that washed in with Jiao.\n\nGo check up on him, will you? He's probably hauled it out of the water by now.", objectives = "Speak with Master Angler Ju Lien in Soggy's Gamble.", completion = "Hey there!\n\nOh, I'm fine. I've had worse spills than that after a night at the Chum Bucket.\n\nBut would you look at this thing? I spotted it peeking out of the sea floor when I went under - Jiao must have dredged it up while he was thrashing around.\n\nNot really sure what to do with it, but it looks valuable. Seeing as how you pretty much saved all our hides, I think we owe you this catch." }
WordHunterWoW_QuestEN[31355] = { title = "Restoring Jade's Purity", description = "{class}, will you aid us?\n\nThe temple's purity has been jeopardized. Even now the three masters struggle against their doubts.\n\nPlease, I beg you, head in and help Wise Mari, Liu Flameheart, and Lorewalker Stonestep in their fight against the sha.", objectives = "Assist Wise Mari, Liu Flameheart, and Lorewalker Stonestep with their sha problems.", progress = "Please, you must assist those within before they succumb to their doubts.", completion = "While I am sad to hear the fates of Wise Mari and Priestess Flameheart, you have my heartfelt thanks." }
WordHunterWoW_QuestEN[31356] = { title = "Deep Doubts, Deep Wisdom", description = "There is an ancient pandaren saying that states, \"With deep doubts comes deep wisdom.\"\n\nThe Sha of Doubt has infested the Heart of Jade within the temple. It must be destroyed.\n\nI dare say that you are about to become all the wiser, {class}.", objectives = "Kill the Sha of Doubt.", progress = "The Sha of Doubt must be destroyed, <name>, or we are all lost.", completion = "I never doubted you. Funny though, you don't look any wiser.\n\n<The master winks.>" }
WordHunterWoW_QuestEN[31357] = { title = "Relics of the Four Kings", description = "The mogu have reawakened and are a threat to all of Pandaria. They are on the cusp of becoming even more dangerous.\n\nThere are four great mogu kings of legend: Zian of the Endless Shadow, Meng the Demented, Qiang the Merciless, and Subetai the Swift. Four artifacts of these kings are secreted away in the Vault of Kings Past, below.\n\nYou must retrieve these relics before the mogu discover them and become unstoppable.", objectives = "Collect the Lantern of the Sorcerer King, Mad King Meng's Balance, Qiang's \"The Science of War\", and Subetai's Bow of the Swift.", progress = "We must retrieve the lantern, balance, scroll, and bow before Xin and his clans uncover them.", completion = "I will find a better hiding place for the four relics.\n\nPandaria is indebted to you, <name>." }
WordHunterWoW_QuestEN[31359] = { title = "The Kunchong Whisperer", description = "To really connect with Kovok you need to challenge him mentally and physically. You must respect his strength and intelligence; only then will he allow you to really train him.\n\nThe muckscale tribe may provide an adequate test of his abilities and with you there he shouldn't be in danger.\n\nAdditionally, this will allow us to decrease their numbers in the Briny Muck.", objectives = "Kill Oracle Hiss'ir and 10 Muckscale tribe members.", completion = "I am most impressed with your progress, Wakener. Kovok's training is coming along nicely and he seems to be fond of you.\n\nI have no doubt that you are the best choice to assist me in training him." }
WordHunterWoW_QuestEN[31360] = { title = "A New Lesson for the Master", description = "A new king of the mogu has arisen: Xin the Weaponmaster.\n\nHe single-handedly subjugated the mogu clans, and now they and their new leaders vie for his favor.\n\nI've never seen or read of any who are his equal in battle. Do not underestimate Xin, {name}.\n\nOur fate rests in your hands.", objectives = "Kill Xin the Weaponmaster.", progress = "The king of the mogu must die.\n\nThough another will eventually rise, none are as deadly as Xin the Weaponmaster.", completion = "Truly a fight for the ages.\n\nI'm glad that you're on our side, <name>." }
WordHunterWoW_QuestEN[31362] = { title = "Last Piece of the Puzzle", description = "I must say, {name}, despite their skirmishes with the hozen, I've never seen the jinyu so militant.\n\nThis troubles me. We must discuss it another time, however. I have come to ask for your assistance.\n\nThe fresco, where last we spoke, is nearly unveiled. I am certain that it holds ancient wisdom - knowledge that the emperor would have us remember.\n\nMy meditations alone may not be enough to discern its meaning. Please, take this heirloom to the shrine of my ancestors. I shall require their assistance.\n\n", objectives = "Use Cho's Heirloom at Cho's Family Shrine on Serpent's Overlook.\n\nSpeak with Mishi for transportation.", progress = "Yes, <class>?", completion = "<Lorewalker Cho shudders, in spite of himself.>\n\nThe legends... they're true!" }
WordHunterWoW_QuestEN[31363] = { title = "Lighting the Way", description = "We need reinforcements! Someone has to fight through and light the signal flame.\n\nIt's all up to you, {class}. No pressure or anything.", objectives = "Light the Signal Flame.", progress = "<name>, you need to get out there and signal the reinforcements!", completion = "Outstanding, <name>. Your timing couldn't have been better!" }
WordHunterWoW_QuestEN[31364] = { title = "That's a Big Bug!", description = "The mantid have something they call Raigonn. It's a giant bug they're using to bust down the wall's gates!\n\nLet's keep that thing from getting into the vale!", objectives = "Kill Raigonn.", progress = "You need to bring that thing down before it busts through the final gate!", completion = "If I didn't see it with my own eyes, I wouldn't have believed it.\n\nGreat job, <name>!" }
WordHunterWoW_QuestEN[31365] = { title = "Somewhere Inside", description = "I sent a dozen of my best men ahead to infiltrate the mantid siege.\n\nNone have returned.\n\nSince you are taking the fight directly to the mantid, you will be in a position to free any who had the misfortune to be captured.\n\nYou will do this?", objectives = "Rescue 12 Shado-Pan Prisoners.", progress = "My men are being held somewhere amongst the mantid siege.", completion = "Thirteen thanks I give to you; twelve for those you rescued and my own as well.\n\nHere's something else I give to you in gratitude." }
WordHunterWoW_QuestEN[31366] = { title = "Take Down the Wing Leader", description = "The mantid have lain siege to Niuzao Temple.\n\nEven now, Wing Leader Ner'onok and his forces work to cross the final chasm.\n\nYou must stop him before they reconstruct that bridge.", objectives = "Kill Wing Leader Ner'onok.", progress = "Hurry, <class>, the construction of the mantid bridge nears completion.", completion = "The wing leader lies dead and the siege is broken.\n\nYou've saved the temple, <name>." }
WordHunterWoW_QuestEN[31367] = { title = "The Lorewalkers", description = "So you are interested in learning more of the lore of this land?\n\nVery well! You should speak to Lorewalker Cho at the Seat of Knowledge.\n\nHe can be found in the room above the entrance to the Mogu'shan Palace. Speak with Mishi for a ride.", objectives = "Speak to Lorewalker Cho at the Seat of Knowledge in the Vale of Eternal Blossoms.", progress = "Welcome, traveler.", completion = "Ah yes, I can see by your face that you are an eager seeker of stories. You have come to the right place." }
WordHunterWoW_QuestEN[31368] = { title = "The Lorewalkers", description = "So you are interested in learning more of the lore of this land?\n\nVery well! You should speak to Lorewalker Cho at the Seat of Knowledge.\n\nHe can be found in the room above the entrance to the Mogu'shan Palace. Speak with Mishi for a ride.", objectives = "Speak to Lorewalker Cho at the Seat of Knowledge in the Vale of Eternal Blossoms.", progress = "Welcome, traveler.", completion = "Ah yes, I can see by your face that you are an eager seeker of stories. You have come to the right place." }
WordHunterWoW_QuestEN[31369] = { title = "The Anglers", description = "If you want to explore all the secrets of the deep ocean, and catch some big fish, speak to Haito at the Anglers Wharf in Krasarang Wilds.\n\nI'm sure he'd love to show you a thing or two about reeling!", objectives = "Speak to Fisherman Haito at the Anglers Wharf in the Krasarang Wilds.", completion = "You ready to catch some FISH?" }
WordHunterWoW_QuestEN[31370] = { title = "The Anglers", description = "If you want to explore all the secrets of the deep ocean, and catch some big fish, speak to Haito at the Anglers Wharf in Krasarang Wilds.\n\nI'm sure he'd love to show you a thing or two about reeling!", objectives = "Speak to Fisherman Haito at the Anglers Wharf in the Krasarang Wilds.", completion = "You ready to catch some FISH?" }
WordHunterWoW_QuestEN[31371] = { title = "Tracking Event: Player Has Completed One Anglers Daily", description = "", objectives = "" }
WordHunterWoW_QuestEN[31372] = { title = "The Tillers", description = "The Tillers do their business at Halfhill in the Valley of the Four Winds.\n\nIf you're interested in getting started, I hear there's a new farmer in town by the name of Farmer Yoon.\n\nI betcha he'll be looking for help.", objectives = "Speak to Farmer Yoon at Sunsong Ranch in the Valley of the Four Winds.", completion = "You arrived just in time!" }
WordHunterWoW_QuestEN[31373] = { title = "The Order of the Cloud Serpent", description = "The Order of the Cloud Serpent is always searching for talented riders.\n\nIf you wish to follow our way, you should speak to Instructor Skythorn at The Arboretum in the Jade Forest.\n\nI wish you luck, {race}.", objectives = "Speak to Instructor Skythorn at The Arboretum in The Jade Forest.", completion = "Ah, have you come to join the Order?" }
WordHunterWoW_QuestEN[31374] = { title = "The Tillers", description = "The Tillers do their business at Halfhill in the Valley of the Four Winds.\n\nIf you're interested in getting started, I hear there's a new farmer in town by the name of Farmer Yoon.\n\nI betcha he'll be looking for help.", objectives = "Speak to Farmer Yoon at Sunsong Ranch in the Valley of the Four Winds.", completion = "You arrived just in time!" }
WordHunterWoW_QuestEN[31375] = { title = "The Order of the Cloud Serpent", description = "The Order of the Cloud Serpent is always searching for talented riders.\n\nIf you wish to follow our way, you should speak to Instructor Skythorn at The Arboretum in the Jade Forest.\n\nI wish you luck, {race}.", objectives = "Speak to Instructor Skythorn at The Arboretum in The Jade Forest.", completion = "Ah, have you come to join the Order?" }
WordHunterWoW_QuestEN[31376] = { title = "Attack At The Temple of the Jade Serpent", description = "Darkness enshrouds the Temple of the Jade Serpent, and Yu'Lon's priests beseech us for aid.\n\nThey hold the sha in check, but just barely.\n\nYou may be able to turn the tide, {class}.", objectives = "Speak to Elder Sage Tai-Feng at the Jade Temple Grounds in The Jade Forest.", completion = "You've arrived just in time, <class>." }
WordHunterWoW_QuestEN[31377] = { title = "Attack At The Temple of the Jade Serpent", description = "Darkness enshrouds the Temple of the Jade Serpent, and Yu'Lon's priests beseech us for aid.\n\nThey hold the sha in check, but just barely.\n\nYou may be able to turn the tide, {class}.", objectives = "Speak to Elder Sage Tai-Feng at the Jade Temple Grounds in The Jade Forest.", completion = "You've arrived just in time, <class>." }
WordHunterWoW_QuestEN[31378] = { title = "Challenge At The Temple of the Red Crane", description = "The Temple of the Red Crane still reels from the aftermath of the sha's presence, and has only recently gathered to rebuild and retrain its warriors.\n\nIf you wish to help at the temple, speak to Thelonius at the Cradle of Chi-Ji.", objectives = "Speak to Thelonius at the Cradle of Chi-Ji in the Krasarang Wilds.", completion = "Welcome, <class>." }
WordHunterWoW_QuestEN[31379] = { title = "Challenge At The Temple of the Red Crane", description = "The Temple of the Red Crane still reels from the aftermath of the sha's presence, and has only recently gathered to rebuild and retrain its warriors.\n\nIf you wish to help at the temple, speak to Thelonius at the Cradle of Chi-Ji.", objectives = "Speak to Thelonius at the Cradle of Chi-Ji in the Krasarang Wilds.", completion = "Welcome, <class>." }
WordHunterWoW_QuestEN[31380] = { title = "Trial At The Temple of the White Tiger", description = "Xuen, the great Celestial of the North, seeks the greatest champions in the land.\n\nToday, he holds trials of battle at his temple in Kun-Lai Summit.\n\nIf you wish to test yourself against skilled fighters from all across Pandaria, then go to him and enter the challenger's ring!", objectives = "Speak to Xuen at the Temple of the White Tiger in Kun-Lai Summit.", completion = "So you wish to test your skills? Very good, <race>." }
WordHunterWoW_QuestEN[31381] = { title = "Trial At The Temple of the White Tiger", description = "Xuen, the great Celestial of the North, seeks the greatest champions in the land.\n\nToday, he holds trials of battle at his temple in Kun-Lai Summit.\n\nIf you wish to test yourself against skilled fighters from all across Pandaria, then go to him and enter the challenger's ring!", objectives = "Speak to Xuen at the Temple of the White Tiger in Kun-Lai Summit.", completion = "So you wish to test your skills? Very good, <race>." }
WordHunterWoW_QuestEN[31382] = { title = "Defense At Niuzao Temple", description = "Niuzao Temple, far to the west, is under attack by the mantid.\n\nThe great Celestial holds them back for now, but he cannot stand alone forever.\n\nGo and help the defenders, {class}. The Temple must not fall!", objectives = "Speak to Ogo the Elder at Niuzao Temple in the Townlong Steppes.", completion = "Well met, <class>! We need your help." }
WordHunterWoW_QuestEN[31383] = { title = "Defense At Niuzao Temple", description = "Niuzao Temple, far to the west, is under attack by the mantid.\n\nThe great Celestial holds them back for now, but he cannot stand alone forever.\n\nGo and help the defenders, {class}. The Temple must not fall!", objectives = "Speak to Ogo the Elder at Niuzao Temple in the Townlong Steppes.", completion = "Well met, <class>! We need your help." }
WordHunterWoW_QuestEN[31384] = { title = "The Golden Lotus", description = "The Golden Lotus have guarded the Vale for centuries, keeping it safe and hidden from harm.\n\nRecent events have unleashed terrible horrors upon our sacred vale, but allies of the Golden Lotus still stand against them, attempting to bring peace.\n\nIf you wish to help, you had best join them at the Setting Sun Garrison.", objectives = "Speak to Anji Autumnlight at the Setting Sun Garrison in the Vale of Eternal Blossoms.", completion = "Well met, <race>. You look capable. Glad to know we have a decent <class> on our side." }
WordHunterWoW_QuestEN[31385] = { title = "The Golden Lotus", description = "The Golden Lotus have guarded the Vale for centuries, keeping it safe and hidden from harm.\n\nRecent events have unleashed terrible horrors upon our sacred vale, but allies of the Golden Lotus still stand against them, attempting to bring peace.\n\nIf you wish to help, you had best join them at the Setting Sun Garrison.", objectives = "Speak to Anji Autumnlight at the Setting Sun Garrison in the Vale of Eternal Blossoms.", completion = "Well met, <race>. You look capable. Glad to know we have a decent <class> on our side." }
WordHunterWoW_QuestEN[31386] = { title = "The Shado-Pan Offensive", description = "We Shado-Pan have amassed our forces for the first time in many ages.\n\nThe Sha of Hatred has escaped beyond the Serpent's Spine, and it is our sacred duty to imprison it once more.\n\nHowever, our warriors are great, but our numbers too few. Help from a capable {class} may not be turned away.\n\nIf you wish to join the offensive, speak to Taran Zhu in the Townlong Steppes.", objectives = "Speak to Taran Zhu at Longying Outpost in the Townlong Steppes.", completion = "Well met, <race>." }
WordHunterWoW_QuestEN[31387] = { title = "Understanding The Shado-Pan", description = "The Shado-Pan rank among Pandaria's oldest defenders.\n\nFor years we train in our snow-capped monastery high in the Kun-Lai Summit, perfecting the martial secrets passed down by our ancestors.\n\nOur numbers may seem few, but a single Shado-Pan can be deadlier than a hundred trained soldiers.\n\nTo join the Shado-Pan order is a long journey full of hardship. If this is the path you seek, then you must first prove your worth.\n\nThere is urgent work to be done here. Help the Golden Lotus defend the Vale.", objectives = "Earn Revered standing with the Golden Lotus.", completion = "Ah yes. <name>. Your name has traveled to us from the east.\n\nWe have seen your efforts in the Vale of Eternal Blossoms. Already you have earned the esteem of the Golden Lotus.\n\nYes, we are interested to learn more about you." }
WordHunterWoW_QuestEN[31388] = { title = "The Shado-Pan Offensive", description = "We Shado-Pan have amassed our forces for the first time in many ages.\n\nThe Sha of Hatred has escaped beyond the Serpent's Spine, and it is our sacred duty to imprison it once more.\n\nHowever, our warriors are great, but our numbers too few. Help from a capable {class} may not be turned away.\n\nIf you wish to join the offensive, speak to Taran Zhu in the Townlong Steppes.", objectives = "Speak to Taran Zhu at Longying Outpost in the Townlong Steppes.", completion = "Well met, <race>." }
WordHunterWoW_QuestEN[31389] = { title = "Understanding The Shado-Pan", description = "The Shado-Pan rank among Pandaria's oldest defenders.\n\nFor years we train in our snow-capped monastery high in the Kun-Lai Summit, perfecting the martial secrets passed down by our ancestors.\n\nOur numbers may seem few, but a single Shado-Pan can be deadlier than a hundred trained soldiers.\n\nTo join the Shado-Pan order is a long journey full of hardship. If this is the path you seek, then you must first prove your worth.\n\nThere is urgent work to be done here. Help the Golden Lotus defend the Vale.", objectives = "Earn Revered standing with the Golden Lotus.", completion = "Ah yes. <name>. Your name has traveled to us from the east.\n\nWe have seen your efforts in the Vale of Eternal Blossoms. Already you have earned the esteem of the Golden Lotus.\n\nYes, we are interested to learn more about you." }
WordHunterWoW_QuestEN[31390] = { title = "The Klaxxi", description = "The Klaxxi are only rumored to exist, far beyond the wall in the Dread Wastes.\n\nFew have ventured into that territory, and none have returned to tell the tale.\n\nIf you are set on finding these... Klaxxi... there is a small group of Shado-Pan manning the wall to the far southwest who may know more.", objectives = "Speak to Bowmistress Li at the Gate of the Setting Sun between the Vale of Eternal Blossoms and the Dread Wastes.", completion = "The Dread Wastes is a very dangerous place." }
WordHunterWoW_QuestEN[31391] = { title = "The Klaxxi", description = "The Klaxxi are only rumored to exist, far beyond the wall in the Dread Wastes.\n\nFew have ventured into that territory, and none have returned to tell the tale.\n\nIf you are set on finding these... Klaxxi... there is a small group of Shado-Pan manning the wall to the far southwest who may know more.", objectives = "Speak to Bowmistress Li at the Gate of the Setting Sun between the Vale of Eternal Blossoms and the Dread Wastes.", completion = "The Dread Wastes is a very dangerous place." }
WordHunterWoW_QuestEN[31392] = { title = "Temple of the White Tiger", description = "Have you heard the news, traveller? There's been an attack at one of our most sacred places, the Vale of Eternal Blossoms!\n\nEven now, there's a human prince within the White Tiger Temple arguing that you and the other races from beyond the mists should be allowed within.\n\nThe temple is in the northeast of Kun-Lai. Maybe you can convince the White Tiger to allow you inside?\n\nI only hope the Vale has not been utterly destroyed...", objectives = "Speak to Anduin Wrynn at the Temple of the White Tiger in Kun-Lai Summit.", completion = "<class>, I'm glad you're here! The Pandaren tell of a legendary place, the \"Vale of Eternal Blossoms.\" It's a place of great healing, if the locals are to be believed.\n\nBetween the destruction of the Cataclysm and the horrors of this light-forsaken war, the Vale may be our best hope for healing the wounds of the world.\n\nWe need to get in there!" }
WordHunterWoW_QuestEN[31393] = { title = "Temple of the White Tiger", description = "Have you heard the news, traveller? There's been an attack at one of our most sacred places, the Vale of Eternal Blossoms!\n\nEven now, there's a human prince within the White Tiger Temple arguing that you and the other races from beyond the mists should be allowed within.\n\nThe temple is in the northeast of Kun-Lai. Maybe you can convince the White Tiger to allow you inside?\n\nI only hope the Vale has not been utterly destroyed...", objectives = "Speak to Dezco at the Temple of the White Tiger in Kun-Lai Summit.", completion = "Hello, <class>! The human prince from Stormwind has been granted an audience with the White Tiger. He seeks to gain admittance into the Vale of Eternal Blossoms... for both the Alliance and the Horde.\n\nThe Vale is a sacred place. I believe my wife Leza saw it in a vision - it's what brought my people to Pandaria. Perhaps we will find shelter there.\n\nDo you think we will be allowed inside?" }
WordHunterWoW_QuestEN[31394] = { title = "A Celestial Experience", description = "Nobody is allowed into the Vale without the approval of the August Celestials. Xuen, The White Tiger, appears ready to listen to me.\n\nBut Taran Zhu of the Shado-Pan is reluctant to let the Alliance or Horde anywhere NEAR the Vale after all that's happened.\n\n<Anduin shakes his head.>\n\nMaybe you can help me make my case. Speak to the White Tiger on our behalf. Be careful! He may set a number of challenges before you...", objectives = "Speak to Xuen and complete his tests.", progress = "Are you finished with the White Tiger's tasks?", completion = "You did it, <name>!\n\nThe White Tiger has agreed to allow us to accompany the Pandaren into the Vale of Eternal Blossoms. We can set up an Alliance outpost in there to act as our embassy with the Pandaren." }
WordHunterWoW_QuestEN[31395] = { title = "A Celestial Experience", description = "The human calf is arguing on our behalf. He is well-spoken; I can see why Baine Bloodhoof regards the prince so highly.\n\nStill, the argument does not go well. I am of little consequence, but you are a hero of the Horde. Perhaps you can intercede in our favor?\n\nSpeak with the White Tiger and plead our case, {race}.\n\nBe careful! He may set a number of challenges before you...", objectives = "Speak to Xuen and pass his tests.", progress = "Have you passed the White Tiger's tests. <race>?", completion = "You did it, <name>!\n\nThe White Tiger has agreed to allow us to accompany the Pandaren into the Vale of Eternal Blossoms.\n\nWhere the Alliance Prince failed, a hero of the Horde prevailed." }
