WordHunterWoW_QuestEN[31398] = { title = "Falling to Pieces", description = "Why would the saurok have amber? More importantly, why would Oracle Hiss'ir be so protective of it?\n\nIt is unlikely this came from the heavily guarded Zan'vess, so where did it come from?\n\nPerhaps the Klaxxi will know what to make of it.", objectives = "Return the Glowing Amber to Kaz'tik the Manipulator.", progress = "Where did you find this?", completion = "You were wise to bring this to us. This is a piece of another paragon's encasing amber.\n\nThe damage suggests the paragon may be in trouble.\n\nI will speak with the council to decide what should be done next." }
