WordHunterWoW_QuestEN[31437] = { title = "FLAG - Swarmkeeper's Crossbow", description = "", objectives = "" }
WordHunterWoW_QuestEN[31438] = { title = "FLAG - Hammer of the Poisoned Mind", description = "", objectives = "" }
WordHunterWoW_QuestEN[31439] = { title = "Dropping Our Signal", description = "The beacon in Amberglow Hollow seems to have been tampered with. Right before the signal cut out the Klaxxi'va picked up a signal for another paragon nearby.\n\nThey believe he is hidden in that wretched little swamp, Duskroot Fen.\n\nI will meet you in the fen to set up a temporary beacon until I can get Amberglow operational again.\n\nYou will wake the paragon and then you will help me.", objectives = "Awaken the paragon in Duskroot Fen.", completion = "It seems my work will begin immediately. You have come to a dangerous place, Wakener." }
WordHunterWoW_QuestEN[31440] = { title = "The Four Tomes", description = "There are four tomes of great necromantic evil studied in Scholomance: \"In the Shadow of the Light\", \"Kel'Thuzad's Deep Knowledge\", \"Forbidden Rites and other Rituals Necromantic\" and \"The Dark Grimoire\".\n\nAs we make our way through this cursed place, find and destroy each book so that no other fool can come along later and learn their vile secrets.", objectives = "Destroy the four tomes: \"In the Shadow of the Light\", \"Kel'Thuzad's Deep Knowledge\", \"Forbidden Rites and other Rituals Necromantic\" and \"The Dark Grimoire\".", progress = "The four tomes contain secrets that have damned this place and all associated with it to an eternity of suffering.\n\nThey must be destroyed!", completion = "Thank you, <name>.\n\nWith the destruction of the tomes I'll go to my final rest knowing that those books will never again haunt a living soul." }
WordHunterWoW_QuestEN[31441] = { title = "Corruption Runs Deep", description = "Today you learn that no one can be trusted in times of war, Wakener. Even those closest to the Klaxxi are susceptible to corruption.\n\nWho knows how long this traitor has been corrupted. He must be destroyed!\n\nYou appear confused. Do you not see the traitor in our midst? Allow me to adjust your vision.", objectives = "Defeat the traitor in the Duskroot Fen.", completion = "You will see more of this. War is never pretty.\n\nThe empresses' corruption is far reaching and hard to detect.\n\nThere is much work to be done. We need to start repairing the damage Kor'ik did." }
WordHunterWoW_QuestEN[31442] = { title = "The Four Tomes", description = "There are four tomes of great necromantic evil studied in Scholomance: \"In the Shadow of the Light\", \"Kel'Thuzad's Deep Knowledge\", \"Forbidden Rites and other Rituals Necromantic\" and \"The Dark Grimoire\".\n\nAs we make our way through this cursed place, find and destroy each book so that no other fool can come along later and learn their vile secrets.", objectives = "Destroy the four tomes: \"In the Shadow of the Light\", \"Kel'Thuzad's Deep Knowledge\", \"Forbidden Rites and other Rituals Necromantic\" and \"The Dark Grimoire\".", progress = "The four tomes contain secrets that have damned this place and all associated with it to an eternity of suffering.\n\nThey must be destroyed!", completion = "Thank you, <name>.\n\nWith the destruction of the tomes I'll go to my final rest knowing that those books will never again haunt a living soul." }
WordHunterWoW_QuestEN[31443] = { title = "Flying Tiger Gourami", description = "You've caught a unique fish... with wings.  Perhaps it deserves the expert opinion of Nat Pagle in Anglers Wharf.\n", objectives = "Bring the Flying Tiger Gourami to Nat Pagle at Anglers Wharf.", progress = "Flying fish?", completion = "Is that a flying tiger gourami?\n\nThis little fish is a rare mutation of the tiger gourami that can fly, and are consequently caught in any freshwater here in Pandaria.\n\nLocal legend states that good luck comes to the person who eats it, and local tradition states that only royalty can eat them.  To be caught breaking this \"tradition\" is a death sentence.\n\nWith that in mind, I'll make sure it gets to the right person." }
WordHunterWoW_QuestEN[31444] = { title = "Spinefish Alpha", description = "You have fished up something special.  It looks pretty aggressive.\n\nMaybe Nat Pagle at the Anglers Wharf might know more about it?\n", objectives = "Bring the Spinefish Alpha to Nat Pagle at Anglers Wharf.", progress = "Strange fish?", completion = "That's not what I think it is, is it?  Oh wow, a spinefish alpha, one of Pandaria's deadliest predators.\n\nSpinefish are malformed abominations created by the sha presence, and these big ones are simply terrifying.  An alpha will often eat other spinefish, even though there isn't a single part of them that's edible.\n\nLuckily for both of us, they are very interesting to alchemists." }
WordHunterWoW_QuestEN[31445] = { title = "zzOld", description = "If you want to explore all the secrets of the deep ocean, and catch some big fish, speak to my brother Haito at the Anglers Wharf in Krasarang Wilds.\n\nI'm sure he'd love to show you a thing or two about reeling!", objectives = "Speak to Fisherman Haito at the Anglers Wharf in the Krasarang Wilds.If you want to explore all the secrets of the deep ocean, and catch some big fish, speak to my brother Haito at the Anglers Wharf in Krasarang Wilds.\n\nI'm sure he'd love to show you a thing or two about reeling!" }
WordHunterWoW_QuestEN[31446] = { title = "Mimic Octopus", description = "You aren't sure how, but you've caught an extraordinary cephalopod.  Nat Pagle at Anglers Wharf would be very interested to see it.\n", objectives = "Bring the Mimic Octopus to Nat Pagle at Anglers Wharf.", progress = "Camouflage octopus?", completion = "Is that a mimic octopus?  A buddy of mine caught one of these off the coast of Zandalar a few years back.  He barely made it back alive, actually.  Pesky trolls, but great fishing!\n\nAnyhow, they aren't as rare as you might think because they use camouflage to hide amongst rocks and plants; only a very skilled fisherman has any hope of catching this elusive, and delicious, morsel." }
WordHunterWoW_QuestEN[31447] = { title = "An End to the Suffering", description = "The key to lifting the curse of this place rests in the final death of Darkmaster Gandling.\n\nDo it, {name}, and make him suffer!", objectives = "Kill Darkmaster Gandling.", completion = "Behold my true form.\n\nI owe you a debt, one which I can never repay. But, I thank you for lifting the curse off of my family.\n\nKel'Thuzad, the Lich King, and now Darkmaster Gandling -- all are dead.\n\nPerhaps now I too can find some semblance of peace." }
WordHunterWoW_QuestEN[31448] = { title = "An End to the Suffering", description = "The key to lifting the curse of this place rests in the final death of Darkmaster Gandling.\n\nDo it, {name}, and make him suffer!", objectives = "Kill Darkmaster Gandling.", completion = "Behold my true form.\n\nI owe you a debt, one which I can never repay. But, I thank you for lifting the curse off of my family.\n\nKel'Thuzad, the Lich King, and now Darkmaster Gandling -- all are dead.\n\nPerhaps now I too can find some semblance of peace." }
WordHunterWoW_QuestEN[31450] = { title = "A New Fate", description = "These new allies have shed light on a great and important truth: it is not just Shen-zin Su that is ailing, but all of the land beyond the clouds. The world needs healing, and I think that you should be the ones to heal it.\n\nI would like you, Ji, and Aysa to leave and bring your strength and wisdom to the world. These Alliance and Horde have different ideals, but at the core of both lies noble intent.\n\nI will leave the choice of who you wish to accompany to you.", objectives = "Speak to the Spirit of Master Shang Xi, and choose whether you leave with the Alliance or the Horde.", completion = "And so it is done... here we are, in our new home." }
WordHunterWoW_QuestEN[31451] = { title = "The Missing Merchant", description = "Usually, Merchant Shi comes through Kun-Lai Summit to trade with the Jinyu and Grummle. We've heard word that he hadn't been seen at Binan, and we haven't seen him here...\n\nI'm worried something has happened to him. Can you go to the Inkgill Mere and see if he's there?", objectives = "Speak with Merchant Shi at Inkgill Mere in Kun-Lai Summit.", completion = "My son! They took my son... Can you help me?" }
WordHunterWoW_QuestEN[31452] = { title = "The Missing Merchant", description = "Usually, Merchant Shi comes through Kun-Lai Summit to trade with the Jinyu and Grummle. We've heard word that he hadn't been seen at Binan, and we haven't seen him here...\n\nI'm worried something has happened to him. Can you go to the Inkgill Mere and see if he's there?", objectives = "Speak with Merchant Shi at Inkgill Mere in Kun-Lai Summit.", completion = "My son! They took my son... Can you help me?" }
WordHunterWoW_QuestEN[31453] = { title = "The Shado-Pan", description = "Our new recruits have spoken in hushed tones about a group of Pandaren they call the \"Shado-Pan\". They are apparently very strong, and secretive.\n\nIt's clear that, no matter what happens here in Kun-Lai, making an alliance with these Shado-Pan will be critical to our foothold in Pandaria.\n\nThat's where you come in. Rumor is they have a base of operations to the southeast, near Firebough Nook.\n\nYou will go there, and curry their favor. For the Horde!", objectives = "Speak to Shado-Master Chong at Shado-Pan Fallback in Firebough Nook.", completion = "Who are you? Can you fight? If so, we can use your help." }
WordHunterWoW_QuestEN[31454] = { title = "A Legend in the Making", description = "Our world finds itself at a crossroads. The next few months will shape everything to come - presuming we are to have a future at all.\n\nAh! But I am getting ahead of myself. Let me back up. Come, share a drink with me. Let's talk about the future of Azeroth.", objectives = "Share a drink with Wrathion. He's buying.", completion = "Of course, I must ask your discretion regarding what we just talked about.\n\nWe wouldn't want to alarm anyone who is, shall we say, less capable than yourself." }
WordHunterWoW_QuestEN[31455] = { title = "The Shado-Pan", description = "Our new recruits have spoken in hushed tones about a group of Pandaren they call the \"Shado-Pan\". They are apparently very strong, and secretive.\n\nThat's where you come in. Rumor is they have a base of operations to the southeast, near Firebough Nook. You should travel there as an envoy of the Alliance. Give them any help they require.", objectives = "Speak to Shado-Master Chong at Shado-Pan Fallback in Firebough Nook.", completion = "Who are you? Can you fight? If so, we can use your help." }
WordHunterWoW_QuestEN[31456] = { title = "Muskpaw Ranch", description = "There's another Pandaren settlement out here, Muskpaw Ranch. I don't know if they're alright, what with everything that's been going on with the Yaungol invasion.\n\nYou've been so helpful - you should go check up on them, friend!", objectives = "Travel to Muskpaw Ranch in Kun-Lai Summit and speak with Lao Muskpaw.", completion = "Wha? Who the heck are you? What are you doin' here?\n\nOh, you wanna help?" }
WordHunterWoW_QuestEN[31457] = { title = "Muskpaw Ranch", description = "There's another Pandaren settlement out here, Muskpaw Ranch. I don't know if they're alright, what with everything that's been going on with the Yaungol invasion.\n\nYou've been so helpful - you should go check up on them, friend!", objectives = "Travel to Muskpaw Ranch in Kun-Lai Summit and speak with Lao Muskpaw.", completion = "Wha? Who the heck are you? What are you doin' here?\n\nOh, you wanna help?" }
WordHunterWoW_QuestEN[31458] = { title = "Damage Control", description = "Kor'ik has been sending signals to the empress for weeks. Everything the Klaxxi have done, the empress knows about.\n\nThat stops now!\n\nKypari Ik will be the first to receive news of Kor'ik's demise. It would benefit us to make sure that message does not make it to the empress.\n\nDestroying the whisperers and beacon there will buy us enough time to come up with a plan before the empress can act.", objectives = "Destroy 5 Ik'thik Whisperers and deactivate the Kypari Ik Beacon.", progress = "Information is power, Wakener. Those with the most information always have the most power.", completion = "Excellent work! This should allow us the time to repair the damage Kor'ik caused.\n\nYou may have just shifted the tide of war in our favor." }
WordHunterWoW_QuestEN[31459] = { title = "Cho's Missive", description = "One of those grummles came by and said that Lorewalker Cho sent for you. You should go ahead and meet up with him, he might have something important to say.\n\nThe grummel said he's at Onekeg, to the north.", objectives = "Speak with Lorewalker Cho at Onekeg in Kun-Lai Summit.", completion = "Oh, hello. Nice to see you again." }
WordHunterWoW_QuestEN[31460] = { title = "Cho's Missive", description = "One of those adorable little grummles came by and said that Lorewalker Cho sent for you. You should meet up with him!\n\nThe grummel said he's at Onekeg, to the north.", objectives = "Speak with Lorewalker Cho at Onekeg in Kun-Lai Summit.", completion = "Oh, hello. Nice to see you again." }
WordHunterWoW_QuestEN[31461] = { title = "Spoke with Xuen", description = "", objectives = "" }
WordHunterWoW_QuestEN[31462] = { title = "Spirit of Violence Defeated", description = "", objectives = "" }
WordHunterWoW_QuestEN[31463] = { title = "Spirit of Anger Defeated", description = "", objectives = "" }
WordHunterWoW_QuestEN[31464] = { title = "Opposing Faction Leader Defeated", description = "", objectives = "" }
WordHunterWoW_QuestEN[31465] = { title = "Extracting Answers", description = "Kypari Ik is just one of many locations that houses some of Empress Shek'zeer's offspring. In their juvenile state the young are reckless and difficult to control. They are also deadly.\n\nSwarmborn are hatched with a highly toxic venom that diminishes in potency with age. The venom can incapacitate even the strongest and most skilled fighter if it hits flesh.\n\nI would like you to bring me some of this venom.", objectives = "Collect 6 Venom-Coated Mandibles from the Ik'thik Swarmborn in Kypari Ik.", progress = "Swarmborn venom will not only give us an additional weapon, it will also help us figure out what stage the swarm is in.", completion = "This venom is in its advanced stages, but doesn't seem to be losing it's potency...\n\nThis is very curious. The Klaxxi will want to know immediately. Thank you, Wakener." }
WordHunterWoW_QuestEN[31466] = { title = "FLAG - Took Loot", description = "", objectives = "" }
WordHunterWoW_QuestEN[31467] = { title = "Strong as a Tiger", description = "With the grill, you can transform those raw tiger steaks into food that makes you stronger. Learn the recipe for charbroiled tiger steaks from me. Show me what you can do.", objectives = "Train the recipe for Charbroiled Tiger Steak from the Master of the Grill, then give him 5 Charbroiled Tiger Steaks.", progress = "Learn the recipe from me and demonstrate what you have learned.", completion = "Strength and good health! This is the Way of the Grill." }
WordHunterWoW_QuestEN[31468] = { title = "Trial of the Black Prince", description = "I have on good authority that you are a champion among champions, but if you'll permit me this indulgence, I would like to test your mettle for myself.\n\nThe mogu who assault the Vale of Eternal Blossoms, the mogu minions who inhabit Shan'ze Dao, and the sha-corrupted mantid swarming the Dread Wastes... these may provide an adequate challenge for one of your stature.\n\nProve yourself to me. No rush - I expect this to take you some time.", objectives = "Earn an Honored Reputation with the Black Prince. Level 90 mogu and mantid in the Vale of Eternal Blossoms, Townlong Steppes and the Dread Wastes will earn reputation.", completion = "Marvelous. That did not take long at all.\n\nWord of your many achievements has been the talk of the Vale!\n\nVery well, I will take you under my wing." }
WordHunterWoW_QuestEN[31469] = { title = "UNUSED", description = "The Pandaren Way of the Grill produces foods that increase your physical strength. Learn the recipe for Charbroiled Tiger Steak from the Master of the Grill and show him the results of your learning.You will receive:", objectives = "Make a Charbroiled Tiger Steak for the Master of the Grill. You will need to learn the Way of the Grill and the recipe from him first." }
WordHunterWoW_QuestEN[31470] = { title = "Way of the Wok", description = "If you wish to make dishes that enhance agility, you should bring some carrots and rice to the Master of the Wok. The virmen around here tend to carry a lot of carrots around. You can also grow your own, if you have a farm.", objectives = "Bring 5 Juicycrunch Carrots to the Master of the Wok.", progress = "Hello, young chef. Do you wish to learn the Way of the Wok?", completion = "Well done." }
WordHunterWoW_QuestEN[31471] = { title = "Agile as a Tiger", description = "To cook with the wok, you need to be nimble. Your first lesson is sauteed carrots.\n", objectives = "Train the recipe for Sauteed Carrots from the Master of the Wok, then give her 5 Sauteed Carrots.", progress = "Let me teach you how to make sauteed carrots.", completion = "Nice work." }
WordHunterWoW_QuestEN[31472] = { title = "Way of the Pot", description = "The cuisine of the Way of the Pot help expand your intellect. Bring some jade lungfish to the Master of the Pot and she will teach you. You can fish for jade lungfish in the Jade Forest.", objectives = "Bring 5 Jade Lungfish to the Master of the Pot.", progress = "Want to learn the recipe for swirling mist soup?  Bring me some jade lungfish.", completion = "Good stuff. Now, let's get to your lesson." }
WordHunterWoW_QuestEN[31473] = { title = "The Strength of One's Foes", description = "Great leadership requires the power to shape the destiny of your people, and the wisdom to make the right decisions. Pandaria boasts great power and ancient wisdom, but rarely in the same place.\n\nLet's see if you and I can change that!\n\nAcquire sigils of power and wisdom from fallen foes in the Mogu'shan Vaults, the Heart of Fear, or the Terrace of Endless Spring. We will put them to a much better use than their current owners.", objectives = "Collect 10 Sigils of Power and 10 Sigils of Wisdom from raid bosses in the Mogu'shan Vaults, Heart of Fear, or Terrace of Endless Spring.", progress = "Sigils of wisdom will often be found on practitioners of the arcane arts, while sigils of power are usually found on those who favor brute strength.\n\nThis is not always true, but it may help you find what you need.", completion = "My friend - you do not disappoint!\n\nWe will put these to good use." }
WordHunterWoW_QuestEN[31474] = { title = "The Soup of Contemplation", description = "Watching over the pot, you get a lot of time to think. Let me show you how to make swirling mist soup and you'll know what I mean.", objectives = "Train the recipe for Swirling Mist Soup from the Master of the Pot, then give her 5 Swirling Mist Soup.", progress = "If you want to learn the Way of the Pot, you have to start with swirling mist soup.", completion = "Intellect is a gift you must hone with time." }
WordHunterWoW_QuestEN[31475] = { title = "Way of the Steamer", description = "A great meal can lift your spirits, and none more so than food from the Way of the Steamer. Bring the Master some giant mantis shrimp and he will show you. You can fish for giant mantis shrimp in the ocean.", objectives = "Bring 5 Giant Mantis Shrimp to the Master of the Steamer.", progress = "If you want to learn the Way of the Steamer, you'll need some shrimp.", completion = "Fine ingredients." }
WordHunterWoW_QuestEN[31476] = { title = "The Spirit of Cooking", description = "When I cook with steam, I infuse the food with my love. Let me teach you the recipe for shrimp dumplings.", objectives = "Train the recipe for Shrimp Dumplings from the Master of the Steamer, then give him 5 Shrimp Dumplings.", progress = "Let me teach you how to make shrimp dumplings.", completion = "Spirits are lifted by good food." }
WordHunterWoW_QuestEN[31477] = { title = "Endurance", description = "They say that the crane appointed sentry by its flock stands guard with a stone in its beak, so that, should it fall asleep, the stone drops and it awakens. To be skilled with the oven, you need to have endurance and patience. Learn the recipe for wildfowl roast and show me that you understand.", objectives = "Train the recipe for Wildfowl Roast from the Master of the Oven, then give her 5 Wildfowl Roast.", progress = "Learn the recipe for wildfowl roast from me and let's see what you can do.", completion = "Stamina and endurance are needed for mastering anything. To slave over a hot oven takes patience, but the results are very much worth the effort." }
WordHunterWoW_QuestEN[31478] = { title = "Way of the Oven", description = "If you are looking for a hearty meal that will sustain you and increase your stamina, you should seek out the Way of the Oven. Bring some wildfowl breasts to the Master of the Oven and she will teach you. There are plenty of cranes in the Valley of the Four Winds and in the Jade Forest, but you can obtain wildfowl breasts from other birds as well.", objectives = "Bring 5 Wildfowl Breasts to the Master of the Oven.", progress = "If you want to make wildfowl roast, you need to obtain wildfowl breasts.", completion = "We can work with these." }
WordHunterWoW_QuestEN[31479] = { title = "Way of the Brew", description = "The Pandaren Way of the Brew produces... Well, I'll let the Master of the Brew explain it. Bring him some ginseng and he will show you the way.", objectives = "Bring 1 Ginseng to the Master of the Brew. Ginseng can be bought from Sungshin Ironpaw.", progress = "You'd like to learn the Way of the Brew?", completion = "This is a fine example of good ginseng. Would you like to learn how to make tea with it?" }
WordHunterWoW_QuestEN[31480] = { title = "Have a Drink", description = "My siblings are so serious. I think life's too short to be so serious all the time. Let's have some tea together. Let me teach you how to make ginseng tea.", objectives = "Train the recipe for Ginseng Tea from the Master of the Brew, then give him 1 Ginseng Tea.", progress = "Let me teach you how to make ginseng tea.", completion = "Well done. This is delicious." }
WordHunterWoW_QuestEN[31481] = { title = "Fear Itself", description = "I've picked up a few motes of pandaren wisdom during my time here. I particularly enjoy this one:\n\n\"The timid feel fear before trouble starts; the cowards feel fear as trouble happens. The bravest among us feel fear only after the troubles have been taken care of.\"\n\nIs that true? Let's find out.\n\nThe Sha of Fear has fled into the Terrace of Endless Spring. Pursue it there, defeat it, and rip out its spirit - presuming it has one.\n\nYour bravery will be handsomely rewarded.", objectives = "Defeat the Sha of Fear in the Terrace of Endless Spring and acquire the Chimera of Fear.", progress = "Another bit of pandaren wisdom: \"Fear is not a criminal we must lock away. It is a teacher we must seek to understand.\"  In facing our fears, we gain great strength.\n\nHave you faced your fears, <name>?", completion = "You have done it!\n\nSome put their faith in magic or steel. But in my experience, fear is the most powerful weapon one can wield. Use it properly, and your enemies cannot bring themselves to fight you." }
WordHunterWoW_QuestEN[31482] = { title = "Breath of the Black Prince", description = "<Wrathion's piercing red eyes fixate on you.>\n\nYou are among a rare breed, {name}.\n\nYou are just what I am looking for - an individual with the potential to shape events on a global scale.\n\nCome now, I promised you a reward, and you shall have it! East of this tavern is a series of stone steps leading up to a vista that the locals have named \"Mason's Folly.\" Meet me there.", objectives = "Go to the top of the stone steps at Mason's Folly and meet Wrathion there to accept your reward.", completion = "You have earned this, <name>! Use it well.\n\nPlease understand, I mean to pay off my father's debts. I will stop at NOTHING to defend this world. In the future, if you are ever uncertain, you are welcome to question my means. But never question my motives. The safety of this world is my primary concern.\n\nNow then, let's talk about current events." }
WordHunterWoW_QuestEN[31483] = { title = "Incoming...", description = "The Pandaren campaign is only beginning! We turn our attention now to the ongoing conflict between the Alliance and the Horde.\n\nMy contacts in Ravenholdt tell me that the Alliance 7th Legion and a considerable Horde invasion force are converging toward Pandaria's southern shores. Like it or not, Pandaria may soon become a battlefield.\n\nWe are done for now, but I want you to contact me when your fleet arrives. Then... together we will spring into action!", objectives = "Contact Wrathion once your naval fleet makes landfall on the southern coast of Pandaria.", completion = "They're here!\n\n<Wrathion claps his hands and rubs them together, excitedly.>\n\nOh <name>. Things are about to get exciting." }
WordHunterWoW_QuestEN[31484] = { title = "Hisek Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[31485] = { title = "UNUSED", description = "I am not a master chef like my siblings. What I am is a great teacher. If you are dedicated, I can unlock your hidden potential, no matter how inexperienced you are.\n\nIf you wish to learn, show me you can at least follow basic instructions. Learn the recipe for soft-boiled eggs, make five of them and bring them to me.  I have fresh eggs which I will sell to you at a token price.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Learn the recipe for Soft-Boiled Eggs from the Guide to the Ways and make 5 of them for her." }
WordHunterWoW_QuestEN[31486] = { title = "Everything I Know About Cooking", description = "I'm so glad you enjoy my food. Are you interested in the recipes?  If so, you should learn them properly, from my teachers in Halfhill Market.  Everything I know about the kitchen, I learned from them.\n\nSay, if you happen to pass through there, would you deliver this note to Sungshin Ironpaw for me? She was my favorite teacher, and I want her to know that I miss her.", objectives = "Deliver the Letter to Sungshin Ironpaw. She teaches in Halfhill Market.", progress = "You have a letter for me?", completion = "My, that's so thoughtful. I love hearing from my old students." }
WordHunterWoW_QuestEN[31487] = { title = "Sonic Disruption", description = "Relying on sonic whispers to manipulate the kunchong was only the most primitive stage of my research, and yet the Empire seems to have adopted the practice wholly. The manipulators of the Shek'zeer are too impatient to form a proper bond with their kunchong.\n\nTheir laziness will cost them dearly.\n\nStrike this tuning fork near the dread kunchong in the clutches - watch as they reel in confusion and lash out at their masters. Use this to your advantage and put them down.", objectives = "Kill 4 Dread Kunchong and 6 Shek'zeer Manipulators in the Clutches of Shek'zeer. The Sonic Disruption Fork will weaken and confuse the kunchong.", completion = "Let this be a reminder - the kunchong should be feared and respected." }
WordHunterWoW_QuestEN[31488] = { title = "Stranger in a Strange Land", description = "Excuse me, <class>. Is your name <name>?\n\nA figure in a dark cloak asked that I give this to you. She was a traveler from beyond the mists, like yourself, but - well, I didn't trust her.\n\nThe message comes from a tavern in the veiled stair. I'll give you the note but... you should watch your back if you venture up there!", objectives = "Seek out \"The Black Prince\" at the Tavern in the Mists in the Veiled Stair.", progress = "So, my note found its way to you!", completion = "My people have done their job and brought you to me. Wonderful." }
WordHunterWoW_QuestEN[31489] = { title = "Stranger in a Strange Land", description = "Excuse me, <class>. Is your name <name>?\n\nA figure in a dark cloak asked that I give this to you. She was a traveler from beyond the mists, like yourself, but - well, I didn't trust her.\n\nShe mentioned the name \"Wrathion.\" Does that ring any bells for you?\n\nI'll give you the note but... you should watch your back if you're going to deal with these people.", objectives = "Seek out Wrathion at the Tavern in the Mists in the Veiled Stair.", progress = "So, we meet again!", completion = "My people have done their job and brought you to me. Wonderful." }
WordHunterWoW_QuestEN[31490] = { title = "Rank and File", description = "First things first; let's kill us some crusaders.\n\nAnd when I say kill the Scarlet Crusade, I mean wipe them out, root and branch, rank and file.", objectives = "Kill 50 members of the Scarlet Crusade within the Scarlet Halls.", progress = "You know, I've been killing the ones that you can't see behind closed doors.\n\nBut I need to maintain this disguise. So if you could just take care of all of the ones <name> there in the open, that'd be great.", completion = "Great start, <name>!\n\nIt won't be long now before the Scarlet Crusade is nothing more than an ugly footnote in the annals of history." }
WordHunterWoW_QuestEN[31491] = { title = "The Ten Foot Pole", description = "Xuen once issued this challenge to the last Emperor of Pandaria: stand in the center of the room and hold off waves of monks using only a ten foot pole.\n\nMy record is ten. Can you beat that?You will receive:", objectives = "Hold back at least 10 Tiger Temple Monks using the Ten Foot Pole." }
WordHunterWoW_QuestEN[31492] = { title = "The Torch of Strength", description = "Xuen has this challenge he says helps \"refine strength.\" I am starting to think the word \"strength\" means something different to him than the rest of us.\n\nHere, take this torch to the top of the gates of the temple. If you can get it there without the torch being extinguished, you pass the challenge.\n\nWhatever you do, do not try carrying the torch on a mount. It will blow out if you do. Trust me on that one.", objectives = "Carry the Torch of Strength to the gates of the Temple of the White Tiger without it extinguishing.", progress = "Need another torch?", completion = "Wow! You made it. Usually I get stopped by one of those gusts of wind." }
WordHunterWoW_QuestEN[31493] = { title = "Just for Safekeeping, Of Course", description = "There is a book of great value to me here in the halls.\n\nUnfortunately, it's in the possession of Flameweaver Koegler. I've tried to get close to him before, but it's never quite worked out.\n\nYou might have better luck. Just watch out -- I hear that he's gone well and truly insane. The Flameweaver plans to burn every tome they have in the library.\n\nHe'll probably burn the Scarlet Halls down in the process.", objectives = "Collect the Codex of the Crusade.", progress = "It's imperative that I get my hands on the codex.", completion = "Ah yes!\n\n<The Hooded Crusader rubs her hands together gleefully at the sight of the codex.>\n\nAnd now, I have a checklist with the name of every Scarlet Crusader on it!\n\nYou know... just in case any of them are unaccounted for. I don't like loose ends." }
WordHunterWoW_QuestEN[31494] = { title = "Free From Her Clutches", description = "The Shek'zeer manipulators are corralling young kunchong into that clutch and exposing them to raw fear energies, twisting them and accelerating their growth.\n\nDisgusting! I will not allow it!\n\nBreak open the cages and set those hatchlings free.", objectives = "Break open Kunchong Cages to release 8 Kunchong Hatchlings in the Clutches of Shek'zeer.", completion = "Yes, I could see them rising up from the clutches. Beautiful!" }
WordHunterWoW_QuestEN[31495] = { title = "Rank and File", description = "First things first; let's kill us some crusaders.\n\nAnd when I say kill the Scarlet Crusade, I mean wipe them out, root and branch, rank and file.", objectives = "Kill 50 members of the Scarlet Crusade within the Scarlet Halls.", progress = "You know, I've been killing the ones that you can't see behind closed doors.\n\nBut I need to maintain this disguise. So if you could just take care of all of the ones out there in the open, that'd be great.", completion = "Great start, <name>!\n\nIt won't be long now before the Scarlet Crusade is nothing more than an ugly footnote in the annals of history." }
WordHunterWoW_QuestEN[31496] = { title = "Sampling the Empire's Finest", description = "The wonders of the kypari sap never cease to amaze me. Among its numerous properties and applications, the sap can be refined into a nutritious and extremely delectable elixir.\n\nNowhere in the Empire will you find a finer execution of this brew than the palace itself. Surely, the homes of the loyalists have feeders brimming with this sweet nectar.\n\nFill this jar at their feeders and return it to me. I long to sample the imperial ambrosia once more.", objectives = "Use the Sap Jar at Imperial Feeders outside the Heart of Fear 4 times to fill it.", completion = "Ah, yes, hand it over! Quickly now! My forelegs are trembling with anticipation." }
WordHunterWoW_QuestEN[31497] = { title = "Just for Safekeeping, Of Course", description = "There is a book of great value to me here in the halls.\n\nUnfortunately, it's in the possession of Flameweaver Koegler. I've tried to get close to him before, but it's never quite worked out.\n\nYou might have better luck. Just watch out -- I hear that he's gone well and truly insane. The Flameweaver plans to burn every tome they have in the library.\n\nHe'll probably burn the Scarlet Halls down in the process.", objectives = "Collect the Codex of the Crusade.", progress = "It's imperative that I get my hands on the codex.", completion = "Ah yes!\n\n<The Hooded Crusader rubs her hands together gleefully at the sight of the codex.>\n\nAnd now, I have a checklist with the name of every Scarlet Crusader on it!\n\nYou know... just in case any of them are unaccounted for. I don't like loose ends." }
WordHunterWoW_QuestEN[31498] = { title = "Jade Serpent Challenge Mode - Consolation (Nth)", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[31499] = { title = "Jade Serpent Challenge Mode - Bronze Addition (Nth)", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[31500] = { title = "Jade Serpent Challenge Mode - Silver Addition (Nth)", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[31501] = { title = "Jade Serpent Challenge Mode - Gold Addition (Nth)", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[31502] = { title = "Wing Clip", description = "The young fliers of this era are fascinating. Their exceptional agility and endurance were, in my time, the feats of incredibly skilled or mature fliers.\n\nThis would seem to indicate some kind of evolution in wing structure... Or perhaps a result of advancements in training? Induced genetic mutation? Selective breeding?\n\nGah! There's no way to know for certain without tissue samples.\n\nBring me their wings! And try not to ruin them in the process, will you? I need them intact!", objectives = "Collect 24 Needler Wings from Shek'zeer Needlers in the Clutches of Shek'zeer.", progress = "Do you have the specimens?", completion = "Excellent, these are in fine shape." }
WordHunterWoW_QuestEN[31503] = { title = "Shortcut to Ruin", description = "There is a champion among the loyalists, Vess-Guard Na'kal, whose strength comes not from experience or development, but from genetic modification. He was meant to be an example of the future of mantid - the sick idea that we can be born strong, without earning it.\n\nHe's a mockery of my work! Gene augmentation was meant for mature, post-swarm veterans ONLY!\n\nEnd him. Perhaps it will serve as a lesson to Grand Empress Shek'zeer that taking shortcuts leads to ruin.", objectives = "Kill Vess-Guard Na'kal outside the Heart of Fear.", progress = "I will not see my work used as a crutch to prop up the unworthy!", completion = "My enhancements are tools for experienced warriors. Not toys for these fool children!" }
WordHunterWoW_QuestEN[31504] = { title = "Ordnance Disposal", description = "If the Grand Empress's agents are still operating under security standards from my time, they would have hidden powerful pheromone mines all around the clutches.\n\nWith mere whisper she could detonate them all simultaneously, engulfing the palace and rendering entire siege armies powerless.\n\nIf we hope to have any success in a large scale standoff, we need to disable those mines. My... \"gift\" to you when we met will allow you to see the mines. Disturb them and get to a safe distance.", objectives = "Disable 8 Pheromone Mines around the Clutches of Shek'zeer and the Heart of Fear.", progress = "We cannot hope to re-take the clutches as long as those mines are still present is such quantities.", completion = "You weren't exposed to the pheromones were you? That could lead to... well, perhaps I shouldn't worry you with the details." }
WordHunterWoW_QuestEN[31505] = { title = "Vess-Guard Duty", description = "Vess-Guard Vik'az co-ordinates the defense forces at Zan'vess. He is worth ten mantid in battle, and his presence inspires the Zan'thik who fight alongside him.\n\nNeedless to say, we need him dead.\n\nHe patrols the housing area at the center of the island.", objectives = "Kill Vess-Guard Vik'az in Zan'vess.", progress = "Do not underestimate the impact of a precision strike. All of the Zan'thik will reel with the loss of Vik'az.", completion = "One by one, her champions fall." }
WordHunterWoW_QuestEN[31506] = { title = "Shackles of Manipulation", description = "The Zan'thik employ a sizable force of... indentured labor.\n\nYaungol are bound in special shackles which enhance and prolong the effects of sonic manipulation. It is this technology that allows the Zan'thik manipulators to command such large quantities of thralls to endlessly toil for them in the quarries.\n\nI would like to study these shackles.", objectives = "Collect 6 Zan'thik Shackles from Thought-Bound Miners and Thought-Bound Brutes in Zan'vess.", progress = "Surely this is something you can handle, is it not?", completion = "Ingenious devices, really. I have a feeling they will prove useful." }
WordHunterWoW_QuestEN[31507] = { title = "Meltdown", description = "The venomsting scorpions on Zan'vess are fed sap from a young age, causing a fascinating mutation in which their natural armor plating becomes infused with amber. Effectively, it's organic kyparite, the same substance used in forging most of the empire's weapons and armor.\n\nI think I've found a way to chemically break down kyparite, but it needs testing. Use these grenades on the Zan'thik venomstings and observe the results.", objectives = "Slay 6 Zan'thik Venomstings in Zan'vess. Use Korven's Experimental Grenade to counter their armor plating.", completion = "The kyparite ignited, did it? Fascinating!\n\nNot exactly what I was hoping for, but it's something." }
WordHunterWoW_QuestEN[31508] = { title = "Specimen Request", description = "Kyparite worms have shown extreme adaptations in order to mimic the environment around them. They can also grow to immense sizes at rates which are nearly unheard of for most creatures.\n\nTheir physiology could provide valuable insight into further mutations.\n\nBring me sample shards from the muck tunnelers in the shallows near Zan'vess.", objectives = "Collect 6 Kyparite Shards from Muck Tunnelers in The Briny Muck.", progress = "Do you have the specimens?", completion = "Well look at that, you actually got it done. I half expected to be scooping your remains out of the muck with a jar." }
WordHunterWoW_QuestEN[31509] = { title = "Fear Takes Root", description = "The fallout from Shek'zeer's madness will continue long after her reign has ended. We will struggle to heal our lands for many years to come, and even then our efforts may prove fruitless.\n\nA new species of sha-twisted flora has begun taking root near Zan'vess. Destroy any that you find, but beware - there is no telling what kind of sinister defenses it may have.", objectives = "Destroy 15 Dreadspore Bulbs in Zan'vess and The Briny Muck.", completion = "This species is interesting, but the risks associated with keeping it around for study are too high." }
WordHunterWoW_QuestEN[31510] = { title = "Quiet Now", description = "On the southwestern corner of Zan'vess lie the Whispering Stones. Much like the towers here, they are critical in transmitting long-range sonic signals.\n\nAn adjunct of the Empress operates the stones, keeping her in communication with the Zan'thik forces. Disrupt the signal, then silence him.", objectives = "Interact with the Zan'thik Resonating Crystal at the Whispering Stones in Zan'vess to incite Adjunct Sek'ot, then slay him.", completion = "It must drive her further into paranoia and madness, losing contact with Zan'vess.\n\nGood. Let her suffer." }
WordHunterWoW_QuestEN[31511] = { title = "A Witness to History", description = "I will gather up the other Tauren pilgrims and we will travel into the Vale together.\n\nMeet me at the Gate of the August Celestials at the southern edge of Kun-Lai Summit and speak with me there.", objectives = "Speak with Sunwalker Dezco at the Gate of the August Celestials.", progress = "You must be <name>.", completion = "Thank you for coming so quickly.\n\nFor thousands of years, the Golden Lotus has kept the Vale safe from those who would seek its power.\n\nUnfortunately, that time is past, and we need your help." }
WordHunterWoW_QuestEN[31512] = { title = "A Witness to History", description = "The celestials are allowing us back into the Vale! This will be a sight to behold.\n\nWe shouldn't waste any time. Head to the Gate of the August Celestials at the southern edge of Kun-Lai Summit and speak with me there.", objectives = "Speak with Anduin Wrynn at the Gate of the August Celestials.", progress = "You must be <name>.", completion = "Thank you for coming so quickly.\n\nFor thousands of years, the Golden Lotus has kept the Vale safe from those who would seek its power.\n\nUnfortunately, that time is past, and we need your help." }
WordHunterWoW_QuestEN[31513] = { title = "Blades of the Anointed", description = "The problem with the Scarlet Crusade is that they keep coming back, even after death.\n\nBehind those resurrections is High Inquisitor Whitemane. With her death, so goes the Crusade.\n\nTo give her the final rest, we need two swords of legend, each with a lost but storied history.\n\nLuckily for me... er, us, these two blades of the anointed are at rest here within the monastery.\n\nFind them and once you've killed Whitemane, plunge the blades into her corpse to make the death permanent.", objectives = "Collect the two Blades of the Anointed.", progress = "<With one blade already in your possession, you move to take the other.>\n\n<An inscription on the statue behind the sword reads, \"The Hand of Providence\".>", completion = "<The second anointed blade floats just in front of the wet statue. Steam rises from the sword.>\n\n<You get the uncanny feeling that the Hand of Providence has been waiting for you.>" }
WordHunterWoW_QuestEN[31514] = { title = "Unto Dust Thou Shalt Return", description = "<You take the second anointed blade in hand and feel the power of both swords course through you.>\n\n<There is but one thing left to do. As the mysterious, hooded woman explained, to put an end to the Scarlet Crusade, you must thrust both blades into the corpse of High Inquisitor Whitemane.>", objectives = "Use the Blades of the Anointed on the corpse of High Inquisitor Whitemane to send her permanently to her final rest.", progress = "<The deed is not yet done. There can be no end to the Scarlet Crusade while Whitemane can come back from the dead.>", completion = "With Whitemane gone for good, the Scarlet Crusade is finished. It's just a matter of sweeping up the refuse.\n\nThank you, <name>. Not just for myself, but for everyone opposed to mindless hatred and bigotry.\n\nAnd, thank you for these two new blades. Anointed anew in her blood, they should serve me well as I take the fight to Scholomance and deal with Darkmaster Gandling.\n\nI bid you adieu for now." }
WordHunterWoW_QuestEN[31515] = { title = "Blades of the Anointed", description = "The problem with the Scarlet Crusade is that they keep coming back, even after death.\n\nBehind those resurrections is High Inquisitor Whitemane. With her death, so goes the Crusade.\n\nTo give her the final rest, we need two swords of legend, each with a lost but storied history.\n\nLuckily for me... er, us, these two blades of the anointed are at rest here within the monastery.\n\nFind them and once you've killed Whitemane, plunge the blades into her corpse to make the death permanent.", objectives = "Collect the two Blades of the Anointed.", progress = "<With one blade already in your possession, you move to take the other.>\n\n<An inscription on the statue behind the sword reads, \"The Hand of Providence\".>", completion = "<The second anointed blade floats just in front of the wet statue. Steam rises from the sword.>\n\n<You get the uncanny feeling that the Hand of Providence has been waiting for you.>" }
WordHunterWoW_QuestEN[31516] = { title = "Unto Dust Thou Shalt Return", description = "<You take the second anointed blade in hand and feel the power of both swords course through you.>\n\n<There is but one thing left to do. As the mysterious, hooded woman explained, to put an end to the Scarlet Crusade, you must thrust both blades into the corpse of High Inquisitor Whitemane.>", objectives = "Use the Blades of the Anointed on the corpse of High Inquisitor Whitemane to send her permanently to her final rest.", progress = "<The deed is not yet done. There can be no end to the Scarlet Crusade while Whitemane can come back from the dead.>", completion = "With Whitemane gone for good, the Scarlet Crusade is finished. It's just a matter of sweeping up the refuse.\n\nThank you, <name>. Not just for myself, but for everyone opposed to mindless hatred and bigotry.\n\nAnd, thank you for these two new blades. Anointed anew in her blood, they should serve me well as I take the fight to Scholomance and deal with Darkmaster Gandling.\n\nI bid you adieu for now." }
WordHunterWoW_QuestEN[31517] = { title = "Contending With Bullies", description = "We honor strength here, not brutality. It is unfortunate but there are some who come to my doorstep oblivious to this distinction.\n\nI have turned away one such challenger. In retaliation, he sacked the village of Yinying.\n\nGo to Yinying Village southeast of the temple, and face this \"Shonuf.\" Give him a lesson in true strength.", objectives = "Defeat Shonuf.", progress = "It is a fine line between proving one's strength, and bullying.", completion = "I commend your victory and thank you for dealing with that ruffian." }
WordHunterWoW_QuestEN[31518] = { title = "The Vale of Eternal Blossoms", description = "It's been many lifetimes since the gates to the valley were open, {name}.\n\nI wouldn't miss this for the world, and neither should you!\n\nMeet me at the southen edge of Kun-Lai Summit. I'll wait for you there.", objectives = "Speak to Anduin at the Gate of the August Celestials." }
WordHunterWoW_QuestEN[31519] = { title = "A Worthy Challenge: Yan-zhu the Uncasked", description = "{name}, I need you to assemble a hearty group and lead them into Stormstout Brewery. Activate the Challenger's Orb therein, and evaporate Yan-zhu the Uncasked.\n\nReturn to me when you've completed this challenge, and I shall reward you handsomely.", objectives = "Complete the Stormstout Brewery Challenge Mode.", completion = "You have my sincerest thanks, <name>. Without fine Stormstout brews to lighten the drudgery of the day, the world would be a dull place indeed." }
WordHunterWoW_QuestEN[31520] = { title = "A Worthy Challenge: Sha of Doubt", description = "{name}, I need you to assemble a hearty group and lead them into the Temple of the Jade Serpent. Activate the Challenger's Orb therein, and vanquish the Sha of Doubt.\n\nReturn to me when you've completed this challenge, and I shall reward you handsomely.", objectives = "Complete the Temple of the Jade Serpent Challenge Mode.", completion = "You have my gratitude, <name>. You've displayed great valor today, and the speed at which you completed the challenge surely will impress your friends and intimidate your foes." }
WordHunterWoW_QuestEN[31521] = { title = "To Be a Master", description = "There will come a day when you have mastered all that we have to teach you. When that day comes, it will be time for you to teach others in turn. When you have proven to yourself that you have mastered all the Ways, come back and speak with me.", objectives = "Make Black Pepper Steak, Sea Mist Rice Noodles, Mogu Fish Stew, Steamed Crab, Chun Tian Spring Roll and Mad Brewer's Breakfast, then return to the Guide to the Ways.", completion = "You have been a great student. Now you should share your knowledge with others. I hope you will speak with the Stock Master and take on an apprentice as soon as you can." }
WordHunterWoW_QuestEN[31522] = { title = "A Worthy Challenge: Sha of Hatred", description = "{name}, I need you to assemble a tranquil group and lead them into the Shado-Pan Monastery. Activate the Challenger's Orb therein, and rescue Taran Zhu from the Sha of Hatred.\n\nReturn to me when you've completed this challenge, and I shall reward you handsomely.", objectives = "Complete the Shado-Pan Monastery Challenge Mode.", completion = "Many blessings upon you, <name>. Driving hatred from this world so quickly deserves rich reward." }
WordHunterWoW_QuestEN[31523] = { title = "A Worthy Challenge: Xin the Weaponmaster", description = "{name}, I need you to assemble a nimble group and lead them into Mogu'shan Palace. Activate the Challenger's Orb therein, and put an end to Xin the Weaponmaster.\n\nReturn to me when you've completed this challenge, and I shall reward you handsomely.", objectives = "Complete the Mogu'shan Palace Challenge Mode.", completion = "Many thanks, <name>. Your martial prowess is second to none, and your alacrity is sure to strike fear in the hearts of your enemies." }
WordHunterWoW_QuestEN[31524] = { title = "A Worthy Challenge: Raigonn", description = "{name}, I need you to assemble a cracking group and lead them into the Gate of the Setting Sun. Activate the Challenger's Orb therein and lay waste to Raigonn.\n\nReturn to me when you've completed this challenge, and I shall reward you handsomely.", objectives = "Complete the Gate of the Setting Sun Challenge Mode.", completion = "That was a blow well struck, <name>. I've never seen a <class> fell a giant with such speed." }
WordHunterWoW_QuestEN[31525] = { title = "A Worthy Challenge: Wing Leader Ner'onok", description = "{name}, I need you to assemble an eagle-eyed group and lead them into the Siege of Niuzao Temple. Activate the Challenger's Orb and ground Wing Leader Ner'onok.\n\nReturn to me when you've completed this challenge, and I shall reward you handsomely.", objectives = "Complete the Siege of Niuzao Temple Challenge Mode.", completion = "<name>, that was amazing. Ner'onok is a master tactician, and you schooled him handily." }
WordHunterWoW_QuestEN[31526] = { title = "A Worthy Challenge: Durand", description = "{name}, I need you to assemble a stout group and lead them into Scarlet Monastery. Activate the Challenger's Orb therein, and smite Durand with righteous fury.\n\nReturn to me when you've completed this challenge, and I shall reward you handsomely.", objectives = "Complete the Scarlet Monastery Challenge Mode.", completion = "<name>, you're a stalwart <class>. Your friends and guild mates will surely notice the speed and ferocity with which you conquered the Scarlet Monastery." }
WordHunterWoW_QuestEN[31527] = { title = "A Worthy Challenge: Flameweaver Koegler", description = "{name}, I need you to assemble a cunning group and venture forth into the depths of Scarlet Halls. Activate the Challenger's Orb therein, and put a stop to Flameweaver Koegler's book-burning ways.", objectives = "Complete the Scarlet Halls Challenge Mode.", completion = "Excellent work, <name>. Just the thought of him burning up that beautiful library makes me shudder. Your friends will appreciate the speed with which you dispatched him." }
WordHunterWoW_QuestEN[31528] = { title = "A Worthy Challenge: Darkmaster Gandling", description = "{name}, I need you to assemble a fearless group and lead them into the depths of Scholomance. Activate the Challenger's Orb, and cleanse Scholomance of Darkmaster Gandling's evil presence.\n\nReturn to me when you've completed this challenge and I shall reward you handsomely.", objectives = "Complete the Scholomance Challenge Mode.", completion = "<name>, you've done a great service. May the skeletons of the dead remain peaceful now that Gandling no longer seeks to disturb their slumber." }
WordHunterWoW_QuestEN[31529] = { title = "Mission: Culling The Vermin", description = "I was sent to this valley to protect The Heartland from any potential threats.\n\nI've identified a high priority target. The Springtail vermin burrow into the mountain cliffs, high above the farmlands.\n\nLeft unchecked, their numbers will multiply, and they will make their way down to the fields below.\n\nThey must be eliminated.", objectives = "Kill 12 Springtail vermin.", progress = "What do you have to report?", completion = "The targets are eliminated? Well done, <class>." }
WordHunterWoW_QuestEN[31530] = { title = "Mission: The Hozen Dozen", description = "I've been watching the hozen since I arrived, and I don't like the pattern of activity that I'm seeing in their camp.\n\nMultiple hozen travel down the mountain under the cover of night, pillaging supplies from the farmlands below.\n\nWe must stop their rampant theft. I have been thinning their numbers when I can, but one soldier alone is not enough.\n\nI need your help. Kill as many of the hozen as you can.", objectives = "Kill 12 Springtail vermin." }
WordHunterWoW_QuestEN[31531] = { title = "Mission: Aerial Threat", description = "I've identified another high risk target, one that most people would not suspect.\n\nThe cliff kites soaring above the hills to the east are quite dangerous.\n\nI have seen them swooping down to the farms, snatching grain and seed when no one is looking.\n\nIn order to protect the farms, we must thin their numbers.", objectives = "Kill 12 Cliff Kites.", progress = "How goes the mission?", completion = "I knew you would carry out the mission without any problems. Well done, <name>." }
WordHunterWoW_QuestEN[31532] = { title = "Mission: Predator of the Cliffs", description = "During my routine patrol of the mountains this morning, I spotted a huge white bird diving down to the farmlands.\n\nIt lifted an entire yak in its talons and disappeared among the cliffs.\n\nToday a yak, tomorrow a farmhand!\n\nWe must eliminate this bird before it chooses its next victim.", objectives = "Kill the Great Cliff Hawk.", completion = "You did it, <name>! I feel at ease knowing the Valley safer now, because of you." }
WordHunterWoW_QuestEN[31533] = { title = "The Perfect Feather", description = "This beautifully pristine feather is unlike any you have seen before in the Valley.\n\nThere is one person who might be interested in seeing this feather.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Bring the feather to Old Hillpaw at Old Hillpaw's House or Halfhill Market in the Valley of the Four Winds.\n\nProvided item:" }
WordHunterWoW_QuestEN[31534] = { title = "The Beginner's Brew", description = "Can you keep a secret, {name}?\n\nI've been trying my hand at brewing. All I've got is this old hand-made still, but it still works pretty good.\n\nI've got an idea for a new brew, but I need some ingredients.\n\nI'm awful shy around the townsfolk, but I've seen you making friends all around.\n\nWould you be willing to ask the farmers for some ingredients for me?", objectives = "Collect 1 Sweet Lakemelon from Haohan Mudclaw, 1 Fuzzy Peach from Gina Mudclaw, 1 Black Cherries from Fish Fellreed, and 1 Red Radish from Farmer Fung.", progress = "I don't know what it is. Maybe it's staring at that brewery day in and day out, but I just feel... like I want to brew the best beer in the Valley... no... all of Pandaria!\n\nOh, it's a silly dream, isn't it?", completion = "You got them! This is wonderful, <name>!\n\nI'll get started on the brew as soon as I can." }
WordHunterWoW_QuestEN[31535] = { title = "Replenishing the Pantry", description = "People come from all over Pandaria to learn cooking from the Ironpaw family.  We take great pride not only in being the best chefs, but also in passing what we know onto others.  That's why we try to charge as little as possible for cooking lessons.\n\nThis means, however, that we often find ourselves in shortage of cooking ingredients for the lessons.  Would you donate some to the school, to help out students who cannot afford it?", objectives = "Bring Nam Ironpaw a Bundle of Groceries. Bundles of Groceries can be created by using containers sold by Merchant Cheng.", progress = "It's hard to learn how to cook if you don't have ingredients to cook with.", completion = "Your help is very much appreciated. This will make a great difference for some of our students." }
WordHunterWoW_QuestEN[31536] = { title = "Preserving Freshness", description = "To preserve maximum freshness, cooking ingredients need to be stored properly. Fortunately, Merchant Cheng over there sells good containers.  I hate to send you on such a menial errand, but would you go purchase an empty tiger meat basket for me? ", objectives = "Bring Nam Ironpaw an Empty Tiger Meat Basket.", progress = "Ingredients will spoil if not stored properly.", completion = "Ah, good.  Now these ingredients will stay fresh until we're ready to cook." }
WordHunterWoW_QuestEN[31537] = { title = "Ella's Taste Test", description = "Well, I finally got the brew made, but I won't know if it's any good unless some people taste it.\n\nWould you take my brew and see what the folks in Halfhill think?\n\nI... I couldn't face them myself.", objectives = "Ask Jogu the Drunk, Bobo Ironpaw, Farmer Yoon, and Nana Mudclaw what they think of Ella's Brew.", completion = "Really? That's what they really said? Wow!" }
WordHunterWoW_QuestEN[31538] = { title = "A Worthy Brew", description = "There's one final person who needs to taste my brew.\n\nI've heard that he's traveled far and wide, and tasted drinks from all over the world.\n\nHe happens to be in town, and I'd like to know what he thinks of my skills.", objectives = "Ask Chen Stormstout to taste Ella's Brew.", completion = "You aren't pulling my leg are ya, <name>? If he really said that, well... I guess... I guess it means I can do it, after all!\n\nThank you, <name>. You've really helped me gain confidence in myself." }
WordHunterWoW_QuestEN[31539] = { title = "A Thing of Beauty", description = "We live in a world of magic.The few among us who are skilled can imbue this magic into the things we craft and give them power. Such things are valued.\n\nFewer still, however, are those among us who can create things that are cherished through the ages not because they are imbued with power, but because of their great beauty.\n\nThe Temple of the Jade Serpent has commissioned us for such a work, and I believe you are the worthiest among us.  Will you accept the commission?", objectives = "Craft a Commissioned Painting and bring it to Inkmaster Wei at the Arboretum in the Jade Forest. The recipe can be found in your Inscription pane under Quests.", progress = "This is a grand project. It will take much time and effort, even from a craftsman such as you.", completion = "This... This is beyond my wildest expectations. This will be treasured and preserved for generations to come." }
WordHunterWoW_QuestEN[31540] = { title = "Staves for Tian Monastery", description = "It seems like the Tian Monsatery is training a lot of monks this year. We've received a huge commission for staves. And by huge, I mean HUGE.\n\nCould you take on part of the commission? I'd very much appreciate it. You will receive the rewards for your portion, of course.", objectives = "Craft 3 Ghost Iron Staves and 2 Rain Poppy Staves. Bring them to Inkmaster Wei at the Arboretum in the Jade Forest.", progress = "So many staves! How many monks do they have?!", completion = "Fine craftsmanship.  The monks will appreciate these." }
WordHunterWoW_QuestEN[31541] = { title = "Set in Jade", description = "One of the greatest poets of our time is Master Kwang. He has composed a poem of great beauty, and a merchant in Halfhill would like to have these words inscribed in stone, to display proudly in her home. She has requested a scribe of great skill to take on this job. Will you accept the commission?", objectives = "Craft an Engraved Jade Disc and bring it to Inkmaster Jo Po at the Arboretum, in the Jade Forest. The recipe can be found in your Inscription pane under Quests.", progress = "How is it coming along?", completion = "Beautiful. This will be cherished." }
WordHunterWoW_QuestEN[31542] = { title = "Incarnadine Ink", description = "The practice of caligraphy is an old custom in Pandaria. I am working on a piece about an ancient war, so I seek an ink that is suitable to the subject matter.\n\nI have searched high and low for the right hue, but it eludes me. Can you think of  a way to achieve the color I am seeking?", objectives = "To attain the color Inkmaster Glenzu is seeking will require an unconventional source of pigment. His description evokes in your mind the color of blood - specifically the blood of tigers...\n\n Craft 5 Incarnadine Ink. The recipe can be found in your Inscription pane under Quests.", progress = "I cannot find the right color!", completion = "Where did you... How did you... This is perfect!" }
WordHunterWoW_QuestEN[31543] = { title = "Portrait of a Lady", description = "Many great pieces of art are results of great love.  A merchant in Halfhill wishes to have a portrait made for his beloved, as a birthday present.  Will you accept this commission?", objectives = "Paint a Portrait of Madam Goya and bring it to Inkmaster Glenzu at the Arboretum, in the Jade Forest. The recipe can be found in your Inscription pane under Quests.", progress = "It is a wonderful thing to see a man so in love.", completion = "A fine painting." }
WordHunterWoW_QuestEN[31544] = { title = "A Tribute to the Dead", description = "All things must come to an end - even the life of a good man.  A family in Kun Lai has commissioned a monument for their beloved patriarch who has passed on recently.  Will you accept the commission?", objectives = "Create an Inscribed Monument Stone and bring it to Inkmaster Jo Po at the Arboretum, in the Jade Forest. The recipe can be found in your Inscription pane under Quests.", progress = "Respect for the dead is part of our traditions.", completion = "A fine work to honor a fine man." }
WordHunterWoW_QuestEN[31545] = { title = "The Finer Things", description = "The Pandaria Treasure Society is interested in purchasing finely crafted goods from skilled jewelcrafters such as yourself.  The items will be catalogued, and the most exceptional cuts stored in a secret vault, while the rest are sold to refresh our funds.\n\nOur goal is to eventually create a unique collection for a special event.", objectives = "Bring the requested goods to any member of the Pandaria Treasure Society in The Valley of Eternal Blossoms." }
WordHunterWoW_QuestEN[31548] = { title = "Learning the Ropes", description = "Now that you are a pet trainer, it's time to test your skills!\n\nHead out into the valley and pick a fight with a battle pet.  Come back to me after you have won and I will continue your training.  Good luck!", objectives = "Win a pet battle.", completion = "Nice work, <name>!  You're better with those pets than I thought!" }
WordHunterWoW_QuestEN[31549] = { title = "On The Mend", description = "Now that you have won a battle, we need to heal up your pets so they can fight another day!  Visit Shelby Stoneflint, our local stable master, to heal and revive your pets.", objectives = "Heal your pets to full health by visiting Shelby Stoneflint the Stable Master.", completion = "Now those look like some healthy pets, <name>.  Remember, you can heal and revive your entire collection of pets at any time by visiting a stable master." }
WordHunterWoW_QuestEN[31550] = { title = "Got one!", description = "Great work so far {name}.  You are going to be a pro at this pet stuff before you know it.  Now it's time to catch a pet of your own!\n\nHead back out and find a battle pet to fight, engage it in battle and throw your trap once it's low on health.  Bring your catch back for me to see once you are finished.\n\nRemember, you need at least one pet at level 3 to use your trap!", objectives = "Catch a battle pet.", completion = "I see... an excellent choice. You're on your way to building up a great team!\n\nRemember, you have the opportunity to catch any pet you can fight, so go ahead and try to get as many as you can during your adventures." }
WordHunterWoW_QuestEN[31551] = { title = "Got one!", description = "Great work so far, {name}!  You are going to be a pro at this pet stuff before you know it.  Now it's time to catch a pet of your own!\n\nHead back out and find a battle pet to fight, engage it in battle, and throw your trap once it's low on health.  Bring your catch back for me to see once you are finished.\n\nRemember, you need at least one pet at level 3 to use your trap!", objectives = "Catch a battle pet.", completion = "I see... an excellent choice. You're on your way to building up a great team!\n\nRemember, any pet you can fight, you can catch, so go ahead and try to get as many as you can during your adventures." }
