WordHunterWoW_QuestEN[31598] = { title = "Kypa'rak's Core", description = "<As the ringworm tumbles apart, a massive chunk of organic kyparite falls from its core. Someone at Klaxxi'vess will want to see this.>", objectives = "Bring the Massive Kyparite Core to Ambersmith Zikk at Klaxxi'vess.\n\nProvided item:", completion = "Interesting. You were wise to spot the importance of this, Wakener. Organic kyparite is highly valuable to us.\n\nHere, a reward. In fair trade." }
WordHunterWoW_QuestEN[31599] = { title = "The Matriarch's Maw", description = "<The enormous mandibles of the kunchong matriarch Karanosh should be of value to someone in Klaxxi'vess.>", objectives = "Bring the Enormous Kunchong Mandibles to Ambersmith Zikk at Klaxxi'vess.\n\nProvided item:", completion = "I recognize those mandibles. Karanosh ate my brother, you know.\n\nOf course, I have millions of brothers.\n\n<Zikk cackles.>" }
WordHunterWoW_QuestEN[31600] = { title = "Enable Scenarios", description = "", objectives = "" }
WordHunterWoW_QuestEN[31603] = { title = "Seeds of Fear", description = "", objectives = "Some of the corrupted kypari were shattered during the swarm's horrid march, casting slivers of sha-infested amber across the land.\n\nBring me any that you find in your travels, so that they may be disposed of properly.", progress = "Some of the corrupted kypari were shattered during the swarm's horrid march, casting slivers of sha-infested amber across the land.\n\nBring me any that you find in your travels, so that they may be disposed of properly.", completion = "As long as these shards blanket the land, our home will be a place of fear and death." }
WordHunterWoW_QuestEN[31604] = { title = "Assault on Zan'vess", description = "The island settlement of Zan'vess is the last hope for the future of my kind. Although the mantid there are loyal to Shek'zeer, the kypari itself has been spared the sha corruption that has befallen the mainland.\n\nStill, under imperial orders, the Zan'thik are draining sap at an unsustainable rate.\n\nYou have proven yourself a capable asset. The council wants you to lead an assault on the island. Disrupt their operations and keep the kypari healthy.\n\nSpeak with me when you are ready to begin.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Complete the Assault on Zan'vess scenario. Speak with Klaxxi'va Vor or use the Looking For Dungeon tool to begin." }
WordHunterWoW_QuestEN[31605] = { title = "The Zan'thik Dig", description = "We have just intercepted a message from an adjunct on Zan'vess. Yaungol laborers there have unearthed a paragon in the amber quarry on the back side of the island.\n\nGet there immediately and free him before the Zan'thik destroy him!", objectives = "Locate the unearthed paragon in the Amber Quarry on Zan'vess.", completion = "<From the looks of it, this mantid was just recently broken out of his chamber. He lets out a hacking cough.>\n\n...Diss-ec...tor... has... returned..." }
WordHunterWoW_QuestEN[31606] = { title = "The Dissector Wakens", description = "You are... not like the others...\n\nI hear the Klaxxi calling... <cough>\n\nI just need a moment.", objectives = "Hold off the Zan'thik while Rik'kal wakens.", progress = "<cough cough>\n\nMy head...", completion = "Look at you! Many parts and pieces... yes... and all of them so good at killing. Fascinating.\n\nI must pick your brain some time. Muhahah." }
WordHunterWoW_QuestEN[31607] = { title = "Tracking Event: Finished Spiteful Spirits & Hatred Becomes Us", description = "", objectives = "" }
WordHunterWoW_QuestEN[31609] = { title = "The Wrath of Shek'zeer", description = "The rest of the freed paragons are scattered around the Heart of Fear, fighting off the mantid swarm. They may need your help!", objectives = "Rout the Mantid Swarm by slaying Akkolon, Shox'tik, the Manifestation of Terror, and 25 mantid subjugates.", completion = "The siege is broken, for now." }
WordHunterWoW_QuestEN[31611] = { title = "The Kun-Lai Kicker", description = "Have you ever seen the Brewmoon Festival?\n\nThe good folks of Binan Village host quite a party. And tonight's festivities are brew-catered by none other than yours truly here.\n\nI am making my famous Kun-Lai Kicker!\n\nThink you might come and join us for the festivities? It should be a completely relaxing event with absolutely no danger whatsoever.", objectives = "Protect the Brewmoon Festival.", progress = "Ah, still alive I see...", completion = "So I may have underestimated how safe it is to brew these days." }
WordHunterWoW_QuestEN[31612] = { title = "Shadow of the Empire", description = "You only understand part of our order. You are an outsider, and have been treated as such.\n\nIt is no longer appropriate that we keep our secrets from you. There is something you should see.", objectives = "Accompany Kil'ruk the Wind-Reaver into the chamber below Klaxxi'vess.", progress = "There is something you should see.", completion = "<Kil'ruk gives you a strange glance.>\n\nThe Klaxxi'va may never accept you fully. Their xenophobic minds are closed to the possibility of a useful <race>.\n\nI, for one, have been proud to fight by your side, <class>. Your presence, and your assistance, do us great honor." }
WordHunterWoW_QuestEN[31613] = { title = "Volatile Greenstone Brew", description = "I am working on a batch of my famous Volatile Greenstone Brew.\n\nShould be superb in countering the rascals and mischievous elementals we have been seeing around the mines lately.\n\nTell you what, how about you round up some of your friends and bring them back here to try out a round.\n\nFirst one's on the house!", objectives = "Aid in the defense of Greenstone Village.", progress = "Sprites, jade destroyers, rocks that talk. This world is becoming a troublesome one.\n\nBut... nothing that can not be solved with a strong brew and winning smile.\n\nAnd a solid punch or two.", completion = "I see you put my Volatile Greenstone Brew to good use. Well done, <class>!" }
