WordHunterWoW_QuestEN[31806] = { title = "Test Quest", description = "This artifact has been restored to a remarkably excellent condition.  Perhaps you will put it on display at the Seat of Knowledge, so that lorewalkers and archaeologists can study it.", objectives = "Put the artifact on display." }
WordHunterWoW_QuestEN[31807] = { title = "Tracking Quest: Opened the Golden Valley II", description = "", objectives = "" }
WordHunterWoW_QuestEN[31808] = { title = "Rampage Against the Machine", description = "Kovok has progressed at an astonishing rate. Perhaps the years in hibernation effected his growth process...\n\nWhatever the reason, this could not have come at a better time. I believe it is time to test his abilities.\n\nYou have done so much to aid in his training. It is only fitting that you assist him in his first battle.\n\nI've already guided him to the edge of the scar. Find him and destroy Shek'zeer's army!", objectives = "Kill 200 Mantid while controlling Kovok in the Scar.", progress = "Was the battle glorious?! How many of Shekzeer's army fell to Kovok?", completion = "I was able to glimpse moments of the battle through your mind. It looked to be a massacre! Well done!" }
WordHunterWoW_QuestEN[31809] = { title = "Remnants of Anger", description = "As you look upon the severed claw of the defeated Sha of Anger, you realize that Ban Bearheart, commander of the Shado-Pan in Townlong Steppes, would want to know of your victory.", objectives = "Deliver the Claw of Anger to Ban Bearheart at the Shado-Pan Garrison in Townlong Steppes.", progress = "<Ban looks at you with narrowed eyes.>\n\nSomething about you is... different. Changed.", completion = "<As you present the Claw to Ban, his eyes grow wide with the realization of what you have done.>\n\nI see now what about you has changed.\n\nYou have done the impossible. The Shado-Pan shall record your name, and honor it as long as we stand watch over this land." }
WordHunterWoW_QuestEN[31810] = { title = "Riding the Skies", description = "I can no longer call myself your teacher, {name}.\n\nYou have proven yourself worthy of your cloud serpent.\n\nToday, you shall join our ranks. Are you ready?", objectives = "Join the Order of the Cloud Serpent.", completion = "Today, we become brethren. Congratulations on joining the Order of the Cloud Serpent. Let us ride together!" }
WordHunterWoW_QuestEN[31811] = { title = "Riding the Skies", description = "I can no longer call myself your teacher, {name}.\n\nYou have proven yourself worthy of your cloud serpent.\n\nToday, you shall join our ranks. Are you ready?", objectives = "Join the Order of the Cloud Serpent.", completion = "Today, we become brethren. Congratulations on joining the Order of the Cloud Serpent. Let us ride together!" }
WordHunterWoW_QuestEN[31812] = { title = "Zunta, The Pet Tamer", description = "I can tell you have been honing your pet battle skills, {name}.  I think it's time for you to take on a real challenge.\n\nZunta can be found near the Tor'kren Farm south of Orgrimmar.  He is an up and coming wild pet tamer and I think it's time you faced him in battle!", objectives = "Defeat Zunta in a pet battle.", progress = "Who be sendin' you to face Zunta?", completion = "Ah, Varzok. Yes, I know him well. He be makin' no mistake in sendin' you here." }
WordHunterWoW_QuestEN[31813] = { title = "Dagra the Fierce", description = "Der be another trainer not far from here that you ought to fight to test your worth.\n\nDagra the Fierce waits on the northern slope of Thorn Hill, east of The Crossroads. If you be beatin' her, you just might have what it takes.", objectives = "Defeat Dagra the Fierce in a pet battle.", progress = "I fear nothing. I will not be defeated!", completion = "You fight with the determination of one who does not fear defeat, but does not tolerate it, either. You will go far." }
WordHunterWoW_QuestEN[31814] = { title = "Analynn", description = "Determination is naught without proper challenge.\n\nFind Analynn wandering the roads in western Ashenvale. She is a bit...eccentric...but a fine trainer nonetheless! Fighting her will harden your team.", objectives = "Defeat Analynn in a pet battle.", completion = "You do not understand. I have not been defeated, merely set back." }
WordHunterWoW_QuestEN[31815] = { title = "Zonya the Sadist", description = "{name}, a rare opportunity has arisen that I think you will be interested in.\n\nZonya the Sadist in southern Stonetalon Mountains has returned to the battle scene. I must suggest that you face her to further hone your own abilities as a tamer.", objectives = "Defeat Zonya the Sadist in a pet battle.", progress = "You be messin' with da wrong troll, mon.", completion = "Did you enjoy the taste of victory? It'll be your last, mon. Things do not get easier from here." }
WordHunterWoW_QuestEN[31816] = { title = "Traitor Gluk", description = "Are you up for an adventure? Bill the Pirate, local star tamer down in the Cape of Stranglethorn, has issued an open challenge to prepared trainers!\n\nYou can find Bill the Pirate in the southern Cape of Stranglethorn, walking the local roads to find potential fights.You will receive:", objectives = "Defeat Bill the Pirate in a pet battle." }
WordHunterWoW_QuestEN[31817] = { title = "Merda Stronghoof", description = "Are you ready for a real measure of your prowess, {race}?\n\nMerda Stronghoof has made camp at da place dey call Karnum's Glade in the Cenarion Wildlands of Desolace. Fighting a trainer as powerful as her will put your skills to the test, eh?", objectives = "Defeat Merda Stronghoof in a pet battle.", completion = "The resilience of Desolace cannot compare to your own desire to grow. I applaud your efforts." }
WordHunterWoW_QuestEN[31818] = { title = "Zunta", description = "Think you can take me again, eh?", objectives = "Defeat Zunta in a pet battle.", progress = "You be a worthy opponent, mon.", completion = "Lay off, mon! Lay off! You win!" }
WordHunterWoW_QuestEN[31819] = { title = "Dagra the Fierce", description = "You climbed this mountain once more only to face your own demise.", objectives = "Defeat Dagra the Fierce in a pet battle.", progress = "You have much to learn before I will call you my superior.", completion = "Impossible!" }
WordHunterWoW_QuestEN[31820] = { title = "A Present for Teacher", description = "I'm all caught up with the other kids now, even though I started very late. Now I can join the regular classes!\n\nI made you an apron to show you how much I appreciate all you've done for me. I hope you like it?", objectives = "Receive Nomi's gift.I'm all caught up with the other kids now, even though I started very late. Now I can join the regular classes!\n\nI made you an apron to show you how much I appreciate all you've done for me. I hope you like it?", completion = "Thank you so much." }
WordHunterWoW_QuestEN[31821] = { title = "Level Up!", description = "Good, good. It's important to keep your pets healthy and ready for battle.\n\nMy next task for you is to fight a few battles and raise a pet to level 3.  Once you do that, come back and see me and we can talk about catching your own pets!", objectives = "Raise a pet to level 3.", completion = "Great job <name>.  Next up, catching your own pets!" }
