WordHunterWoW_QuestEN[31834] = { title = "Begin Your Training: Master Cheng", description = "Greetings, {name}. Welcome to the Peak of Serenity.  It is here that we monks train and hone our skills in the martial arts.  The time has come for you to begin your training.  Speak with Master Cheng in the Training Grounds below us to begin.", objectives = "Speak with Master Cheng in the Training Grounds and complete your training with him.", progress = "Complete your training with Master Cheng.", completion = "I hear from Master Cheng that your training went well.  Come back again in the future to continue your training." }
