WordHunterWoW_QuestEN[31847] = { title = "Better Dead than Dread", description = "I am sure many of our associates will be requesting your services after your victory here. But I have received a request for aid from our defenders at the wall along the Dread Wastes.\n\nIf you would assist them, then take a kite and check in with Bowmistress Li.\n", objectives = "Speak with Bowmistress Li on the Serpent's Spine.", completion = "A volunteer for Dread Wastes duty? I think you might be the first.\n\nPleased to meet you." }
WordHunterWoW_QuestEN[31850] = { title = "Eric Davidson", description = "Ah, so you've braved the woods again to face me in battle. I accept your brazen challenge to my vicious spawn.", objectives = "Defeat Eric Davidson in a pet battle.", progress = "Do you feel your imminent defeat creeping up on you, like a spider to its struggling prey?", completion = "Your risk has paid its reward." }
WordHunterWoW_QuestEN[31851] = { title = "Bill Buckler", description = "So ye've come fer another round, have ye?\n\nI'll show ya why they be callin' me the shcourge o' the vale!", objectives = "Defeat Bill Buckler in a pet battle.", completion = "You be the victor today, lad, but next time I won't be takin' it so eashy on ye!" }
WordHunterWoW_QuestEN[31852] = { title = "Steven Lisbane", description = "You dare to challenge me again? This time, I do believe our battle is going to sway in my favor!", objectives = "Defeat Steven Lisbane in a pet battle.", progress = "I do so very much enjoy our bouts.", completion = "A thrilling match! Splendid! Well done indeed!" }
WordHunterWoW_QuestEN[31853] = { title = "All Aboard!", description = "You hear all of that, {name}? There are Alliance that need killing and I need to round up a veteran crew.\n\nYou're coming with me!\n\nWe won't be returning until our assignment's complete, so round up your things and make ready.\n\nI'll be aboard a newly commissioned gunship over Bladefist Bay.\n\nDon't keep me waiting!", objectives = "Speak to General Nazgrim aboard Hellscream's Fist.", completion = "Welcome aboard Hellscream's Fist, <name>!\n\nThis'll be her maiden voyage. Ain't she a beauty?" }
WordHunterWoW_QuestEN[31854] = { title = "Analynn", description = "I see you have once again found me. I presume you wish to do battle once more? Yes, let's.", objectives = "Defeat Analynn in a pet battle.", completion = "Your pets are ecstatic about their victory. I hope you are as well." }
WordHunterWoW_QuestEN[31855] = { title = "The Peak of Serenity - Continue Your Training", description = "The time has come for you to return to the Peak of Serenity to continue your training.  Use Zen Pilgrimage to return there and speak with Master Hight when you arrive.", objectives = "Use Zen Pilgrimage to travel to the Peak of Serenity. Speak to Master Hight in the Shrine of the Ox when you arrive.", completion = "Welcome back, <name>.  It is time to continue your training." }
WordHunterWoW_QuestEN[31856] = { title = "The Peak of Serenity - Begin Your Training", description = "The time has come for you to venture to the Peak of Serenity to begin training in the ways of the Monk.  Use Zen Pilgrimage to go there and speak with Master Hight when you arrive.", objectives = "Use Zen Pilgrimage to travel to the Peak of Serenity. Speak to Master Hight in the Shrine of the Ox when you arrive.", completion = "Welcome, <name>.  It is time to begin your training." }
