WordHunterWoW_QuestEN[31862] = { title = "Zonya the Sadist", description = "The prey be walkin' to the predator's territory, unaware of the danger that he is in. You be givin' Zonya no trouble dis time.", objectives = "Defeat Zonya the Sadist in a pet battle.", progress = "Pain be the sound of victory, mon.", completion = "You think yourself victorious, but I be growin' stronger with each defeat." }
