WordHunterWoW_QuestEN[31870] = { title = "Cassandra Kaboom", description = "Cassandra Kaboom is a fierce tamer, known for her mechanical pets. She should serve as the next step on your journey to greatness.\n\nFind her in Southern Barrens near the Frazzlecraz Motherlode and challenge her. Beating Cassandra will surely prove yourself in the eyes of Varzok.\n\nGood luck.", objectives = "Defeat Cassandra Kaboom in a pet battle.", progress = "What's a <race> like you doin' in a place like this?", completion = "Woah! You really are somethin'!" }
WordHunterWoW_QuestEN[31871] = { title = "Traitor Gluk", description = "You beat Gluk before, but now Gluk lay da smackdown on puny {race}!", objectives = "Defeat Traitor Gluk in a pet battle.", completion = "No! Gluk no lose! Rematch!" }
WordHunterWoW_QuestEN[31872] = { title = "Merda Stronghoof", description = "Just as the land continues to grow, my team is stronger than ever. Are you sure you wish to combat me? There is no shame in admitting defeat now.", objectives = "Defeat Merda Stronghoof in a pet battle.", completion = "Your victory is well-deserved. Your skills are superior to my own." }
WordHunterWoW_QuestEN[31876] = { title = "The Inkmasters of the Arboretum", description = "I have heard that the Inkmasters at the Arboretum are in need of aid from a scribe of great skill.  You should speak with Inkmaster Wei, if you wish to help.", objectives = "Speak with Inkmaster Wei at the Arboretum in the Jade Forest.", completion = "Ah, a scribe of great skill. Some of us here could really use your help." }
WordHunterWoW_QuestEN[31877] = { title = "The Inkmasters of the Arboretum", description = "I have heard that the Inkmasters at the Arboretum are in need of aid from a scribe of great skill.  You should speak with Inkmaster Wei, if you wish to help.", objectives = "Speak with Inkmaster Wei at the Arboretum in the Jade Forest.I have heard that the Inkmasters at the Arboretum are in need of aid from a scribe of great skill. You should speak with Inkmaster Wei, if you wish to help.You will receive:" }
