WordHunterWoW_QuestEN[31886] = { title = "Dread Space", description = "Shado-Pan marksmen keep a constant watch over the Dread Wastes from the top of the Serpent's Spine. They would surely welcome the aid of a skilled {class} such as yourself.\n\nTake a kite and check in with Bowmistress Li.", objectives = "Speak with Bowmistress Li on the Serpent's Spine.", completion = "A volunteer for Dread Wastes duty? I think you might be the first.\n\nPleased to meet you." }
WordHunterWoW_QuestEN[31887] = { title = "Pet Battle Trainers: Kalimdor", description = "It's time to put your battle skills to a true test.\n\nYou will find Steven Lisbane wandering the roads in the southern parts of Northern Stranglethorn. Seek him out and see who the superior tamer is!You will receive:", objectives = "Defeat Steven Lisbane in a pet battle." }
WordHunterWoW_QuestEN[31888] = { title = "Pet Battle Trainers: Kalimdor", description = "It's time to put your battle skills to a true test.\n\nYou will find Steven Lisbane wandering the roads in the southern parts of Northern Stranglethorn. Seek him out and see who the superior tamer is!You will receive:", objectives = "Defeat Steven Lisbane in a pet battle." }
WordHunterWoW_QuestEN[31889] = { title = "Battle Pet Tamers: Kalimdor", description = "Now that you've had a real chance to hone your skills, you're ready to venture out into the world of pet battles in full.\n\nThere are five tamers throughout Kalimdor that I'd like you to defeat: Traitor Gluk in Feralas, Grazzle the Great in Dustwallow Marsh, Kela Grimtotem in Thousand Needles, Zoltan in Felwood, and Elena Flutterfly in Moonglade.\n\nIf you are able to best them, you will be ready to venture further.", objectives = "Defeat Traitor Gluk, Grazzle the Great, Kela Grimtotem, Zoltan, and Elena Flutterfly in pet battles." }
WordHunterWoW_QuestEN[31890] = { title = "Pet Battle Trainers: Kalimdor", description = "It's time to put your battle skills to a true test.\n\nYou will find Steven Lisbane wandering the roads in the southern parts of Northern Stranglethorn. Seek him out and see who the superior tamer is!You will receive:", objectives = "Defeat Steven Lisbane in a pet battle." }
WordHunterWoW_QuestEN[31891] = { title = "Battle Pet Tamers: Kalimdor", description = "Now that you've had a real chance to hone your skills, you're ready to venture out into the world of pet battles in full.\n\nThere are five tamers throughout Kalimdor that I'd like you to defeat: Traitor Gluk in Feralas, Grazzle the Great in Dustwallow Marsh, Kela Grimtotem in Thousand Needles, Zoltan in Felwood, and Elena Flutterfly in Moonglade.\n\nIf you are able to best them, you will be ready to venture further.", objectives = "Defeat Traitor Gluk, Grazzle the Great, Kela Grimtotem, Zoltan, and Elena Flutterfly in pet battles." }
WordHunterWoW_QuestEN[31892] = { title = "Battle Pet Trainers: Kalimdor", description = "The very same trainers you bested before in Kalimdor have challenged you once more. No doubt they have not forgotten your last victory!\n\nSeek them out and show them your prowess!You will receive:", objectives = "Defeat Elena Flutterfly, Cassandra Kaboom, Golbo the Great, Zoltan, and Kela Grimtotem in pet battles." }
WordHunterWoW_QuestEN[31893] = { title = "Battle Pet Trainers: Kalimdor", description = "The same five trainers you defeated in Kalimdor have foolishly once more challenged you to battle.\n\nShow them no mercy!You will receive:", objectives = "Defeat Elena Flutterfly, Cassandra Kaboom, Golbo the Great, Zoltan, and Kela Grimtotem in pet battles." }
WordHunterWoW_QuestEN[31894] = { title = "A Delicate Balance", description = "The calling to be a Shado-pan is one to bring balance and harmony to this land. It is our duty to ensure balance is maintained, {name}.\n\nThe yaungol activity in Townlong is threatening this balance and must be stopped before it is too late.\n\nWe've had sightings of yaungol in the Sumprushes. The reports indicate they are attacking the mist lurkers in the area. Find out why and put an end to it! ", objectives = "Speak with Orbiss in the Sumprushes.", completion = "<Orbiss groans at you in agony.>\n\nSo, the shado-pan have sent you to see what the yaungol are doing? Well, do you see?" }
WordHunterWoW_QuestEN[31895] = { title = "Better Off Dread", description = "It's time we go to the source, {name}!\n\nShado-Pan marksmen keep a constant watch over the Dread Wastes from the top of the Serpent's Spine. They would surely welcome the aid of a skilled {class} such as yourself.\n\nSeek out Bowmistress Li atop the Serpent's Spine on the border of Dread Wastes.", objectives = "Speak with Bowmistress Li on the Serpent's Spine.", completion = "A volunteer for Dread Wastes duty? I think you might be the first.\n\nPleased to meet you." }
WordHunterWoW_QuestEN[31897] = { title = "Grand Master Trixxy", description = "Word around the master tamers in Kalimdor is you're the new hotshot that's making such a buzz. Why don't you come down to my training grounds in the Ice Thistle Hills in Winterspring so I can show you how it's done?", objectives = "Defeat Stone Cold Trixxy in a pet battle.", progress = "You're tougher than you look!", completion = "You really are some sort of hotshot, aren't ya? You won't be so lucky next time!" }
WordHunterWoW_QuestEN[31902] = { title = "Battle Pet Tamers: Eastern Kingdoms", description = "Now that you've had a real chance to hone your skills, you're ready to venture out into the world of pet battles in full.\n\nThere are five tamers throughout the Eastern Kingdoms that I'd like you to defeat: David Kosse in The Hinterlands, Deiza Plaguehorn in Eastern Plaguelands, Kortas Darkhammer in Searing Gorge, Everessa in Swamp of Sorrows, and Kortas' brother, Durin Darkhammer, in Burning Steppes.\n\nIf you are able to best them, you will be ready to venture further.", objectives = "Defeat David Kosse, Deiza Plaguehorn, Kortas Darkhammer, Everessa, and Durin Darkhammer in pet battles." }
WordHunterWoW_QuestEN[31903] = { title = "Battle Pet Tamers: Eastern Kingdoms", description = "Now that you've had a real chance to hone your skills, you're ready to venture out into the world of pet battles in full.\n\nThere are five tamers throughout the Eastern Kingdoms that I'd like you to defeat: David Kosse in The Hinterlands, Deiza Plaguehorn in Eastern Plaguelands, Kortas Darkhammer in Searing Gorge, Everessa in Swamp of Sorrows, and Kortas' brother, Durin Darkhammer, in Burning Steppes..\n\nIf you are able to best them, you will be ready to venture further.", objectives = "Defeat David Kosse, Deiza Plaguehorn, Kortas Darkhammer, Everessa, and Durin Darkhammer in pet battles." }
WordHunterWoW_QuestEN[31904] = { title = "Cassandra Kaboom", description = "I've loaded my pets with new gyrotechnic training modules. You're going down!", objectives = "Defeat Cassandra Kaboom in a pet battle.", completion = "I must've converted a line wrong somewhere..." }
WordHunterWoW_QuestEN[31905] = { title = "Grazzle the Great", description = "You're back?! You're just asking to get eaten by a black dragon!", objectives = "Defeat Grazzle the Great in a pet battle.", progress = "I've seen better.", completion = "It's like my pretties have lost their will to fight." }
WordHunterWoW_QuestEN[31906] = { title = "Kela Grimtotem", description = "You're so bold as to venture into the heart of Grimtotem lands once more to challenge me? You will regret your decision!", objectives = "Defeat Kela Grimtotem in a pet battle.", progress = "You are a fool. A lucky fool, but still a fool.", completion = "Mark my words, I will defeat you one day soon." }
WordHunterWoW_QuestEN[31907] = { title = "Zoltan", description = "With each passing day my power grows. Resistance is futile.", objectives = "Defeat Zoltan in a pet battle.", progress = "All hail Zoltan!", completion = "This world is doomed. Why do you continue to try so fervently?" }
WordHunterWoW_QuestEN[31908] = { title = "Elena Flutterfly", description = "I see you're ready for another bout in the skies. Let's take flight!", objectives = "Defeat Elena Flutterfly in a pet battle.", progress = "I admire your abilities in combat.", completion = "My flight has come to an end. Victory is yours this day." }
WordHunterWoW_QuestEN[31909] = { title = "Grand Master Trixxy", description = "Freeze! You've finally warmed up from our last encounter, have you? Let's change that.", objectives = "Defeat Stone Cold Trixxy in a pet battle.", progress = "You show no mercy. I like you.", completion = "You're hot stuff!" }
WordHunterWoW_QuestEN[31910] = { title = "David Kosse", description = "My research has helped my training regimen greatly. I will defeat you this time.", objectives = "Defeat David Kosse in a pet battle.", progress = "I see you've worked on your routine as well.", completion = "Perhaps my research is not as complete as I thought." }
WordHunterWoW_QuestEN[31911] = { title = "Deiza Plaguehorn", description = "You have not yet turned to the true path of undeath. Perhaps another battle will show you the way.", objectives = "Defeat Deiza Plaguehorn in a pet battle.", completion = "Perhaps undeath is not the answer..." }
WordHunterWoW_QuestEN[31912] = { title = "Kortas Darkhammer", description = "I hear that you fought my fool of a brother. He lost, eh?\n\nLooks like this is my time to shine!", objectives = "Defeat Kortas Darkhammer in a pet battle.", progress = "How do you have such a strong team?", completion = "You're no better than Durin. In it for the glory. Pah!" }
WordHunterWoW_QuestEN[31913] = { title = "Everessa", description = "I believe I'm figuring out the secrets of this place. Soon I will be unstoppable!", objectives = "Defeat Everessa in a pet battle.", completion = "I see you have secrets of your own." }
WordHunterWoW_QuestEN[31914] = { title = "Durin Darkhammer", description = "My time under the Firelord has prepared me fer anything. Nothing you can throw at me will deter me!", objectives = "Defeat Durin Darkhammer in a pet battle.", progress = "What realm spawned a fighter of your caliber?", completion = "I'll defeat ye if it's the last thing I ever do. I haven't come this far fer nothin'!" }
WordHunterWoW_QuestEN[31915] = { title = "Grand Master Lydia Accoste", description = "The master tamers around the Eastern Kingdoms have been talking about you. You think yourself unstoppable? You believe that you are the true grand master?\n\nCome, then, {name}. I await you in Deadwind Pass. Come, and know the crushing defeat that's always been yours.", objectives = "Defeat Lydia Accoste in a pet battle.", progress = "Your power is not like the others'...", completion = "I have an eternity to train. I will defeat you!" }
WordHunterWoW_QuestEN[31916] = { title = "Grand Master Lydia Accoste", description = "You wish to face me again? You will regret this decision!", objectives = "Defeat Lydia Accoste in a pet battle.", progress = "You are powerful beyond my own belief.", completion = "You continue to reveal your strategies to me. Eventually, your defeat will be certain." }
WordHunterWoW_QuestEN[31917] = { title = "A Tamer's Homecoming", description = "Yer ready to enter the full circuit of pet battlin', matey. Go back to yer trainer, Mish Burnhep, in Stormwind, and prepare for the adventure of a lifetime!", objectives = "Report to Audrey Burnhep in Stormwind.", completion = "I'm so proud of you, <name>. You're ready for the big time!" }
WordHunterWoW_QuestEN[31918] = { title = "A Tamer's Homecoming", description = "If you beat me, then you must be ready for da big time! Go talk to Varzok in Orgrimmar.", objectives = "Report to Varzok in Orgrimmar.", completion = "Well done, <name>. You are finally prepared to truly come into your own as a tamer." }
WordHunterWoW_QuestEN[31919] = { title = "Battle Pet Tamers: Outland", description = "You've bested the master tamers of Kalimdor and the Eastern Kingdoms, but your next challenge will be far more trying.\n\nThere are four tamers in Outland that you must now defeat: Nicki Tinytech in Hellfire Peninsula, Ras'an in Zangarmarsh, Narrok in Nagrand, and Morulu the Elder in Shattrath.\n\nYou must defeat them to proceed on the path to greatness.", objectives = "Defeat Nicki Tinytech, Ras'an, Narrok, and Morulu the Elder in pet battles." }
WordHunterWoW_QuestEN[31920] = { title = "Grand Master Antari", description = "I've seen the likes of you before. A young, naive tamer that thinks that they deserve victory handed to them on a silver platter.\n\nWell no more! I will be your reckoning, {class}. I, Bloodknight Antari of Shadowmoon Valley, await the chance to show you how it feels to be obliterated in battle.", objectives = "Defeat Bloodknight Antari in a pet battle.", progress = "I don't believe it...", completion = "Impossible! I cannot lose!" }
WordHunterWoW_QuestEN[31921] = { title = "Battle Pet Tamers: Outland", description = "You've bested the master tamers of Kalimdor and the Eastern Kingdoms, but your next challenge will be far more trying.\n\nThere are four tamers in Outland that you must now defeat: Nicki Tinytech in Hellfire Peninsula, Ras'an in Zangarmarsh, Narrok in Nagrand, and Morulu the Elder in Shattrath.\n\nYou must defeat them to proceed on the path to greatness.", objectives = "Defeat Nicki Tinytech, Ras'an, Narrok, and Morulu the Elder in pet battles." }
WordHunterWoW_QuestEN[31922] = { title = "Nicki Tinytech", description = "According to my calculations, I have a 32.333% chance of victory. I'll take it!", objectives = "Defeat Nicki Tinytech in a pet battle.", progress = "I may have made a mistake somewhere...", completion = "I forgot to carry the 1!" }
WordHunterWoW_QuestEN[31923] = { title = "Ras'an", description = "You want to fight again? I think I've gotten better!", objectives = "Defeat Ras'an in a pet battle.", progress = "If I win, will you take me to visit Stormwind?", completion = "Nice work!" }
WordHunterWoW_QuestEN[31924] = { title = "Narrok", description = "I wish to do battle once more. These young ones need to grow stronger.", objectives = "Defeat Narrok in a pet battle.", progress = "You are a worthy adversary.", completion = "It would seem that these younglings still have a lot of work to do before they are at full strength. Thank you." }
WordHunterWoW_QuestEN[31925] = { title = "Morulu The Elder", description = "I have learned much since our last encounter. Do you wish to test your skills once more?", objectives = "Defeat Morulu The Elder in a pet battle.", progress = "You are truly wise beyond your years.", completion = "Even I continue to learn from each passing day." }
WordHunterWoW_QuestEN[31926] = { title = "Grand Master Antari", description = "You capitalized on my mistake last time and emerged victorious. This time, you will not be so fortunate, {race}.", objectives = "Defeat Bloodknight Antari in a pet battle.", progress = "Your performance is astonishing.", completion = "You are a fool for thinking yourself better than me. I will crush you, I swear it!" }
WordHunterWoW_QuestEN[31927] = { title = "Battle Pet Tamers: Northrend", description = "Outland's finest have fallen to your skill, but Northrend now awaits you!\n\nThere are four tamers that you must now defeat: Beegle Blastfuse in Howling Fjord, Nearly Headless Jacob in Crystalsong Forest, Okrut Dragonwaste in Dragonblight, and Gutretch in Zul'Drak.\n\nIf you are able to best all of them, then Northrend's Grand Master will surely challenge you!", objectives = "Defeat Beegle Blastfuse, Nearly Headless Jacob, Okrut Dragonwaste, and Gutretch in pet battles." }
WordHunterWoW_QuestEN[31928] = { title = "Grand Master Payne", description = "In my opinion, my fellow tamers have been far too lenient on your training.\n\nTrue pet taming requires militaristic discipline. I shall honor you with the pleasure of seeing firsthand what that discipline can produce.\n\nCome to the Argent Tournament Grounds in Icecrown and see firsthand what you could become!", objectives = "Defeat Major Payne in a pet battle.", progress = "Perhaps other methods may be useful in certain cases.", completion = "I was wrong about you, <name>. You've earned my respect as one of the finest adversaries I've ever faced. Don't go and think that I'll let you defeat me again next time, though!" }
WordHunterWoW_QuestEN[31929] = { title = "Battle Pet Tamers: Northrend", description = "Outland's finest have fallen to your skill, but Northrend now awaits you!\n\nThere are four tamers that you must now defeat: Beegle Blastfuse in Howling Fjord, Nearly Headless Jacob in Crystalsong Forest, Okrut Dragonwaste in Dragonblight, and Gutretch in Zul'Drak.\n\nIf you are able to best all of them, then Northrend's Grand Master will surely challenge you!", objectives = "Defeat Beegle Blastfuse, Nearly Headless Jacob, Okrut Dragonwaste, and Gutretch in pet battles." }
WordHunterWoW_QuestEN[31930] = { title = "Battle Pet Tamers: Pandaria", description = "You must now face the toughest tamers in all of Azeroth, {name}. They make their home in Pandaria, training ground of the grand masters.\n\nThere are six grand masters left to defeat: Hyuna of the Shrines in The Jade Forest, Farmer Nishi in Valley of the Four Winds, Mo'ruk in Krasarang Wilds, Courageous Yon in Kun-Lai Summit, Seeker Zusshi in Townlong Steppes, and Wastewalker Shu in Dread Wastes.\n\nIf you think yourself ready, seek out these champions of the trade and prove yourself!", objectives = "Defeat Hyuna of the Shrines, Farmer Nishi, Mo'ruk, Courageous Yon, Seeker Zusshi, and Wastewalker Shu in pet battles." }
WordHunterWoW_QuestEN[31931] = { title = "Beegle Blastfuse", description = "One of my chickens flew for just a moment yesterday, I swear. We're finally hitting the big time!\n\nOh, you'd like to battle again?", objectives = "Defeat Beegle Blastfuse in a pet battle.", progress = "We still don't have sustained flight, though.", completion = "One day, when we're flying high above you, you'll be the loser!" }
WordHunterWoW_QuestEN[31932] = { title = "Nearly Headless Jacob", description = "Time and time again you defy my wisdom. What is it that brings you back to these woods?\n\nAh, you wish to do battle once more. Very well then.", objectives = "Defeat Nearly Headless Jacob in a pet battle.", progress = "Your intentions are clear.", completion = "Your risk has paid its due reward. Now begone!" }
WordHunterWoW_QuestEN[31933] = { title = "Okrut Dragonwaste", description = "You dare interrupt our work? Then you must battle me again! Take out your pets, and I'll give you a taste of Hellscream's wrath!", objectives = "Defeat Okrut Dragonwaste in a pet battle.", progress = "You...fool.", completion = "I dare you to continue to fight the inevitable. Dragons will once again serve our purposes, and you will fall to my hand in a pet battle. I swear on the Warchief's mantle that it will be so!" }
WordHunterWoW_QuestEN[31934] = { title = "Gutretch", description = "Me like fighting you. You not so easy like the others. We fight again?", objectives = "Defeat Gutretch in a pet battle.", progress = "<Gutretch stares at you blankly.>", completion = "Me like fighting you, even if me lose." }
WordHunterWoW_QuestEN[31935] = { title = "Grand Master Payne", description = "The rebel {class} comes once again to test his might again that of a Grand Master. Your bravery will be your undoing this time!", objectives = "Defeat Major Payne in a pet battle.", progress = "You are a true fighter at heart. I respect that.", completion = "I applaud your tactics, but despise your victory. Well done, <name>." }
WordHunterWoW_QuestEN[31936] = { title = "The \"Jinyu Princess\" Irrigation System", description = "<The back of the box features a caricature of a jinyu maiden surrounded by marketing copy.>\n\n\"Hey there, greenthumb. Are you pouting over parched pumpkins? Crying over crusty cabbage? Are your leeks lame and your melons melancholy?\n\nThen it's time you brought home the Jinyu Princess! She'll wash over your garden like a sweet spring rain, dousing that drought with a deep draught of...\"\n\n<It goes on like this for six paragraphs.>", objectives = "Bring the \"Jinyu Princess\" Irrigation System to Farmer Yoon at Sunsong Ranch or Halfhill market.\n\nProvided item:", completion = "A sprinkler system? For the farm? Thank you, <name>! We can use this instead of that old watering can.\n\nThe \"Jinyu Princess\" eh? What's up with that?\n\n\n\nAlright, I don't even want to know. I'll get this installed right away!" }
WordHunterWoW_QuestEN[31937] = { title = "\"Thunder King\" Pest Repellers", description = "<An imposing image of a mogu face dominates this box, casting its gaze downward at neatly ordered rows of bold text.>\n\n\"DO NOT LET WEAK, DISGUSTING INSECTS INFEST YOUR GLORIOUS CROPS. CONQUER THEM WITH THE MIGHT OF THE THUNDER KING AND PROTECT YOUR LEGACY.\"\n\n<The rest of the space is dedicated to cartoon depictions of various insects crying out in lament or fleeing in terror.>", objectives = "Bring the \"Thunder King\" Pest Repellers to Farmer Yoon at Sunsong Ranch or Halfhill Market.\n\nProvided item:", completion = "Pest repellers! You're a genius, <name>! We can finally stop using that ancient bug sprayer.\n\n\n\nAw yeah, Thunder King! That's what I'm talking about!\n\nI'll get this installed right away - those bugs won't know what hit 'em!" }
WordHunterWoW_QuestEN[31938] = { title = "The \"Earth-Slasher\" Master Plow", description = "<The box art depicts a pandaren farmer of impossible physique standing proudly astride a widening rift in the earth, a mighty plow in his grasp. Cubs wrestle playfully on his shoulders and dangle from his muscular arms.\n\nAt his side, a stoic female - of equally impossible physique - balances a massive, overflowing cornucopia gracefully on her head while kicking a virmen in the face.>\n\n\"The Earth-Slasher. Master the land. Master your life.\"", objectives = "Bring the \"Earth-Slasher\" Master Plow to Farmer Yoon at Sunsong Ranch or Halfhill Market.\n\nProvided item:", completion = "An Earth-Slasher master plow! I... I never thought I'd get to use one of these. Do you have any idea how much time this will save us?!\n\nI heard if you push the Earth-Slasher through twenty yards of solid rock, you end up with a sandbox and a citation from the Shado-Pan for causing an earthquake scare!\n\nThis is going to be AWESOME." }
WordHunterWoW_QuestEN[31939] = { title = "Test", description = "All right friend, all of that farming was just for practice!\n\nAre you ready to try the real thing?\n\nMei Mei Ironpaw over at the market is in need of some carrots for her stew. And you know who can grow those carrots? Us!\n\nHow about you show me what you've learned by planting, growing, and harvesting four beds of Juicycrunch Carrots?You will learn:", objectives = "Plant and harvest 4 Juicycrunch Carrots. Juicycrunch Carrot Seeds can be purchased from Merchant Greenfield at Halfhill Market. After tilling and caring for your planting, you must wait until the next day to harvest grown Juicycrunch Carrots.All right friend, all of that farming was just for practice!\n\nAre you ready to try the real thing?\n\nMei Mei Ironpaw over at the market is in need of some carrots for her stew. And you know who can grow those carrots? Us!\n\nHow about you show me what you've learned by planting, growing, and harvesting four beds of Juicycrunch Carrots?You will learn:" }
WordHunterWoW_QuestEN[31940] = { title = "Battle Pet Trainers: Pandaria", description = "Outland's finest have fallen to your skill, but Northrend now awaits you!\n\nThere are four trainers that you must now defeat: Ziggy the Flightless in Howling Fjord, Nearly Headless Jacob in Crystalsong Forest, Okrut Dragonwaste in Dragonblight, and Gutretch in Zul'drak.\n\nIf you are able to best all of them, then Northrend's Grand Master will surely challenge you!You will receive:", objectives = "Defeat Ziggy the Flightless, Nearly Headless Jacob, Okrut Dragonwaste, and Gutretch in pet battles." }
WordHunterWoW_QuestEN[31941] = { title = "Squash Those Foul Odors", description = "Grandpa always said, \"A squash a week, and your tail won't reek.\"\n\n<Yoon subtly sniffs the air.>\n\nYup. I think it's been about a week. Could you help me plant a Jade Squash?", objectives = "Plant a Jade Squash in Sunsong Ranch. You can purchase seeds from Merchant Greenfield in the Halfhill Market.", completion = "Well planted, <name>.\n\nNow we play the waiting game..." }
WordHunterWoW_QuestEN[31942] = { title = "It's Melon Time", description = "<Farmer Yoon looks up at the sky and sniffs the air.>\n\nHmm...\n\n<He licks his paw and holds it up in the air, sticks a toenail into the soil, and then inspects the length of his shadow.>\n\nYup. It's melon time.\n\nCould you grab some seeds and help me plant a Striped Melon?", objectives = "Plant a Striped Melon in Sunsong Ranch. You can purchase seeds from Merchant Greenfield in the Halfhill Market.", progress = "Hurry up! Melon time doesn't last forever!", completion = "That was close. We almost missed melon time." }
WordHunterWoW_QuestEN[31943] = { title = "Which Berries? Witchberries.", description = "That young'un over there, Andi, is going to grow up to be a heck of a farmer some day. I can tell just by lookin' at him.\n\nI think I'll plant him some witchberries. Kids love witchberries - it'll be a nice surprise.", objectives = "Plant Witchberries in Sunsong Ranch. You can purchase seeds from Merchant Greenfield in the Halfhill Market.", completion = "Alright, witchberries! I can't wait!\n\nBut I'm gonna have to." }
WordHunterWoW_QuestEN[31944] = { title = "Complete Your Training: The Final Test", description = "Welcome back, {name}.  The time has come for you to complete the last step of your training.  Head to the Training Grounds for your final test.", objectives = "Go the the Training Grounds at the Peak of Serenity and complete your final test.", progress = "Complete your final test.", completion = "Well done, <name>.  Your training is now complete.  Feel free to return in the future to spar with the masters here to practice what you have learned." }
WordHunterWoW_QuestEN[31945] = { title = "Learn and Grow VI: Gina's Vote", description = "My business is doomed! You see all of the Ironpaws at their cooking stations?\n\nTheir tasty dishes draw many of the customers to this market, but they're all out of scallions!\n\nIt may not look like much, but the scallion is an essential cooking ingredient. Without it, foods are less savory, less flavorful, and less aromatic.\n\nThis is terrible. I'm not getting another scallion shipment for a week!\n\nWait a second. You're a farmer, aren't you? You think you could help me?", objectives = "Plant and harvest 1 Scallion, then deliver 5 Scallions to Gina Mudclaw.\n\nScallion Seeds can be purchased from Merchant Greenfield at Halfhill Market. After tilling and tending your plant, you must wait until the next day to harvest ripe Scallions.", progress = "Don't overlook the scallion. It may be small and innocuous, but it creates truly marvelous flavors.", completion = "Well, I'll be! I've certainly seen larger scallions, but this will do quite nicely. You've just saved our hides, <name>!" }
WordHunterWoW_QuestEN[31946] = { title = "Mung-Mung's Vote III: The Great Carrot Caper", description = "Mung-Mung don't care who steals carrots. Only care what Mr. Mudclaw does to poor Mung-Mung when he finds his crop is ruined!\n\n<Mung-Mung rubs his chin thoughtfully.>\n\nWait! Mung-Mung have bright idea. You go and grow some juicycrunch carrots. Then, we take your carrots and pretend they are Mr. Mudclaw's.\n\nYes!", objectives = "Plant and harvest 2 Juicycrunch Carrots, then deliver 10 Juicycrunch Carrots to Mung-Mung.\n\nJuicycrunch Carrot Seeds can be purchased from Merchant Greenfield at Halfhill Market. After tilling and tending your plant, you must wait until the next day to harvest ripe Juicycrunch Carrots.", progress = "Virmens love carrots, but they hate turnips. I hate turnips, too.", completion = "Whoa, these carrots look crunchy and juicy, <name>! Mung-Mung did not know you had such a green thumb." }
WordHunterWoW_QuestEN[31947] = { title = "Farmer Fung's Vote III: Crazy For Cabbage", description = "<Farmer Fung is beaming with a radiant smile.>\n\nThanks to you, I got my precious yaks back! Unfortunately, I noticed that their time out in the wild left them rather gaunt.\n\nThey must be starving, but I don't feed my prize yaks just any regular old grass.\n\nNo sir, they eat only the leafiest green cabbages you can find here in the Valley.\n\nMy stores are a bit low. If you bring me some cabbages for my yaks, I will reward you handsomely.", objectives = "Plant and harvest 3 Green Cabbages, then deliver 15 Green Cabbages to Farmer Fung.\n\nGreen Cabbage Seeds can be purchased from Merchant Greenfield at Halfhill Market. After tilling and tending your plant, you must wait until the next day to harvest ripe Green Cabbages.", progress = "I have pet nicknames for all of my yaks. There's Hairy, and Shaggy, and Fluffy, and Woolly, and...", completion = "I was expecting cabbages, but not cabbages of this quality! Oh my!\n\nA perfectly round head, large waxy leaves, a perfect gradient of emerald color...\n\n<Farmer Fung takes a bite out of the cabbage.>\n\nMmm, and sweet, crisp flavor! These is a beautiful cabbage, <name>. My yaks will certainly be spoiled by this tasty treat." }
WordHunterWoW_QuestEN[31948] = { title = "Nana's Vote II: The Sacred Springs", description = "You caught me at a good time, {name}. I was just hankering to make a fresh batch of Witchberry Julep.\n\nHave you ever heard of this wondrous brew?\n\nEach sip takes ten years off your face! How do you think I still look so good?\n\nAnyway, I need a special ingredient - thousand-year water - which can be collected from the mouth of the waterfall to the north.\n\nI'm afraid the journey is too treacherous for an old matron like me, but if you can get your hands on a pitcher, I'll let you share my brew.", objectives = "Use the Empty Pitcher at the Golden Falls to collect Thousand-Year Water.", progress = "The water in this valley flows from the Vale of Eternal Blossoms to the north. It is said that these waters have wondrous, magical properties.", completion = "Found the falls, did you? Oh yes, I see you found the water. Wonderful!" }
WordHunterWoW_QuestEN[31949] = { title = "Nana's Vote III: Witchberry Julep", description = "Now that we have the water, I can almost taste the icy cold witchberry julep!\n\nNow, we just need to find ourselves some sweet witchberries.\n\nMy grandson's berries this season have been total slop, so I need to seek a decent harvest elsewhere.\n\nSay, do you have any witchberries in the ground this year? How about you bring me some from your farm?\n\nIf your berries are up to the standard, we'll make ourselves a grand old batch of the old juice!", objectives = "Plant and harvest 3 Witchberries, then deliver 15 Witchberries to Nana Mudclaw.\n\nWitchberry Seeds can be purchased from Merchant Greenfield at Halfhill Market. After tilling and tending your plant, you must wait until the next day to harvest ripe Witchberries.", progress = "Hurry it up, will ya? I'm an old woman. I don't have all the time in the world, and I want one more taste of the sauce before I croak!", completion = "<Nana Mudclaw scrutinizes a dark witchberry, then pops it into her mouth. Her face lights up.>\n\nLands alive! I haven't tasted such a sweet, juicy witchberry in years! Why, the only person who could grow berries like these was... Old Yoon, yer friend's grandpa.\n\n<Nana Mudclaw blushes.>\n\nOh that man was such a scamp! I still remember the summer days when we were young, eating these berries by the bushel without a care in the world.\n\nThank you for reminding me of an old friend, <name>." }
WordHunterWoW_QuestEN[31950] = { title = "Tracking Quest: Move NPCs to Dais", description = "", objectives = "" }
WordHunterWoW_QuestEN[31951] = { title = "Grand Master Aki", description = "You have fought hard and well against the trainers of Azeroth. Even the grand masters have fallen to your cunning tactics.\n\nI now await you in the Vale of Eternal Blossoms, for you have earned the privilege to face me in battle. Come, {name}, and let us see if you have what it takes to defeat me.", objectives = "Defeat Aki the Chosen in a pet battle.", progress = "I have heard much about your techniques. Hopefully that does not alter the outcome of our bout.", completion = "You have emerged victorious. Continue your training and find challenges in other trainers like yourself. The journey is never truly complete." }
WordHunterWoW_QuestEN[31952] = { title = "Battle Pet Tamers: Pandaria", description = "You must now face the toughest tamers in all of Azeroth, {name}. They make their home in Pandaria, training ground of the grand masters.\n\nThere are six grand masters left to defeat: Hyuna of the Shrines in The Jade Forest, Farmer Nishi in Valley of the Four Winds, Mo'ruk in Krasarang Wilds, Courageous Yon in Kun-Lai Summit, Seeker Zusshi in Townlong Steppes, and Wastewalker Shu in Dread Wastes.\n\nIf you think yourself ready, seek out these champions of the trade and prove yourself!", objectives = "Defeat Hyuna of the Shrines, Farmer Nishi, Mo'ruk, Courageous Yon, Seeker Zusshi, and Wastewalker Shu in pet battles." }
WordHunterWoW_QuestEN[31953] = { title = "Grand Master Hyuna", description = "You seek to do battle once more? Very well, it will strengthen me to better protect the sacred sites of my people.", objectives = "Defeat Hyuna of the Shrines in a pet battle.", progress = "You are a noble fighter.", completion = "You are very strong. Will you lend your skills to my efforts?" }
WordHunterWoW_QuestEN[31954] = { title = "Grand Master Mo'ruk", description = "This time I'm gonna do the beating! You watch!", objectives = "Defeat Mo'ruk in a pet battle.", progress = "No! Me win!", completion = "Next time you lose. I'm gonna beatcha!" }
WordHunterWoW_QuestEN[31955] = { title = "Grand Master Nishi", description = "My pets continue to grow in strength thanks to the fertile land we train on. You don't stand a chance!", objectives = "Defeat Farmer Nishi in a pet battle.", progress = "You're good, I'll give you that.", completion = "Wow! I'm not the only one that's been training!" }
WordHunterWoW_QuestEN[31956] = { title = "Grand Master Yon", description = "If you think I am going to let you walk away with another victory in hand, you are sorely mistaken. This time, I will stand over you as the superior trainer!", objectives = "Defeat Courageous Yon in a pet battle.", progress = "You fight well, for a <race>.", completion = "Fine. Victory is yours once more. Begone, I have much preparation to do before we meet again." }
WordHunterWoW_QuestEN[31957] = { title = "Grand Master Shu", description = "You venture into the heart of the wastes to face me again, only to suffer defeat at the hands of a true grand master. Noble, but foolish.", objectives = "Defeat Wastewalker Shu in a pet battle.", progress = "Perhaps your bravery is not as foolish as I had thought.", completion = "In all my time as a grand master I've never faced one as determined as you. The others were right about you. You are a force to be reckoned with." }
WordHunterWoW_QuestEN[31958] = { title = "Grand Master Aki", description = "You wish to test yourself against me once more? Very well, let us fight.", objectives = "Defeat Aki the Chosen in a pet battle.", progress = "The journey to greatness is never complete.", completion = "You are stronger and your skills more refined. Your journey continues." }
WordHunterWoW_QuestEN[31959] = { title = "The Empress' Gambit", description = "Grand Empress Shek'zeer has finally lost her patience with us. We have learned of an enormous army, massing in the shadows of the Heart of Fear, with orders to crush Klaxxi'vess.\n\nWe have been fortunate to hold out this long, but we cannot survive a siege of this scale.\n\nWakener, you have been invaluable to our efforts. Come, take your place on the field among we paragons.\n\nI will see you on the battlefield!", objectives = "Report to Malik the Unscathed outside the Heart of Fear." }
WordHunterWoW_QuestEN[31960] = { title = "Tracking Event: Vote #1 Complete", description = "", objectives = "" }
WordHunterWoW_QuestEN[31961] = { title = "Tracking Event: Vote #2 Complete", description = "", objectives = "" }
WordHunterWoW_QuestEN[31962] = { title = "Tracking Event: Vote #3 Complete", description = "", objectives = "" }
WordHunterWoW_QuestEN[31963] = { title = "Tracking Event: Vote #4 Complete", description = "", objectives = "" }
WordHunterWoW_QuestEN[31964] = { title = "Tracking Event: Vote #5 Complete", description = "", objectives = "" }
WordHunterWoW_QuestEN[31965] = { title = "Tracking Event: Vote #6 Complete", description = "", objectives = "" }
WordHunterWoW_QuestEN[31966] = { title = "Battle Pet Tamers: Cataclysm", description = "You have defeated Northrend's finest tamers, but you need more preparation before you are ready to face the grand masters of Pandaria. Ready yourself and hone your skills by defeating these elite tamers: Brok in Mount Hyjal, Bordin Steadyfist in Deepholm, and Goz Banefury in Twilight Highlands.\n\nOnce you have triumphed over them, you will be ready to journey to Pandaria to face the ultimate challenge.", objectives = "Defeat Brok, Bordin Steadyfist, and Goz Banefury in pet battles." }
WordHunterWoW_QuestEN[31967] = { title = "Battle Pet Tamers: Cataclysm", description = "Northrend has fallen to your hand, but you are not yet ready to face the grand masters of Pandaria. Defeat these tamers to harden your will for the coming challenges: Brok in Mount Hyjal, Bordin Steadyfist in Deepholm, and Goz Banefury in Twilight Highlands.\n\nOnly by defeating them will you be ready to journey to Pandaria.", objectives = "Defeat Brok, Bordin Steadyfist, and Goz Banefury in pet battles." }
WordHunterWoW_QuestEN[31968] = { title = "Doubt Begins To Surface", description = "The Alliance... so many airships. How can we possibly fight them all? I... don't feel... well...You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Snap Nazgrim out of it.The Alliance... so many airships. How can we possibly fight them all? I... don't feel... well...You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[31969] = { title = "Priorities Tracking", description = "", objectives = "" }
WordHunterWoW_QuestEN[31970] = { title = "Grand Master Obalis", description = "You think yourself ready to challenge Pandaria? You truly believe that you can defeat the most powerful tamers in all of Azeroth?\n\nI shall be the judge of that notion, {race}. Face me atop the Vir'naal Dam in Uldum, and we shall see if you are truly ready.", objectives = "Defeat Obalis in a pet battle.", progress = "I admire your passion, young one.", completion = "I have been proven wrong. You are prepared to face my greaters." }
WordHunterWoW_QuestEN[31971] = { title = "Grand Master Obalis", description = "I see the triumphant tamer returns to again test himself against me. Very well. I accept your challenge.", objectives = "Defeat Obalis in a pet battle.", progress = "Defeat is but a path to success.", completion = "By defeating me, I grow stronger. I urge you to be wary during our next encounter." }
WordHunterWoW_QuestEN[31972] = { title = "Brok", description = "I do not yet understand the plight of these creatures well enough to help them sufficiently. Perhaps another battle would strengthen our bond?", objectives = "Defeat Brok in a pet battle.", progress = "Battle me for the good of all of Mount Hyjal.", completion = "Even in defeat I feel closer to my pets. Thank you for a worthy skirmish." }
WordHunterWoW_QuestEN[31973] = { title = "Bordin Steadyfist", description = "The natives have taught me the strength of the earth. I know it's unending endurance. Let us battle once more, and you'll see that I'm tougher than ever!", objectives = "Defeat Bordin Steadyfist in a pet battle.", progress = "You think you can handle me?", completion = "No, no, I just messed up. How about another go?" }
WordHunterWoW_QuestEN[31974] = { title = "Goz Banefury", description = "The power of twilight flows through me. I am a god! You have no hope of defeating me!", objectives = "Defeat Goz Banefury in a pet battle.", progress = "Pathetic <race>. Doomed to die powerless to the true rulers of this world.", completion = "You fight with the wrath of my masters. Perhaps you and I aren't so different." }
WordHunterWoW_QuestEN[31975] = { title = "The Returning Champion", description = "You belong in Outland with the other hotshots if ya ask me. Why don't ya go back to Audrey Burnhep in Stormwind and see what's next in your new career as a tamer!", objectives = "Report to Audrey Burnhep in Stormwind.", completion = "Let's see...where to send you next..." }
WordHunterWoW_QuestEN[31976] = { title = "The Returning Champion", description = "Word of your skill is spreading. I suggest you return to your trainer, Audrey Burnhep, for further guidance.", objectives = "Report to Audrey Burnhep in Stormwind.", completion = "Let's see...where to send you next..." }
WordHunterWoW_QuestEN[31977] = { title = "The Returning Champion", description = "You belong in Outland with the other hotshots if ya ask me. Why don't ya go back to Varzok in Orgrimmar and see what's next in your new career as a tamer!", objectives = "Report to Varzok in Orgrimmar.", completion = "I've been at work preparing your next set of challenges, <name>. Let us see if you are prepared..." }
WordHunterWoW_QuestEN[31978] = { title = "Priorities!", description = "Just look at this mess! All that brew gone to waste!\n\nTaran Zhu warned us against speaking to you outsiders, but I'll take any help I can get.\n\nWe were on our way to Dawn's Blossom to deliver our brew when the fighting broke out. Now all of our brew has been lost!\n\nYou want to make it up to us? Maybe you can find some of our Honeybrew barrels that haven't been broken. Then it wouldn't be a complete loss.", objectives = "Find 6 Barrels of Honeybrew in Honeydew Glade.", completion = "Well, it's not as much as I would have hoped, but it will have to do. I guess there is no sense in cryin' over spilled brew." }
WordHunterWoW_QuestEN[31979] = { title = "The Returning Champion", description = "You belong in Outland with the other hotshots if ya ask me. Why don't ya go back to Audrey Burnhep in Stormwind and see what's next in your new career as a tamer!You will receive:", objectives = "Report to Audrey Burnhep in Stormwind.You belong in Outland with the other hotshots if ya ask me. Why don't ya go back to Audrey Burnhep in Stormwind and see what's next in your new career as a tamer!You will receive:" }
WordHunterWoW_QuestEN[31980] = { title = "The Returning Champion", description = "Word of your skill is spreading. I suggest you return to your trainer, Varzok, for further guidance.", objectives = "Report to Varzok in Orgrimmar.", completion = "I think I know just the right place to test you next." }
WordHunterWoW_QuestEN[31981] = { title = "Exceeding Expectations", description = "Run off to your trainer, Audrey Burnhep, in Stormwind. Perhaps she can find you more...worthwhile...challenges.", objectives = "Report to Audrey Burnhep in Stormwind.", completion = "You really beat Grand Master Antari? Wow! I'm going to have to find you some really tough tamers to fight!" }
WordHunterWoW_QuestEN[31982] = { title = "Exceeding Expectations", description = "Run off to your trainer, Varzok, in Orgrimmar. Perhaps he can find you more... worthwhile... challenges.", objectives = "Report to Varzok in Orgrimmar.", completion = "There is only one place to test you next." }
WordHunterWoW_QuestEN[31983] = { title = "A Brief Reprieve", description = "Well done, for an {race}. Now, get back to Orgrimmar and talk to that brute Varzok. Maybe he can point you somewhere very far away from my family.", objectives = "Report to Varzok in Orgrimmar.", completion = "I think I know the next step you ought to take." }
WordHunterWoW_QuestEN[31984] = { title = "A Brief Reprieve", description = "Well done, well done indeed! If you would, please report to Miss Audrey Burnhep in Stormwind.\n\nOh, and send her my regards. She's a beautiful young woman that could benefit from the company of an accomplished fighter such as myself.", objectives = "Report to Audrey Burnhep in Stormwind.", completion = "Payne asked you to court me for him, didn't he? When is he ever going to learn?" }
WordHunterWoW_QuestEN[31985] = { title = "The Triumphant Return", description = "You are now prepared as your trainer instructed. Travel back to Stormwind and have words with Audrey Burnhep. She will guide you further.", objectives = "Report to Audrey Burnhep in Stormwind.", completion = "I take it you met Obalis? He's a wonderful fellow, once you get past his rough exterior." }
WordHunterWoW_QuestEN[31986] = { title = "The Triumphant Return", description = "You are now prepared as your trainer instructed. Travel back to Orgrimmar and have words with Varzok. He will guide you further.", objectives = "Report to Varzok in Orgrimmar.", completion = "You are now prepared for a true test of your skill in battle. Are you up to it?" }
WordHunterWoW_QuestEN[31987] = { title = "LFGDungeons - Theramore Launch Event", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[31988] = { title = "Daily Selected Scenario", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[31989] = { title = "The Peak of Serenity - Complete Your Training", description = "The time has come for you to return to the Peak of Serenity to complete your training.  Use Zen Pilgrimage to return there and speak with Master Hight when you arrive.", objectives = "Use Zen Pilgrimage to travel to the Peak of Serenity. Speak to Master Hight in the Shrine of the Ox when you arrive.", completion = "Welcome back, <name>.  It is time for the final step of your training." }
WordHunterWoW_QuestEN[31990] = { title = "Audrey Burnhep", description = "I'm afraid I have nothing left to teach you, <name>. However, your journey as a trainer is far from over!\n<race>eport to Audrey Burnhep in Stormwind. She has connections with many of Azeroth's finest trainers, and will help you grow further.You will receive:", objectives = "Report to Audrey Burnhep in Stormwind.I'm afraid I have nothing left to teach you, <name>. However, your journey as a trainer is far from over!\n<race>eport to Audrey Burnhep in Stormwind. She has connections with many of Azeroth's finest trainers, and will help you grow further.You will receive:" }
WordHunterWoW_QuestEN[31991] = { title = "Grand Master Zusshi", description = "I knew you would return to face me once more. Let us see who is truly wiser in the ways of battle.", objectives = "Defeat Seeker Zusshi in a pet battle.", progress = "Despite my wisdom, you manage to surprise me.", completion = "You are indeed superior. If you would pardon me, I must consult the lake for guidance in my defeat." }
WordHunterWoW_QuestEN[31998] = { title = "A Worthy Challenge: Sha of Doubt", description = "{name}, I need you to assemble a hearty group and lead them into the Temple of the Jade Serpent. Activate the Challenger's Orb therein, and vanquish the Sha of Doubt.\n\nReturn to me when you've completed this challenge, and I shall reward you handsomely.", objectives = "Complete the Temple of the Jade Serpent Challenge Mode.", completion = "You have my gratitude, <name>. You've displayed great valor today, and the speed at which you completed the challenge surely will impress your friends and intimidate your foes." }
WordHunterWoW_QuestEN[31999] = { title = "Nazgrim's Command", description = "You have a comfortable base of operations, no Alliance around for miles, and a few Horde veterans by your side. It looks like it's time to start painting this continent red.\n\nGeneral Nazgrim should know where to start.", objectives = "Report to General Nazgrim at Strongarm Airstrip in the Jade Forest.", completion = "We may have won the battle against the Alliance, but we won't get any further with this many jabbering monkeys on our perimeter.\n\nThe hozen are our next target." }
WordHunterWoW_QuestEN[32000] = { title = "A Worthy Challenge: Yan-zhu the Uncasked", description = "{name}, I need you to assemble a hearty group and lead them into Stormstout Brewery. Activate the Challenger's Orb therein, and evaporate Yan-zhu the Uncasked.\n\nReturn to me when you've completed this challenge, and I shall reward you handsomely.", objectives = "Complete the Stormstout Brewery Challenge Mode.", completion = "You have my sincerest thanks, <name>. Without fine Stormstout brews to lighten the drudgery of the day, the world would be a dull place indeed." }
WordHunterWoW_QuestEN[32001] = { title = "A Worthy Challenge: Sha of Hatred", description = "{name}, I need you to assemble a tranquil group and lead them into the Shado-Pan Monastery. Activate the Challenger's Orb therein, and rescue Taran Zhu from the Sha of Hatred.\n\nReturn to me when you've completed this challenge, and I shall reward you handsomely.", objectives = "Complete the Shado-Pan Monastery Challenge Mode.", completion = "Many blessings upon you, <name>. Driving hatred from this world so quickly deserves rich reward." }
WordHunterWoW_QuestEN[32002] = { title = "A Worthy Challenge: Xin the Weaponmaster", description = "{name}, I need you to assemble a nimble group and lead them into Mogu'shan Palace. Activate the Challenger's Orb therein, and put an end to Xin the Weaponmaster.\n\nReturn to me when you've completed this challenge, and I shall reward you handsomely.", objectives = "Complete the Mogu'shan Palace Challenge Mode.", completion = "Many thanks, <name>. Your martial prowess is second to none, and your alacrity is sure to strike fear in the hearts of your enemies." }
WordHunterWoW_QuestEN[32003] = { title = "A Worthy Challenge: Raigonn", description = "{name}, I need you to assemble a cracking group and lead them into the Gate of the Setting Sun. Activate the Challenger's Orb therein and lay waste to Raigonn.\n\nReturn to me when you've completed this challenge, and I shall reward you handsomely.", objectives = "Complete the Gate of the Setting Sun Challenge Mode.", completion = "That was a blow well struck, <name>. I've never seen a <class> fell a giant with such speed." }
WordHunterWoW_QuestEN[32004] = { title = "A Worthy Challenge: Wing Leader Ner'onok", description = "{name}, I need you to assemble an eagle-eyed group and lead them into the Siege of Niuzao Temple. Activate the Challenger's Orb and ground Wing Leader Ner'onok.\n\nReturn to me when you've completed this challenge, and I shall reward you handsomely.", objectives = "Complete the Siege of Niuzao Temple Challenge Mode.", completion = "<name>, that was amazing. Ner'onok is a master tactician, and you schooled him handily." }
WordHunterWoW_QuestEN[32005] = { title = "A Worthy Challenge: Durand", description = "{name}, I need you to assemble a stout group and lead them into Scarlet Monastery. Activate the Challenger's Orb therein, and smite Durand with righteous fury.\n\nReturn to me when you've completed this challenge, and I shall reward you handsomely.", objectives = "Complete the Scarlet Monastery Challenge Mode.", completion = "<name>, you're a stalwart <class>. Your friends and guild mates will surely notice the speed and ferocity with which you conquered the Scarlet Monastery." }
WordHunterWoW_QuestEN[32006] = { title = "A Worthy Challenge: Flameweaver Koegler", description = "{name}, I need you to assemble a cunning group and venture forth into the depths of Scarlet Halls. Activate the Challenger's Orb therein, and put a stop to Flameweaver Koegler's book-burning ways.", objectives = "Complete the Scarlet Halls Challenge Mode.", completion = "Excellent work, <name>. Just the thought of him burning up that beautiful library makes me shudder. Your friends will appreciate the speed with which you dispatched him." }
WordHunterWoW_QuestEN[32007] = { title = "A Worthy Challenge: Darkmaster Gandling", description = "{name}, I need you to assemble a fearless group and lead them into the depths of Scholomance. Activate the Challenger's Orb, and cleanse Scholomance of Darkmaster Gandling's evil presence.\n\nReturn to me when you've completed this challenge and I shall reward you handsomely.", objectives = "Complete the Scholomance Challenge Mode.", completion = "<name>, you've done a great service. May the skeletons of the dead remain peaceful now that Gandling no longer seeks to disturb their slumber." }
WordHunterWoW_QuestEN[32008] = { title = "Audrey Burnhep", description = "Greetings, {name}! My name is Audrey Burnhep. I've been hearing quite a lot about you recently. You're becoming quite the tamer!\n\nYou should come speak with me in Stormwind. I have connections with some of the finest tamers in all of Azeroth, and I can help you grow even more!", objectives = "Report to Audrey Burnhep in Stormwind.", completion = "Ah, you're <name>. Splendid! Let's get to work then, shall we?" }
WordHunterWoW_QuestEN[32009] = { title = "Varzok", description = "Lok'tar, {name}. My name is Varzok. I have heard much your accomplishments as a tamer recently, and I would like to introduce you to trainers around Azeroth so that you may further hone your skills.\n\nPlease speak with me in Orgrimmar so that we may begin.", objectives = "Report to Varzok in Orgrimmar.", completion = "You must be <name>. Well met. I am Varzok.\n\nI will serve as your contact from here on out." }
WordHunterWoW_QuestEN[32010] = { title = "A Celestial Task", description = "Are you familiar with the August Celestials? Yu'lon, Chi-Ji, Xuen, and Niuzao watch over the four corners of Pandaria.\n\nThey watch you as well.\n\nTheir knowledge is most ancient, and most powerful. To those they favor, they can bestow enormous power.\n\nYou may seek to earn their trust, but they need you for a more important task.\n\nThe Vale of Eternal Blossoms is in danger. First, we must all defend the Vale. Then, we can turn our eyes to the Celestials themselves.", objectives = "Earned Revered standing with the Golden Lotus.", completion = "The Vale is safer now, thanks to you. Now, you must help the Celestials." }
WordHunterWoW_QuestEN[32011] = { title = "A Celestial Task", description = "Are you familiar with the August Celestials? Yu'lon, Chi-Ji, Xuen, and Niuzao watch over the four corners of Pandaria.\n\nThey watch you as well.\n\nTheir knowledge is most ancient, and most powerful. To those they favor, they can bestow enormous power.\n\nYou may seek to earn their trust, but they need you for a more important task.\n\nThe Vale of Eternal Blossoms is in danger. First, we must all defend the Vale. Then, we can turn our eyes to the Celestials themselves.", objectives = "Earned Revered standing with the Golden Lotus.", completion = "The Vale is safer now, thanks to you. Now, you must help the Celestials." }
WordHunterWoW_QuestEN[32012] = { title = "Kovok tracking [GROWING]", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[32016] = { title = "Elder Charms of Good Fortune", description = "Greetings, {name}. I am privileged to offer you an excellent opportunity. Through the centuries, we've honed a method by which the very laws of chance themselves can be bent. With an Elder Charm of Good Fortune, valuable artifacts will find their way into your hands more frequently.", objectives = "Collect 90 Lesser Charms of Good Fortune.", progress = "May these charms bring you great luck, <name>.", completion = "May the stars smile upon you, <name>." }
WordHunterWoW_QuestEN[32017] = { title = "Elder Charms of Good Fortune", description = "Greetings, {name}. I am privileged to offer you an excellent opportunity. Through the centuries, we've honed a method by which the very laws of chance themselves can be bent. With an Elder Charm of Good Fortune, valuable artifacts will find their way into your hands more frequently.", objectives = "Collect 90 Lesser Charms of Good Fortune.", progress = "May these charms bring you great luck, <name>.", completion = "May the stars smile upon you, <name>." }
WordHunterWoW_QuestEN[32018] = { title = "His Name Was... Stormstout", description = "An unusual pandaren came through town a few days back. He told a better tale than Pan, drank twice as much as Lee, and then beat me up in front of the bar. All while his little niece made fun of us.\n\nIt was awesome.\n\nThey said they were headed to the Valley of the Four Winds. You should meet him! Just... watch out for that right hook.", objectives = "Speak with Chen Stormstout at the Thunderfoot Fields in the Valley of the Four Winds.", completion = "Ha ha! You were sent by Bolo? The \"Keg Mender,\" right? From the Drunken Hozen?\n\nHow is his eye healing? Is his friend still hung over?\n\nAhh... that was an enjoyable evening." }
WordHunterWoW_QuestEN[32019] = { title = "They Call Him... Stormstout", description = "Things were not always like this, {race}. Oh no, they were much, much worse. Not three weeks ago, we were under siege by saurok bandits. They stole our jade, befouled our food stores, and terrorized our cubs.\n\nWe needed a hero, and a hero arrived.\n\nHe drove back their forces, defeated their leader, and returned our stolen jade. All he asked in return was a serpent ride for his niece.\n\nI was never able to thank him. If you are headed to the Valley of the Four Winds, would you relay our thanks?", objectives = "Speak with Chen Stormstout at the Thunderfoot Fields in the Valley of the Four Winds.", completion = "You come from the Temple of the Jade Serpent? Rain-Zhu sends his thanks?\n\nAi yah... really, that was nothing. I could have defeated that saurok without spilling my beer.\n\nIn fact, I believe I did." }
