WordHunterWoW_QuestEN[32030] = { title = "Once in a Hundred Lifetimes", description = "The time has come, wakener.\n\nThe council's power will combine to bring an end to the corrupted empress.\n\nThis ritual has not been witnessed in one hundred of your kind's lifetimes - and never by an outsider.\n\nIn exchange for your deeds on our behalf, I invite you to behold this great moment in our history.", objectives = "Speak to Klaxxi'va Ik in Klaxxi'vess.", completion = "Your arrival is timely, wakener.\n\nOur ritual is underway." }
