WordHunterWoW_QuestEN[32035] = { title = "Got Silk?", description = "Strange noises comin' from over at the Silken Fields.\n\nStrange smells, too.\n\nAlmost makes you think that they could use a cash-strapped {class} to complete a few odd jobs for 'em. Make a few pieces of gold.\n\nOr not.", objectives = "Report to Silkmaster Tsai at the Silken Fields in Valley of the Four Winds.", completion = "Greetings, <class>. Welcome to the Silken Fields." }
