WordHunterWoW_QuestEN[32045] = { title = "Children of the Water", description = "We are all children of the water here in the Valley of the Four Winds. It nourishes us, it grows our vegetables, it brings us life.\n\nSome creatures, however, drink too deeply from the water. They grow too large, and must be eliminated before they cause havoc to those around them.\n\nI am but a simple stonecarver. You, on the other hand...", objectives = "Slay Kracor, Thundergill, and Succula.", completion = "Let this be a lesson to you: don't drink too much of the water.\n\nWhy do you think we have such a big brewery?" }
