WordHunterWoW_QuestEN[32105] = { title = "Pristine Monument Ledger", description = "This artifact has been restored to a remarkably excellent condition.  Perhaps you will put it on display at the Seat of Knowledge, so that lorewalkers and archaeologists can study it.", objectives = "Put the artifact on display." }
WordHunterWoW_QuestEN[32106] = { title = "A Winter Veil Gift", description = "", objectives = "A small tag on this present reads:\n\nHappy holidays, <name>!" }
WordHunterWoW_QuestEN[32107] = { title = "Flying Tiger Gourami", description = "You've caught a unique fish... with wings.  Perhaps it deserves the expert opinion of Nat Pagle in Anglers Wharf.\n", objectives = "Bring the Flying Tiger Gourami to Nat Pagle at Anglers Wharf." }
WordHunterWoW_QuestEN[32108] = { title = "Domination Point", description = "Now it is time to show this new land the true strength of the Horde.\n\nReturn to the beach and light the remaining signal fire. Our fleet is waiting.", objectives = "Light the Signal Fire on the beach of the Horde Landing Site to signal the Horde fleet.", completion = "<This fire will signal the full might of the Horde invasion fleet to land on this beach, beginning Garrosh's campaign in Pandaria.>" }
WordHunterWoW_QuestEN[32109] = { title = "Lion's Landing", description = "For too long the Horde has been allowed to run rampant across Azeroth. I will not see these new lands conquered by some barbaric \"warchief.\"\n\nAre you ready to bring Alliance justice to the shores of Pandaria?\n\nLet us return to the landing site. Use the flare launcher to bring in the fleet proper, and begin Operation: Shieldwall.", objectives = "Use the Flare Launcher in Krasarang Cove to signal the Alliance fleet.", completion = "<Blue sails are barely visible on the horizon - the full might of the Alliance fleet, awaiting one final signal.>" }
WordHunterWoW_QuestEN[32112] = { title = "FLAG - Been to Fight Club", description = "", objectives = "" }
WordHunterWoW_QuestEN[32113] = { title = "FLAG - Been to Fight Club Today", description = "", objectives = "" }
WordHunterWoW_QuestEN[32114] = { title = "So, You Wanted to Test Daily Quests?", description = "You wanna test dailies? Well alright then.Upon completion of this quest you will gain:", objectives = "You wanna test dailies? Well alright then.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[32115] = { title = "Shackles of the Past", description = "The mogu are a bunch of right bastards!\n\nThey enslaved the pandaren who worked these caves even after their death. Ye' gotta go free their spirits! It's just not right.\n\nBe careful though... so much trauma, they don't know what's a friend and what's an enemy. So they'll probably fight back.", objectives = "Free 14 Troubled Slave Spirits.", completion = "Ye' did good work out there. It's not right seein' the dead unable to rest like that." }
WordHunterWoW_QuestEN[32116] = { title = "Priorities, People!", description = "When I ordered the excavation of the tunnel to the northwest, I thought we'd find something useful. Gold, iron... anything!\n\nInstead, we found mogu artifacts, and I get a bunch of dwarves from the Explorers' League to baby-sit.\n\nI hear from the soldiers that there's trouble in the mines. I have orders from Wrynn that I have to support the Explorers' League, but I can't spare any troops. Can you get down there and find out what's going on?", objectives = "Meet with Hilda Hornswaggle at the Ruins of Ogudei in Krasarang Wilds.", completion = "Oi! We got a right nasty problem here. Kicked the hornet's nest. Except these are mogu ghost hornets with a mean streak a bloody mile wide!" }
WordHunterWoW_QuestEN[32118] = { title = "Taking Advantage", description = "The fools in the Explorers' League have excavated an ancient mogu ruin to the northeast. And - of course - in their bumbling, they've disturbed the mogu spirits within.\n\nWe are going to take advantage of their ineptitude. Take this portal and meet with Kaelis Sunsoar, my contact within the ruins.", objectives = "Use the portal at Sparkrocket Outpost to meet with Kaelis Sunsoar at the Ruins of Ogudei in Krasarang Wilds.", completion = "Ah, yes. Good. Help from Belloc. He never does like to get his hands dirty." }
WordHunterWoW_QuestEN[32119] = { title = "It Is A Mystery", description = "There's somethin' down there that was spookin' the workers. Some kind o' anomaly... looks like a ghost, or a magic spell... like nothing I've ever seen.\n\nI did manage to get a reading on it and put together this device to try to track it down. The display on the device will let you know roughly how close you are. \n\nOnce you get close enough, you can use it to draw out the anomaly and get rid of it for good!", objectives = "Use Hilda's Anomaly Tracker to find and disperse an anomaly.", progress = "We need to get that anomaly gone so our workers won't be spooked!", completion = "Good work! Now maybe the workers can get through a day without fillin' their britches!" }
WordHunterWoW_QuestEN[32120] = { title = "Legacy of Ogudei", description = "The ruins which we are occupying were built by Ogudei - an ancient mogu ruler. We know little about who he was, though the rise of the spirits in this area seems to indicate that it was related to spirit binding.\n\nWhen you destroy these spirits, a small amount of their essence will remain in this world. Bring it to us - we will analyze it and hopefully learn more about Ogudei's history - and his power.", objectives = "Collect 5 Ancient Mogu Essence.", progress = "You'll need to destroy the spirits to collect their essence. Go to it.", completion = "Good, good. We'll begin our research post-haste." }
WordHunterWoW_QuestEN[32121] = { title = "The Spirit Trap", description = "In the ruins there are a bunch of right nasty blue crystals. Look at 'em the wrong way and bloody angry ghosts run out at ya.\n\nI'm gonna be needing ye' to go in and clear some of them out so we can get our people back to work.", objectives = "Destroy 3 Spirit Traps.", completion = "Those things are nasty! Thanks for takin' care of 'em for us." }
WordHunterWoW_QuestEN[32122] = { title = "Ogudei's Lieutenants", description = "When we dug through to an ancient section of the mogu ruins, that's when all this nasty business went down - and that's where the two worst o' these ghosties emerged.\n\nWe need them gone, friend.", objectives = "Kill Meng-do, Strength of Mountains, and Gen-li, Twister of Words.", completion = "You did it! Good work! Really saved our bacon!\n\nHere's to hoping those things don't come back..." }
WordHunterWoW_QuestEN[32123] = { title = "Death on Two Legs", description = "The Alliance has made landfall. If we do not defeat them here, any hope of a Horde presence on this continent is lost.\n\nGo to the battlefield south of here and slay Alliance you find.\n\nShow them how any Horde who still stands on two legs will be the death of ten Alliance!", objectives = "Defeat 10 Alliance soldiers in Domination Point.", progress = "The Alliance must find no purchase on these shores.", completion = "Well done, <name>. I see your time in this land has hardened your resolve and sharpened your skills." }
WordHunterWoW_QuestEN[32125] = { title = "Don't Try So Hard - DEPRECATED", description = "Ah, a <class>! I guess you'll do.\n\nMy spies tell me there are Alliance spies sneaking around outside the fortress. But they are just... so... bad at it! I mean come on! Show a little pride in your work or something.\n\nGo kill a bunch of 'em as a lesson to the others.\n\nHere, take this batch of my latest Spy Stinker formula. If you can't see the spies just start tossing these outside the walls of the fortress to the south and you should flush them out.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Kill 8 SI:7 Saboteurs." }
WordHunterWoW_QuestEN[32126] = { title = "Tear It Up", description = "The Alliance may be cowardly, but they are not fools. Their assault would be formidable, if it were directed at lesser creatures.\n\nTo sustain a siege and put pressure on our troops they are air dropping in supplies to support their ground forces.\n\nSearch the beaches and docks to the south for any airdropped supplies and smash them.\n\nLet the Alliance see their food and ammunition destroyed before their eyes and despair.", objectives = "Destroy 8 Alliance Supply Drops.", progress = "Never rely on a weapon that requires more than your own strength to wield.", completion = "Just remember, the weapon of choice is not always the weapon with the longest range or heaviest amount of damage. In the end, the best weapon is the weapon that works every time." }
WordHunterWoW_QuestEN[32127] = { title = "All Dead, All Dead", description = "Our Warchief has dispatched me to these shores to deal with this pitiful Alliance threat.\n\nThese humans and their allies have proven to be very dependent on their leaders. No initiative of their own.\n\nAs you walk the battlefield today look to the Alliance ships off our southern shores. Find their captains.\n\nSlay them.\n\nFor the Horde!", objectives = "Defeat Captain Brent the Black and Captain Mulkey.", progress = "Every weapon has its function.", completion = "It is not enough to rob the Alliance of their leaders. We must warn those who would aspire to leadership the cost of such ambition." }
WordHunterWoW_QuestEN[32128] = { title = "Another One Bites the Dust", description = "The Alliance have planted themselves off our southern coast and continue to pepper our ground forces with cannon fire. Let us see how great their siege is without such support.\n\nBoard the enemy vessels and destroy their reserve ammunition. This will take the teeth out of their bite.", objectives = "Detonate the explosive cargo of The Defiant and Valor's Edge.", progress = "For the Horde!", completion = "Ah! Look at them burn. These new Alliance craft require more to destroy them permanently however. I am sure they will have those fires out in a day or two." }
WordHunterWoW_QuestEN[32129] = { title = "Defense Daily 06", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[32130] = { title = "Good Luck, Have Fun", description = "I've got some customers lined up that wanna collect some good old fashioned ears. But not any old ears. They only want the absolute waxiest ears money can buy! \n\nGuess they think they're lucky or something'.\n\nAnyways, I need you to go get 'em for me. I don't want to hurt any animals, so you'll need to get 'em from the Alliance over at Lion's Landing.\n\nHave fun - and remember, only bring me the waxiest!", objectives = "Collect 10 Extra-Waxy Alliance Ears at Lion's Landing in Krasarang Wilds.", progress = "Ears, <name>, I wanna see some ears!", completion = "Good and waxy, just like they asked for. Here's your share." }
WordHunterWoW_QuestEN[32131] = { title = "We Require More Minerals!", description = "Gnomes are excavating a stone quarry to the northeast.\n\nThey're building stuff with it!\n\n<Zazzix rolls his eyes.>\n\nThey're too stupid to realize it's special mogu stone for creating animated statues. \n\nWE can mix with a little Goblin magic juice to make some real big explosions!\n\nBut the stuff is heavy. They've got some of their stupid bomb-bots there for excavating the stone. Blow 'em up near slabs and you'll get chunks small enough to carry. \n\nOr, just kill 'em and take it. Whatever works.", objectives = "Collect 20 Animatable Stone chunks from the Lion's Landing quarry. Lion's Landing Engineers carry them, or you can destroy stone slabs with collateral damage to blow them into chunks you can carry.", progress = "You got some stone? I wanna blow stuff up!", completion = "Ha! YES! You got me some! I'm gonna make the best bomb EVER!\n\nMan I love bombs! Love making them, love blowin' em up...\n\n... and yeah, that IS how I got this eyepatch. What's it to ya?" }
WordHunterWoW_QuestEN[32132] = { title = "Worker Harassment", description = "Our goblin friends do not have the grasp of strategy necessary to win a long term engagement, I'm afraid.\n\nThe key to eliminating any permanent establishment is to attack their ability to replenish their troops and to rebuild.\n\nIn this case, that means taking out their Peasants. Kill them, and you weaken the foundation. The rest of the keep is bound to crumble.", objectives = "Kill 30 Lion's Landing Peasants.", completion = "Good work. That should slow them down by a few days, at least.\n\nYou don't win the war by playing the short game, friend. Trust me, this is the right strategy." }
WordHunterWoW_QuestEN[32133] = { title = "Sentry Wards", description = "We've spotted heavy air support over their base, in the form of way too many dwarves on way too many griffons. Means we can't get any vision of the area from above.\n\nA troll... friend of mine gave us a set of Sentry Wards, which we can use to spy on their base and get a vantage point on what's going on in there.\n\nBad news, friend - you're going to be the one going in there.", objectives = "Place Sentry Wards on the Docks, in the Town Hall, and on the Second Floor of the Barracks at Lion's Landing.", completion = "Good work, <name>. I've already been getting some useful information that should help make our next offensive even more devastating." }
WordHunterWoW_QuestEN[32134] = { title = "Hard Counter", description = "We've managed to get some Demolishers on the beach, but the stupid dwarves are also out there with their stupid mortar tubes, preventing the Demolishers from pushing forward and assaulting the keep itself!\n\nGet out there, kill some dwarves, and blow up some mortar tubes.", objectives = "Kill 8 Lion's Landing Mortar Team Engineers and destroy 2 Lion's Landing Mortar Tubes.", completion = "Oh heck yeah! That'll show 'em that NOBODY blows stuff up like goblins blow stuff up!\n\nOh, and you did good work too." }
WordHunterWoW_QuestEN[32135] = { title = "Hero Killer", description = "There are some situations in which taking out one of their soldiers is more important than killing hundreds.\n\nThey've deployed some of their heroes to the battlefield to help rally their defenders. Not only will killing them soften their defense, it will also leave their morale crippled.\n\nSo go, take one down for me. You can handle it.", objectives = "Kill an Alliance Hero at Lion's Landing in Krasarang Wilds.", completion = "Cut off the head, and the body will fall.\n\n... Unless you're forsaken, I guess. I realize I should probably stop using that saying now that I am." }
WordHunterWoW_QuestEN[32136] = { title = "Work Order: Fuel", description = "Our fuel supplies are running low. Without fuel we won't be able to operate the machinery that's building this place. They might even expect me to start helping them build!\n\nI was not built for manual labor! See these nails?! I just had them done!\n\nGet down to the refinery and get this fuel order filled! Hurry! They were fitting me for a tool-belt this morning. It didn't even match my outfit!", objectives = "Find Grizzle Gearslip in Bilgewater Beach.", completion = "More fuel huh? Is her \"loveliness\" afraid she might have to do a little more than sit around lookin' pretty?" }
WordHunterWoW_QuestEN[32137] = { title = "Runnin' On Empty", description = "I've never seen this quality of oil! Problem is the oil needed a little extra refinin'.\n\nI heard of this system where you use ocean water to speed up the process. I don't have time to waste down here, so I just threw the barrels into the bay.\n\nPretty good idea, I know. Problem is, I'm not sure how to pull it out of the bay...\n\nMaybe someone of your expertise could help me out.", objectives = "Retrieve 9 \"Distilled\" Fuel Barrels from the Blacksand Spillway.", progress = "So he found a use for the bay after all? Waste not, want not I guess!", completion = "Oh, yuck! Why are these barrels wet?! Oh nevermind! At least you got here before they made me work. I can't think of anything more horrible!" }
WordHunterWoW_QuestEN[32138] = { title = "Work Order: Lumber", description = "Everyday it's the same thing! \"We're out of this!\", \"We need more of that!\", \"Why don't you ever do anything?!\"\n\nI work! I do things! They can be so hurtful! I'm doin' my best down here!\n\nOh yeah, we need more lumber! Go down and tell that good for nothin' Zino to get his shredders in gear!", objectives = "Find Zino \"The Shredder\" Quickchop in the Lumber Farm.", completion = "Good for nothin' huh?! I'm busting my rump down here!\n\nMaybe her \"uselessness\" would like to come down here and haul this lumber herself!" }
WordHunterWoW_QuestEN[32139] = { title = "Stacked!", description = "We just filled an order this morning. How could they possibly need more already?!\n\nMy team has been workin' double-time to get these trees chopped and processed.\n\nProblem is we have an infestation of Lion's Landing troops down here. I already risked my neck once today, I'm not goin' back out there!\n\nGoob will go with you and help you fill this order. He's not the brightest, but he can do the heavy liftin'.", objectives = "Gather 9 Pieces of Domination Point Lumber from the Lumber Farm.", progress = "Did you get that order filled?", completion = "It's about time you showed up with this lumber order! I was just about to come down there and get it myself." }
WordHunterWoW_QuestEN[32140] = { title = "Work Order: Iron", description = "When they said they found some amazing rocks in that mine I envisioned diamonds. Everyone knows all mines have diamonds, silly! At the very least rubies!\n\nInstead, all I got was this strange iron! What am I supposed to do with this?\n\nOh well, no one said this job would be glamorous. I just do what I can to add a little class.\n\nWe just got another work order for iron. Go see Daxil down near Oregrind's Dig and get it filled pronto!", objectives = "Find Daxil \"The Gem\" Oregrind near Oregrind's Dig.", completion = "Is she still complaining about diamonds and rubies? We found something better than diamonds down here!\n\nThis ore is special. It has power!" }
WordHunterWoW_QuestEN[32141] = { title = "Power Metal", description = "<Daxil narrows her eyes and speaks in a hushed tone.>\n\nSometimes we dig too deep, {class}. Sometimes, we uncover something so horrible we wish we hadn't started diggin'...\n\nJust kidding! I mean, don't get me wrong, we did find something unexpected. The ore we're finding down there is not your average run-of-the-mill iron.\n\nThere is just one problem; Shale Spiders! We're struggling to keep these orders filled.\n\nMaybe you can lend us a hand?", objectives = "Obtain 7 chunks of Energized Ore from Oregrind's Dig.", progress = "Did you happen to find anything sparkly while you were down there?", completion = "Did they manage to find anything useful down there? Maybe an emerald or an opal? Is it too much to ask for a little bit of effort?!\n\nNevermind! I'll make sure this shipment gets where it's goin'." }
WordHunterWoW_QuestEN[32142] = { title = "We Will Rock You", description = "The orcs can NOT be allowed a foothold in this land. They will defile it just as they did Kalimdor.\n\n{name}, I need boots on the ground and horde in their graves. Get down to the coastline and bring the full force of Alliance wrath down on their heads!\n\nSlay any orcs you find. Take the wind out of their sails.\n\nFor the King!", objectives = "Slay 10 Orcs at Domination Point.", completion = "Well done, soldier. That should help keep the horde in check." }
WordHunterWoW_QuestEN[32143] = { title = "A Kind of Magic", description = "Greetings {name}! I have heard a lot about your success in the field. I would like to use your services to test my latest \"Siege-o-Matic\", a device of terrible and varied abilities.\n\nI promise it is mostly harmless to its users.\n\nWhen you are around Domination Point be on the look out for my Scout-o-Meters. They have been dispatched to get info on good siege targets. When you find one, activate it and I will pilot a Siege-o-Matic to your location.\n\nSee you in the field... as it were.", objectives = "Find the three Scout-o-Matics in Domination Point." }
WordHunterWoW_QuestEN[32144] = { title = "Under Pressure", description = "The Horde are consumed by pride and will fight to the death without a second thought.\n\nWe need to find a way to break their will that does not involve massive loss of our numbers.\n\nLook for the Horde supplies along the coastline and near their ships. Smash their supplies.\n\nNothing breaks the will of a defender like seeing their hope of food go up in a puff of smoke.\n\nWhen you are done, find Sully behind enemy lines. He has the next task for you.", objectives = "Destroy 8 Horde Supply Crates.", completion = "Thanks to your actions, the Horde knows it cannot feed its troops.\n\nThe timeframe they can withstand a siege is greatly reduced and their morale is going to start suffering soon.\n\nWe just need to keep applying pressure." }
WordHunterWoW_QuestEN[32145] = { title = "Don't Lose Your Head", description = "My probes have detected three very dangerous targets in the courtyard of Domination Keep.\n\nThey have an ogre emissary, a Kor'kron officer, and an insane goblin bomb maker.\n\nMy siege-o-matics are not ready for one on one combat so it is up to you to eliminate the targets.\n\nGood luck! Report back to me on the Skyfire when done.", objectives = "Defeat Stone Guard Ruk'ra, Bombgineer Snicklefritz, and Or'Dac.", completion = "Great work! Sorry to put good soldiers in harms way but my Auto-Demolish-o-Tronic Mk 2 isn't functional yet." }
WordHunterWoW_QuestEN[32146] = { title = "Hammer to Fall", description = "It looks like the Horde thinks they can hide behind their heavy hitting mooks.\n\nThe mooks are tough, powerful, and dumber than an ogre with a hangover.\n\nGo down there and bring the hammer of the Alliance fury down on them!", objectives = "Kill 5 Heavy Mooks.", completion = "Thank you soldier. That should teach the Horde that it will take more than a couple of mooks to scare us away." }
WordHunterWoW_QuestEN[32147] = { title = "Attack Daily 06", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[32148] = { title = "Attack! Move!", description = "Sure, they've got about plenty of grunts out there, pounding on our door, waiting to cut our heads off.\n\nI'm not worried about grunts. But they've got shamans and raiders, too. The shamans use their magic to empower the grunts, and the raiders are fast and specialize in taking out our buildings.\n\nI need you to get out there and kill some of those shamans and raiders.\n\nGo! Attack! Move!", objectives = "Kill 12 Dominance Shamans or Dominance Raiders.", completion = "Good work, soldier. Without those shamans, I don't think they'll have much luck breaking down our defenses." }
WordHunterWoW_QuestEN[32149] = { title = "Resource Gathering", description = "Oh, the poor peasants...\n\nThey are cowards, yes, of course. But they don't know how to fight, and they go out to collect lumber for our efforts... the Horde targets them... It's just awful all around!\n\nBut, we need that lumber if we're going to hold out. Go out and collect any they've dropped.", objectives = "Collect 12 Lion's Landing Lumber by recovering it from piles of Hastily Abandoned Lumber.", progress = "Did you gather the lumber yet?", completion = "Good work! With this, we'll be able to finish reinforcing the structure of the keep, which will help keep people safe. You've saved lives today!" }
WordHunterWoW_QuestEN[32150] = { title = "Supply Block", description = "The Horde decided to put goblins in charge of their logistics. And where you have goblins, you have carelessly placed explosives.\n\nScouts have reported that they have their supplies in carts that also contain demolisher ammunition. Look at those crates the wrong way, and they'll blow sky high. \n\nWith enough Horde resources destroyed, we'll put a time limit on their attack and save lives. So go and take out those carts!", objectives = "Destroy 8 Domination Point Supply Carts.", completion = "Without those supplies, they won't be able to support bringing more warriors in the fight. If they can't bring in more warriors, we have a great shot at holding out.\n\nFor today, at least." }
WordHunterWoW_QuestEN[32151] = { title = "Tower Defense", description = "The gnomes are running our quarry operation to the northwest. The stone there is especially tough - the gnomes tell me the mogu used it to fashion their constructs. \n\nI don't know. What I do know is that we use that stone to build our towers, and the Horde has dispatched the Bilgewater goblins to steal it from us.\n\nGet out there and get some back. By the way - collateral damage may break up the stone slabs there. If so, pick that up, too.", objectives = "Collect 20 Animatable Stone at the Lion's Landing Quarry from Bilgewater Goblins or by destroying stone slabs there with collateral damage.", progress = "You brought us the stone yet?", completion = "Alright! We'll get that stone mortared into the cracks in our walls faster than a Dwarf downs a pint." }
WordHunterWoW_QuestEN[32152] = { title = "Siege Damage", description = "The Horde got the bright idea to send Bilgewater goblins to attack our quarry.\n\nThey've been packing heavy explosives - heavy explosives that will react with the ammunition in their demolishers.\n\nKill the Bilgewater goblins until you find an explosive, plant it on one of the demolishers... and BOOM! Siege ended.", objectives = "Find a Bilgewater Blasting Cap on a Bilgewater Sapper, and then plant it on a Domination Point Demolisher.", progress = "We need you to take out those demolishers, soldier!", completion = "You really showed them who owns this beach, <name>. Good work!" }
WordHunterWoW_QuestEN[32153] = { title = "Hero Killer", description = "Look, you're tough. Tougher than the rest of the men and women I've got here. Which means I need you for a special mission.\n\nThe Horde is throwing their best against us. Heroes of their armies - Blademasters, Tauren Chieftans, you name it.\n\nI need you to go take one out. It'll be a huge blow, not just to their offensive but also to morale.", objectives = "Kill a Horde Hero.", completion = "I know it wasn't easy, but you did it. Good work. You've got my respect, soldier." }
WordHunterWoW_QuestEN[32154] = { title = "Burn Out!", description = "Those goblins are gettin' out of hand! First they level the forest and set up that abomination of a rig. Then, they start dumpin' their oil barrels into the bay!\n\nWe got to put a stop to this madness! At the very least we need ta set them back.\n\nWe need to take out their fuel supply! Maybe you'll even get to kill a few goblins in the process!", objectives = "Use the Unstable Explosive to destroy the Northestern Fuel Tank, Northern Fuel Tank, and the Northwestern Fuel Tank.", completion = "Wish I could've been there to watch their fuel burn! Probably put on quite the show.\n\nYou've done well, <name>!" }
WordHunterWoW_QuestEN[32155] = { title = "Necessary Breaks", description = "It goes against me nature to break things on purpose, but in this case it's necessary.\n\nThat rig the goblins are usin' is held together by a wish an' some bubblegum. We need to exploit the situation a little more.\n\nWe have some saboteurs down there already, but we can use someone of your expertise to hurry the job along.\n\nGet down there an' start breakin' and stealin' some valves!", objectives = "Steal 7 Rusty Valves from the fuel operation on Bilgewater Beach." }
WordHunterWoW_QuestEN[32156] = { title = "It's Only Right", description = "This is barbaric warfare, {class}! We've lost so many trying to keep the Bilgewater operation from spreading any further.\n\nThose fallen soldiers fought honorably and deserved to be given their last rights. At the very least we need to be able to notify their next of kin.\n\nPerhaps you can collect their identification tags so we can honor them in some small way.", objectives = "Retrieve 7 Shieldwall Soldier Dog Tags from the Fallen Shieldwall Soldiers in and around Bilgewater Beach.", progress = "Even warfare should have some courtesies.", completion = "You have done these soldiers a great service, <name>. The only thing left to do is make sure they did not die in vain." }
WordHunterWoW_QuestEN[32157] = { title = "The Only Good Goblin...", description = "The destruction in Krasarang is unforgivable, {class}. The only way to put an end to this is to destroy the Bilgewater operation.\n\nThis is for the greater good of Pandaria and the Alliance. Go to Bilgewater Beach and cut them down! No doubt the Horde will come to their assistance.\n\nDestroy them!", objectives = "Kill 10 Bilgewater Goblins in and around Bilgewater Beach.", completion = "Excellent work, <class>! Eventually we will wipe the Horde from this continent." }
WordHunterWoW_QuestEN[32158] = { title = "Two Step Program", description = "Shredmaster Packle is responsible for much of the devastation down there, {class}.\n\nRumor has it he modified the shredders to work more quickly with less regard for the collateral damage they can inflict.\n\nImagine the agony the trees must endure being hacked at. It will be difficult to recover from this level of destruction.\n\nThe first step in any recovery is acknowledging the problem. Step two is eliminating that problem.", objectives = "Destroy Shredmaster Packle in Quickchop's Lumber Farm.", completion = "Excellent work, <name>! Now the forest can begin its regrowth process. From all death comes new life, and a new opportunity to protect it." }
WordHunterWoW_QuestEN[32159] = { title = "Circle of Life", description = "We should attempt to offset the destruction being wrought on this continent as much as possible. For every tree they destroy, we will plant a new one!\n\nTake these seeds and begin the regrowth process, {name}.\n\nDo not linger for too long though. Nature is unpredictable, and no doubt the anger and hate exuding from Domination Point has seeped into the ground.\n\nI cannot guarantee that the plant that springs from these seeds will not be hostile.", objectives = "Plant 11 Energized Seeds near Quickchop's Lumber Farm." }
WordHunterWoW_QuestEN[32161] = { title = "Beastmaster's Hunt: The Crane", description = "Along with the snare, you get some advice on crane hunting:\n\nThe greatest cranes of the Krasarang Wilds are not tempted by simple things like food. You will need to play on the creatures' emotions if you wish to draw them from their hiding places in the jungle.\n\nCranes abound on both the Cradle of Chi-ji and the Narsong Spires, both of which can be found east of here. Pluck those cranes' quills, then place them in a visible spot near the Crane Temple. Your quarry will come running to you.", objectives = "Obtain 5 Pristine Golden Crownfeathers and a Pristine Jet Crownfeather.", progress = "This is the spot, near the Crane Temple.", completion = "You place the feathers in the dirt, then look off in the direction of the temple..." }
WordHunterWoW_QuestEN[32162] = { title = "Beastmaster's Hunt: The Tiger", description = "Along with the trap, you get some advice on tiger hunting:\n\nTigers are gluttonous creatures, and large game is hard to come by in this jungle. If you wish to tempt the most elder cats out of their hiding places, you may do so with a meal.\n\nJust on the other side of the Serpent's Spine, you will find a herd of yaks. Slay them, bring their meat to the jungle's edge, set up your trap, and wait.", objectives = "Obtain 25 Unbruised Yak Haunches.", progress = "This looks like an ideal spot for a tiger trap.", completion = "You lay the meat out atop the trap, then turn your eyes toward the jungle..." }
WordHunterWoW_QuestEN[32163] = { title = "Beastmaster's Hunt: The Crab", description = "Along with the crate, you get some advice on crab hunting:\n\nCrabs are strange, primordial creatures, with wildly different motivations than you or I.\n\nSmall crabs are easy to find and hunt, but the large ones hide beneath the sands, out of danger and out of our reach. To draw them out, we play on their sense of smell.\n\nThe Unga villagers to the southeast allow their fish to ferment before they eat them. Bring enough rotten fish together, and you will catch yourself a colossal crab.", objectives = "Obtain 30 Funky Rotten Fish from Unga Villagers in Unga Ingoo.", progress = "This looks like a good place to catch a crab.", completion = "You spread out the decaying fish, prepare the crate, then turn your eyes toward the beach..." }
WordHunterWoW_QuestEN[32164] = { title = "Beastmaster's Hunt: The Crane", description = "Along with the snare, you get some advice on crane hunting:\n\nThe greatest cranes of the Krasarang Wilds don't care about simple things like food. You need to play on the creatures' emotions if you want to draw them out of the jungle.\n\nThere's plenty of cranes on the Cradle of Chi-ji and on the Narsong Spires, both to the west of here. Pluck some of those cranes' quills, then put them in a visible spot near the Crane Temple. Your quarry will come running to you.", objectives = "Obtain 5 Pristine Golden Crownfeathers and a Pristine Jet Crownfeather.", progress = "This is the spot, near the Crane Temple.", completion = "You place the feathers in the dirt, then look off in the direction of the temple..." }
WordHunterWoW_QuestEN[32165] = { title = "Beastmaster's Hunt: The Tiger", description = "Along with the trap, you get some advice on tiger hunting:\n\nTigers are gluttons, and big game is hard to come by in this jungle. If you want to tempt the elder cats out of their hiding places, you need a tempting meal.\n\nJust on the other side of the Serpent's Spine, you can find a herd of yaks. Kill them, bring their meat to the jungle's edge, set up your trap, and wait.", objectives = "Obtain 25 Unbruised Yak Haunches.", progress = "This looks like an ideal spot for a tiger trap.", completion = "You lay the meat out atop the trap, then turn your eyes toward the jungle..." }
WordHunterWoW_QuestEN[32166] = { title = "Beastmaster's Hunt: The Crab", description = "Along with the crate, you get some advice on crab hunting:\n\nCrabs are strange, old creatures, with different motivations than us.\n\nSmall crabs are easy to find and hunt, but the big ones hide beneath the sands, out of danger and out of our reach. To draw them out, we play on their sense of smell.\n\nThe Unga villagers to the southwest allow their fish to ferment before they eat them. Bring enough rotten fish together, and you will catch yourself a colossal crab.", objectives = "Obtain 30 Funky Rotten Fish from Unga Villagers in Unga Ingoo.", progress = "This looks like a good place to catch a crab.", completion = "You spread out the decaying fish, prepare the crate, then turn your eyes toward the beach..." }
WordHunterWoW_QuestEN[32167] = { title = "Ancient's Fall", description = "The crane has fallen.", objectives = "Speak with Jorn Skyseer at Domination Point in Krasarang Wilds." }
WordHunterWoW_QuestEN[32168] = { title = "End of an Elder", description = "The tiger has fallen.", objectives = "Speak with Jorn Skyseer at Domination Point in Krasarang Wilds." }
WordHunterWoW_QuestEN[32169] = { title = "A Colossal Victory", description = "The crab has fallen.", objectives = "Speak with Jorn Skyseer at Domination Point in Krasarang Wilds.", completion = "Well fought, <name>." }
WordHunterWoW_QuestEN[32170] = { title = "Ancient's Fall", description = "The crane has fallen.", objectives = "Speak with Huntsman Blake at Krasarang Cove in Krasarang Wilds." }
WordHunterWoW_QuestEN[32171] = { title = "End of an Elder", description = "The tiger has fallen.", objectives = "Speak with Huntsman Blake at Krasarang Cove in Krasarang Wilds." }
WordHunterWoW_QuestEN[32172] = { title = "A Colossal Victory", description = "The crab has fallen.", objectives = "Speak with Huntsman Blake at Lion's Landing in Krasarang Wilds.", completion = "Well fought, <name>." }
WordHunterWoW_QuestEN[32173] = { title = "Build Portal 01", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[32174] = { title = "Build Portal 01", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[32175] = { title = "Darkmoon Pet Battle!", description = "Are you prepared to test the mettle of your pets...?", objectives = "Defeat Jeremy Feasel in a pet battle.", progress = "My, my. Well done!", completion = "I must say, good show!" }
WordHunterWoW_QuestEN[32181] = { title = "Beastmaster's Quarry: The Crane", description = "The ancient crane is alive, but stunned.\n\nYou should bring it back to Jorn Skyseer before it wakes up.", objectives = "Bring the Ancient Bloodcrown Crane to Jorn Skyseer.", progress = "Welcome back, <name>.", completion = "It only took one to capture the beast, but it will take many more to truly defeat it.\n\nSpeak to me again when you have gathered enough allies. We shall test the grace of the crane against the might of the Horde." }
WordHunterWoW_QuestEN[32182] = { title = "Beastmaster's Quarry: The Tiger", description = "The elder cat is alive, but stunned.\n\nYou should bring it back to Jorn Skyseer before it wakes up.", objectives = "Bring the Krasari Elder to Jorn Skyseer.", progress = "Welcome back, <name>.", completion = "It only took one to capture the beast, but it will take many more to truly defeat it.\n\nSpeak to me again when you have gathered enough allies. We shall test the ferocity of the tiger against the might of the Horde." }
WordHunterWoW_QuestEN[32183] = { title = "Beastmaster's Quarry: The Crab", description = "The colossal crab is alive, but stunned.\n\nYou should bring it back to Jorn Skyseer before it wakes up.", objectives = "Bring the Colossal Viseclaw to Jorn Skyseer.", progress = "Welcome back, <name>.", completion = "It only took one to capture the beast, but it will take many more to truly defeat it.\n\nSpeak to me again when you have gathered enough allies. We shall test the resilience of the crab against the might of the Horde." }
WordHunterWoW_QuestEN[32184] = { title = "Beastmaster's Quarry: The Crane", description = "The ancient crane is alive, but stunned.\n\nYou should bring it back to Huntsman Blake before it wakes up.", objectives = "Bring the Ancient Bloodcrown Crane to Huntsman Blake.", progress = "Welcome back, <name>.", completion = "It might have taken just one <race> to capture this beast, but it will take many more to put it down.\n\nGather up some friends, then come and speak with me again. We'll pit the grace of the crane against the glory of the Alliance!" }
WordHunterWoW_QuestEN[32185] = { title = "Beastmaster's Quarry: The Tiger", description = "The elder cat is alive, but stunned.\n\nYou should bring it back to Huntsman Blake before it wakes up.", objectives = "Bring the Krasari Elder to Huntsman Blake.", progress = "Welcome back, <name>.", completion = "It might have taken just one <race> to capture this beast, but it will take many more to put it down.\n\nGather up some friends, then come and speak with me again. We'll pit the power of the tiger against the glory of the Alliance!" }
WordHunterWoW_QuestEN[32186] = { title = "Beastmaster's Quarry: The Crab", description = "The colossal crab is alive, but stunned.\n\nYou should bring it back to Huntsman Blake before it wakes up.", objectives = "Bring the Colossal Viseclaw to Huntsman Blake.", progress = "Welcome back, <name>.", completion = "It might have taken just one <race> to capture this beast, but it will take many more to put it down.\n\nGather up some friends, then come and speak with me again. We'll pit the stamina of the crab against the glory of the Alliance!" }
WordHunterWoW_QuestEN[32189] = { title = "A Shabby New Face", description = "A strange fellow in a pointy hat showed up this morning trying to sell some kinda special seeds. Claimed they were magic.\n\nI welcome a little competition - business is business, after all - but this gentleman had a certain... shabby look to him. Oh, and he stunk somethin' FIERCE.\n\nWould you check up on him, just to make sure he's on the level? He's over there by Jian Ironpaw, making a meal out of the samples.", objectives = "Speak with Barnaby Fletcher in Halfhill Market.", completion = "AUGHM... nomf... -slurp- mmmf...\n\n<Barnaby looks up from the table, revealing a tangled beard dotted with melon seeds. Juices rush down his chin as he greets you.>\n\nMmf... -cough- A customer! Hello! Name's Fletcher. Barnaby Fletcher - nice to meet you!\n\n<He wipes a hand on his robe before extending it, still visibly sticky and flecked with pulp.>" }
WordHunterWoW_QuestEN[32190] = { title = "To Mogujia", description = "Throm-ka, {class}. While we were busy defending our foothold here, Regent Lord Lor'themar Theron led a research expedition north into Kun-Lai Summit.\n\nUnfortunately, it seems they have encountered trouble.\n\nWarchief Garrosh Hellscream has already departed to lend his assistance, but he will require additional reinforcements.\n\nGo northward into the mountains of Kun-Lai. Speak to Tak-Tak for transportation.", objectives = "Find Regent Lord Lor'themar Theron at Mogujia. Speak to Tak-Tak at Domination Point for transportation.", progress = "Were you sent from Domination Point?", completion = "Well met, <class>. We are an archaeological expedition, sent to excavate these ruins. We had no idea that this area was crawling with dangerous mogu." }
WordHunterWoW_QuestEN[32191] = { title = "Ancient Guardians", description = "Before the mogu overwhelmed our scouting party, we found relics scattered amongst the ruins to the north.\n\nI would like to collect some samples, but the mogu's terracotta watchdogs are too much for us to handle.\n\nIf you could clear the area of their presence, we will be able to resume our work.", objectives = "Kill 5 Korune Guardians.", progress = "I am quite keen to understand the mogu's magic.", completion = "Ah! Well done! With the guardians gone, we should be able to excavate these ruins safely." }
WordHunterWoW_QuestEN[32192] = { title = "Bloodlines", description = "We managed to fend off the mogu wardens and their dogs, but many of the blood elves from the scouting party were not as lucky.\n\nMany of my people are trapped inside the ruins to the north. We are devising a solution to break them out, but I believe there may be a more straightforward approach.\n\nGo to the ruins and kill the wardens guarding each prisoner. If my intuition is correct, this will free our comrades.", objectives = "Free 6 Domination Mages by killing Korune Wardens.", progress = "These mogu are not to be underestimated.", completion = "We blood elves have served the Horde faithfully. Lately, I wonder what we have to gain from Garrosh's leadership." }
WordHunterWoW_QuestEN[32193] = { title = "To Mogujia", description = "The Explorers' League sent an expedition north some days ago.\n\nWe haven't heard from them since, and I'd sleep better at night knowing our folks aren't in some sort of trouble.\n\nLast I heard, Brann Bronzebeard was heading toward Mogujia in the Kun-Lai Summit.\n\nFind him and report back with their status. Fennie over there can give you a ride if you need one.", objectives = "Find Brann Bronzebeard at Mogujia. Speak to Fennie Hornswaggle at Lion's Landing for transportation.", completion = "These artifacts must be several thousand years old. Have ye ever seen the like?" }
WordHunterWoW_QuestEN[32194] = { title = "Bad Blood", description = "The Explorers' League is here to excavate the ruins, and it's my job to protect them.\n\nWhen we arrived, we found this place crawling with blood elves. Apparently,the Horde are just as interested in the mogu as we are.\n\nThis gives quite an opportunity to thin our enemies' numbers, and steal their findings, too.\n\nSlay any blood elves you find in the ruins, and bring back whatever they are digging up.", objectives = "Collect 5 Korune Artifacts from Silvermoon Runeseekers, Dominance Mages, or Dominance Knights.", progress = "What are those blood elves after?", completion = "Well done, <class>. I knew that you could get the job done." }
WordHunterWoW_QuestEN[32195] = { title = "Anger Remains", description = "From the looks o' our initial survey, this entire area is humming with residual sha energy.\n\nYou know what ta do, {name}. Destroy any last traces ye can find o' the stuff!", objectives = "Kill 27 Angerlings." }
WordHunterWoW_QuestEN[32196] = { title = "A Kind of Magic - DEPRECATED", description = "Greetings <..your name here..>!\n\nDo you find war to be constantly challenging your survivability? Is today's Horde proving to be too much for your armor?\n\nWell, then look no further than the all new \"Siege-o-Matic 4000\".\n\nTry it out the latest prototype today! Just look for Scout-o-Matics <near the Wolf Kennel>, <near the Horde Base entrance>, and <atop the Horde Battlements>.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Find the 3 Scout-o-Matics in Domination Point." }
WordHunterWoW_QuestEN[32197] = { title = "Mystery Meatloaf", description = "We've been gettin' complaints right and left that the Boss-Lady gets all the good grub and leaves the scraps for the others.\n\nBetween you and I, they may be onto somethin' here. I don't even get to eat as good as she does!\n\nWe need somethin' Sezik can make a lot of that at least attempts to disguise how inedible the food is here...\n\nI got it! Mystery Meatloaf!", objectives = "Obtain 7 Chunks of Mystery Meat from the local wildlife.", progress = "What do ya got for me now?", completion = "I have standards ya know! I'm a chef, not a magician!\n\nThe only mystery here is how Duke thinks he'll pull this over on everyone else!" }
WordHunterWoW_QuestEN[32198] = { title = "One Magical, Flying Kingdom's Trash...", description = "Before we enter into a business relationship, I am required by the terms of my rehabilitation program to inform you that I am a recovering potion addict.\n\nThere, now that THAT's out of the way, let's talk portals!\n\nYou see, the big portals in the cities - the ones running all day and night - leak tons of magical energy. It crystallizes around the edges and is generally regarded as trash.\n\nBut I noticed during my, uh... hiatus in the sewers of Dalaran, that these shards still had power.\n\nInterested?", objectives = "Speak with Barnaby Fletcher to learn more about Portal Shards.", completion = "I knew you would be!\n\nHere's the catch - the shards, in their current state, are unstable. But the soil in this valley is renowned for its magical properties! I am sure if you were to \"plant\" the shard, a very interesting reaction would take place.\n\nIt could stabilize, leaving you with a functioning portal! Or... it might tear open a magical rift that spits out transdimensional horrors!\n\nMy gut tells me it will be a little of both, but there's only one way to know for sure.\n\nHere, take a sample!" }
WordHunterWoW_QuestEN[32199] = { title = "Krasarang Steampot", description = "The Boss-Lady desires crabs!\n\nWhy are you looking at me like that? It's not uncommon for a classy person, such as her loveliness, to want crab for dinner. What did you think I meant?\n\nThere are some big crabs wandering around on Bilgewater Beach that should be suitable for her refined palate.\n\nBring Sezik the best crab meat you can find!", objectives = "Obtain 5 chunks of Polluted Viseclaw Meat from the Viseclaw crabs on Bilgewater Beach.", progress = "Boss-Lady wants a steampot does she? Well, maybe she should come down here and make it herself!", completion = "This meat is disgusting! It's going to take every spice I have to cover that smell up.\n\nOnly the best for the Boss-Lady!\n\n<Sezik grins and winks at you.>" }
WordHunterWoW_QuestEN[32200] = { title = "Dangers of Za'Tual", description = "{name}, what I ask of you is little short of genocide, but it is a task that must be done.\n\nFind trolls within their town or on the beach and slay them, for the good of us all.", objectives = "Slay 12 Trolls in Za'Tual.", completion = "Much blood was spilled this day. It is on my hands, <name>, not yours." }
WordHunterWoW_QuestEN[32201] = { title = "Grave Circumstances", description = "The Court of Bones crawls with mogu forces. Endlessly do they perform their rituals of lightning and thunder.\n\nIf our mission to take this island is to succeed, then we cannot allow them to hold such a strategic position.\n\nThey must be eliminated.", objectives = "Kill 10 Shan'ze Gravekeepers, Shan'ze Soulrippers, or Shan'ze Thundercallers.", progress = "The mogu are powerful, but with cunning and tenacity, we can defeat them.", completion = "Excellent. You have dealt the mogu a blow that they shall not easily forget." }
WordHunterWoW_QuestEN[32202] = { title = "Kill Trolls", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[32203] = { title = "Kill Mogu Spirits", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[32204] = { title = "The Skumblade Threat", description = "Ihgaluk Crag has no end of saurok. Those beasts attack my men and spread their disease into nearby water and wildlife, interfering with our operations.\n\nThin their numbers, {name}. Once the Horde takes full control of this island, we can look for more permanent solutions.", objectives = "Slay 10 Skumblade saurok.", completion = "One day, this island will belong to the Horde. I can only hope that it will be free of saurok before then.\n\n<Aethas sneers.>\n\nAt least they attack the Alliance, too." }
WordHunterWoW_QuestEN[32205] = { title = "Gather Scout Reports", description = "", objectives = "" }
WordHunterWoW_QuestEN[32206] = { title = "This Just Won't Do", description = "The Zandalari here are very powerful, {class}. They should not be underestimated. We cannot afford to ignore them as a threat simply because they do not wield swords.\n\nMore arrive every day, and with them centuries of magic knowledge. This threat must be dealt with, and quickly.\n\nAid us in clearing this area, {class}. Perhaps we can even learn something from them in the process.", objectives = "Kill any 8 Zandalari trolls within Conqueror's Terrace.", progress = "Magic can be a great ally or your worst enemy. Let's not leave it to chance.", completion = "It's impressive how easily you were able to cut them down.\n\nPerhaps, it's you they should not underestimate. Thank you for your assistance, <class>." }
WordHunterWoW_QuestEN[32207] = { title = "Saur Loser", description = "Inside the Beast Pens you will encounter some of the most skilled beast tamers in the Zandalari military. They are trained to kill with axe, beast, and claw. This is where they build their cavalry.\n\nWe need you to kill any Zandalari you find in there before they can get their mounted monstrosities out into the open battlefield.", objectives = "Defeat 10 Zandalari trolls in the Beast Pens.", completion = "A trained Zandalari beastcaller with a mount unleashed on the battlefield can kill twenty times their number. Your preemptive attack has saved many lives. Thank you!" }
WordHunterWoW_QuestEN[32208] = { title = "Maximum Capacitor", description = "The mines north of here are being used to extract Ghost Iron ore and energize it with lightning energy.\n\nWe need to destroy the drills they use to extract the ore. They are impervious to normal attack, but can be overloaded using the proper methods.\n\nOh - and while you're there, take out whoever is running the operation.", objectives = "Interact with the three lightning drills in the Ghost Iron Mines to destroy them, and kill Metal Lord Mono-Han." }
WordHunterWoW_QuestEN[32209] = { title = "Save Our Scouts!", description = "The heavy mogu presence in the mines let us know it was a place of great importance - but we needed to gather more information on their activities there, so we sent agents into the mines to spy on them.\n\nUnfortunately, many were captured, and we've found that some are being tortured in the mines. You have to go rescue them - nobody deserves what they are going through...\n\nAnd, when you finish, kill whoever captured them. No mercy, {name}!", objectives = "Rescue the three captured Sunreaver agents within the Ghost Iron Mines, and kill Metal Lord Mono-Han." }
WordHunterWoW_QuestEN[32210] = { title = "Kill mogu boss for key, use object behind jumping puzzle", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[32211] = { title = "Nalak the Storm Lord", description = "[PH] Kill Nalak [Description]You will receive:", objectives = "[PH] Kill Nalak [Log Description]" }
WordHunterWoW_QuestEN[32212] = { title = "The Assault on Zeb'tula", description = "Our scouting efforts along the coast have given us valuable intelligence about the island, {class}.\n\nHowever, we will accomplish nothing if we do not advance forward onto the mainland.\n\nI have assembled a team of our most elite aerial units to begin the attack.\n\nI would like you to join the assault. A champion such as yourself could turn the battle in our favor at the critical moment.\n\nWhen you are ready to begin the attack, speak to me.", objectives = "Complete the Assault on Zeb'tula. Speak to Lor'themar Theron to begin the attack.", progress = "We must claim a better strategic position on the island itself.", completion = "Yes! You have done it, champion!\n\nWe will be as a tide that sweeps over this island, bringing with it a new destiny for our people. And you, hero, are at its forefront." }
WordHunterWoW_QuestEN[32213] = { title = "Old Enemies", description = "So Jaina and the Kirin Tor think they can push us out again? I will not stand by and allow them to repeat the events of Dalaran!\n\nThis time we fight back! This time we do the pushing...\n\nGo to Violet Rise and slay any Kirin Tor agent you find.", objectives = "Kill 10 Kirin Tor units or players on the Isle of Thunder.", completion = "So, Violet Rise runs red with the blood of our enemies? Well done, <name>.\n\nThis will be an ongoing battle I fear. We must continue to show our strength here." }
WordHunterWoW_QuestEN[32214] = { title = "Bilgewater Infiltrators", description = "There is nothing more unnerving than walking along, minding your own business, and hearing someone following you. I swear I hear it all over the place down here! We're being watched!\n\nI have a feeling the entire beach is just crawling with spies!\n\nI made some improvements to our infrared goggle tech to put an end to the sabotogery. That's right sabotogery! Now I just need you to try 'em out! Feel free to dispose of any spies you happen to catch.", objectives = "Kill 10 SI: 7 Saboteurs around Domination Point and Bilgewater Beach.", completion = "Very nice, <name>! I knew it! I knew there were Alliance sneaking around down there!\n\nNo one messes with a Bilgewater rig and gets away with it!" }
WordHunterWoW_QuestEN[32215] = { title = "Heinous Sacrifice", description = "The Zandalari perform heinous rites against our people! They must be stopped!\n\nDelve into the heart of the Za'Tual and destroy their altars.", objectives = "Destroy the Zandalari sacrificial altars.", progress = "This effort should quell their obscene sacrifices for a time.", completion = "I could feel the magic of their altars dissipating even here, <class>." }
WordHunterWoW_QuestEN[32216] = { title = "Pterrible Ptorment", description = "The Zandalari treat their skyscreamer pets as little more than scuttling vermin, bending them to their will with violence and torment.\n\nI can hear one writhing in pain at their hands.\n\nFind the tormented skyscreamer within Za'Tual and help it break free of its captors.", objectives = "Free the Tormented Skyscreamer.", progress = "Have you found the skyscreamer?", completion = "It what?! It killed its master? Wonderful. These skyscreamers  have more fight in them than I realized. Thank you for helping free the beast, <race> - it is one less threat to the Horde, and one more for the Zandalari." }
WordHunterWoW_QuestEN[32217] = { title = "Dark Offerings", description = "The spirtibinders of the Zandalari perform sacrificial rites to appease the loa and their vile gods. These dark rituals involve the sacrifice of our people.\n\nDestroy any offerings you can find among their tents in Za'Tual and perhaps we can stall the sacrifices.", objectives = "Destroy 6 Zandalari Offerings.", progress = "I truly hope this helps slow them down. The sacrifices proceed at an alarming rate.", completion = "The tide of blood is slowed, at least for a time. Thank you for your efforts in stalling the sacrifices, <class>." }
WordHunterWoW_QuestEN[32218] = { title = "Ashes of the Enemy", description = "The mogu here at the Court of Bones are bolstering their army by resurrecting the spirits of their dead.\n\nWe cannot allow them to revive their fallen warriors.\n\nTake this torch and burn any mummified corpses that you can find.\n\nWe will destroy our enemies before they have a chance to rise.", objectives = "Burn 8 Mummified Remains.", progress = "The dead should be allowed to rest.", completion = "Their dead shall rise no more, thanks to you, <name>. Excellent work." }
WordHunterWoW_QuestEN[32219] = { title = "Stone Cold", description = "Our assault on the Court of Bones continues. Our progress remains slow, but measurable.\n\nUnfortunately, we've received several reports of stone quilen statues coming to life without warning. I can't have these quilen threatening my research expedition.\n\nVenture into the Court of Bones and destroy any quilen statues that you can find.", objectives = "Destroy 8 Grave Guardians.", completion = "I am glad to hear that you left the quilen in a thousand tiny pieces. You have contributed much to our war effort." }
WordHunterWoW_QuestEN[32220] = { title = "Soul Surrender", description = "We assault the mogu at the Court of Bones, but I fear we merely send them fodder for their abominable rituals.\n\nThe mogu do not merely kill their prisoners - they steal their souls and imbue them in machinations of stone, or reforge the fallen into ghostly tools of war.\n\nHorde or Alliance, it matters not. We cannot allow the mogu to bolster their numbers.\n\nGo into the crypts. Free any prisoners that are still living.", objectives = "Save 6 Sunreaver Scouts or Silver Covenant Scouts.", completion = "Thank you, <name>. You have lightened my heart of a heavy burden through your heroic actions.\n\nI will remember your efforts on this day." }
WordHunterWoW_QuestEN[32221] = { title = "Storming the Beach", description = "Our lumber supply is being jeopardized by constant attacks from Lion's Landing.\n\nWe've been able to keep the attackers at bay, but it's time to really show 'em some muscle!\n\nHead down to the coast and start splitting some skulls!", objectives = "Kill any 10 Shieldwall Forces including SI: 7 Saboteurs in and around Bilgewater Beach.", completion = "Excellent work down there, <name>! That should keep 'em outta our hair for awhile!" }
WordHunterWoW_QuestEN[32222] = { title = "WANTED: Chief Engineer Cogwrench", description = "Wanted for crimes against the Bilgewater Operation!\n\nChief Engineer Cogwrench was last seen building what appeared to be a giant spider tank on the edge of Bilgewater Beach.\n\nExtreme caution should be used when approaching.\n\nA large reward has been posted for Cogwrench's destruction.", objectives = "Destroy Chief Engineer Cogwrench at the edge of Bilgewater Beach.", completion = "Excellent work, <class>! This brings us one step closer to pushing them out of Pandaria!" }
WordHunterWoW_QuestEN[32223] = { title = "WANTED: Lieutenant Ethan Jacobson", description = "Wanted for crimes against the Domination Point forces!\n\nLieutenant Ethan Jacobson is responsible for leading several ground assaults against the Bilgewater lumber operation.\n\nLast spotted occupying an island south of Quickchop's Lumber Farm.", objectives = "Destroy Lieutenant Ethan Jacobson in the Southern Isles south of Quickchop's Lumber Farm.", progress = "Do not return without his blood on your hands!", completion = "It's a good day when another Lion's Landing leader falls, <class>! Good work!" }
WordHunterWoW_QuestEN[32224] = { title = "Rise No More!", description = "Have you seen the ghosts wandering the graveyard?\n\nThey are risen ancestors, the spirits of slain mogu who have been called back to this world.\n\nWhen angered, they attack swiftly and silently, and their numbers increase by the day.\n\nThey do not belong here. Destroy them, and send them back beyond the grave.", objectives = "Kill 15 Risen Ancestors.", completion = "Wonderful work, <class>. This will help our offensive a great deal." }
WordHunterWoW_QuestEN[32225] = { title = "The Call of Thunder", description = "Within the graveyard, in the deepest ruins of their western crypt, the Thunder King's most powerful sorcerers are charging a lightning rod with crackling electricity.\n\nWe suspect that this weapon is meant to rain destruction on our stronghold at Dawnseeker Promontory.\n\nThere is no time to delay. You must stop their ritual at once.", objectives = "Stop the Shan'ze Thundercallers' ritual.", completion = "You continue to exceed my expectations, <class>. Well done." }
WordHunterWoW_QuestEN[32226] = { title = "Into the Crypts", description = "The Reliquary is having a field day out here, literally!\n\nEvery day, the researchers find more relics to study and catalog.\n\nRecently, one of our adventurers found this scroll at the Court of Bones.\n\nI believe that this incantation can be used to call beyond the grave. And if my Mogu is up to date, I'd say you should use it in the last room in the Hall of the Exalted.\n\nWould you be willing to test out my theory?", objectives = "Use the Incantation of Gura in the Hall of the Exalted, then defeat Gura the Reclaimed.", completion = "Ah yes, you've just confirmed my theory! Thank you, <class>." }
WordHunterWoW_QuestEN[32227] = { title = "Preventing a Future Threat", description = "The creatures the Zandalari ride don't start out so big, nor do they start out the vicious and loyal creatures they become.\n\nIf you can frighten some of the hatchling skyscreamers away from the beach, perhaps they will have a chance at a real life.", objectives = "Frighten 12 Hatchling Skyscreamers by running near them.", completion = "You have returned, <race>. It is my hope that these young skyscreamers have the lives they deserve without dealing with the harsh treatment of the trolls." }
WordHunterWoW_QuestEN[32228] = { title = "The Shuddering Moor", description = "There is an immense beast in the swamp. It has not yet marched upon us, but I place no stock that we will continue to be so fortunate.\n\nStrike it down before it grows hungry enough to brave our defenses.", objectives = "Kill the Mighty Devilsaur.", completion = "You are not one to be trifled with. I am sure to have further use of your services.\n\nCome back to me in a day's time, <class>." }
WordHunterWoW_QuestEN[32229] = { title = "Kill Roaming Troll War Party", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[32230] = { title = "The Zandalari Colossus", description = "The trolls have dispatched one of their immense constructs on the southern road, blocking our passage around the island. See to it that the road is cleared, {class}.", objectives = "Destroy the Zandalari Colossus.", progress = "Have you done as I asked?", completion = "When I give you a task, it gets handled.\n\nWell done, <class>." }
WordHunterWoW_QuestEN[32231] = { title = "Trailing Light in the Dark", description = "There is some dark magic in the Diremoor that extinguishes even our magical illuminations, and so our scouts struggle to find their way.\n\nAs you pass through the swamp, relight any torches you find that our men might find their way. Perhaps they will help you find your way back as well.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Relight 8 torches within the Diremoor." }
WordHunterWoW_QuestEN[32232] = { title = "What's Inside Counts", description = "I noticed something strange on my last scouting mission. A group of Zandalari are performing a ritual on what appears to be a very large sentry. They may be trying to re-animate it.\n\nWe need that ritual stopped and the sentry destroyed. Anything that large can't be good.\n\nI've sent a scout ahead to observe their actions. Meet with her and figure out how to stop them.", objectives = "Destroy Guardian Tak'u in Conqueror's Terrace.", completion = "So I was correct to be concerned. It's a good thing you were there to stop them before that guardian was fully infused.\n\nGood work, <class>." }
WordHunterWoW_QuestEN[32233] = { title = "Very Disarming", description = "Look around you, {class}. What do you see? I see an opportunity.\n\nThe casters here work to imbue the Zandalari weapons with powerful magic. As if a sharp blade isn't enough to cut even the strongest foe down to size.\n\nIn my scouting I've noticed the weapons are not very well guarded. This is where you come in...\n\nIf we can steal a few of these weapons we may be able to use them. At the very least they are out of enemy hands.", objectives = "Steal 7 Loa-Infused Blades from Conqueror's Terrace.", progress = "So? What did you find?", completion = "Excellent work, <class>!\n\nThese weapons are terrifying on their own, nevermind the magic they are infused with." }
WordHunterWoW_QuestEN[32234] = { title = "Knowledge Is Power", description = "The Zandalari here practice a different kind of magic. We must understand it before we can defeat it, {class}.\n\nTheir control over the arcane and shadow is impressive. I wish to learn how they have achieved what so many others have not.\n\nI believe their ritual artifacts may hold the answers I seek. Bring me a sampling of the artifacts you find, and I will ensure you are rewarded properly.", objectives = "Retrieve 6 Ritual Artifacts from around Conqueror's Terrace.", progress = "Did you find the artifacts?", completion = "These will do nicely, <class>. Excellent work." }
WordHunterWoW_QuestEN[32235] = { title = "Flash! Aaaaaahhhh!", description = "The gnomes have brought their flying contraptions. I want my skies CLEAR!\n\nGet up there on whatever mount you have with you and destroy those paltry devices.\n\nYou may use this grog I \"acquired\" from our goblin allies. It would be better served blasting down gyrocopters than in the gullet of those little green fiends.", objectives = "Use the Bilgewater Molotovs to destroy 6 Skyfire Gyrocopter X2s.", progress = "Hellscream's eyes are upon you.", completion = "Ha! Simple mechanical toys are no match for a well aimed bottle of grog." }
WordHunterWoW_QuestEN[32236] = { title = "Bug Off!", description = "This cave is crawlin' with nasty shale spiders! How's a girl supposed to get any work done with them gobbling up the miners AND the ore?!\n\nThis seemed like a good opportunity to use my newest invention, Bug Off. See, all you have to do is spray this stuff all over the shale spiders. They hate it and it doesn't seem to have many long term side-effects for the miners!\n\nWhat could possibly go wrong?\n\nTake this handy sprayer and get to work!", objectives = "Spray 5 Agitated Shale Spiders with the Bug Off Sprayer and eradicate 12 Shale Shards.", progress = "Shale spiders. Why did it have to be shale spiders?!", completion = "Now that's what I like to hear! I bet those spiders will think twice before messing with a Bilgewater operation again!" }
WordHunterWoW_QuestEN[32237] = { title = "Precious Resource", description = "What we have here is too much of a good thing, {name}!\n\nOur rig just can't handle the amount of oil we're pumping out of the ground. It's literally bursting at the seams! To be more accurate, it's bursting at the valves.\n\nI've been working double-time to get the valves repaired, but every time I finish the rounds, they're all broken again.\n\nIt's as if someone is following me... That's ridiculous though....\n\nMaybe you'll have better luck. Try getting as many of those valves tightened as you can.", objectives = "Tighten 8 Faulty Valves in and around Gearslip's Gusher.", progress = "Were you able to get those valves tightened?", completion = "So I was being followed! Those dirty rotten sneaks!\n\nI'm going to have to start planting some real nice surprises for those cowards. Surprises that will really knock 'em out!" }
WordHunterWoW_QuestEN[32238] = { title = "Universal Remote-Explode", description = "The Mecha-Pounders are really making things difficult down here, but I think I may have the solution!\n\nI made this universal remote for myself, but it looks like I hit a specific frequency that has an useful result!\n\nApparently this frequency weakens their armor!\n\nUse the remote to take them down a few notches then punch 'em in the face!", objectives = "Destroy 9 Shieldwall Mecha-Pounders in and around Quickchop's Lumber Farm.", progress = "How'd the remote work for ya?", completion = "Good work, <name>! I saw the fireworks from here!\n\nWho knew being a genius was this easy? I don't even have to try anymore." }
WordHunterWoW_QuestEN[32242] = { title = "Buried Secrets", description = "I am told that the mogu once possessed hundreds of hidden armories full of earth-shattering weapons.\n\nWhen a mogu army prepared for war, they struck fear and terror into the hearts of their enemies.\n\nTHIS is the knowledge I seek here on Pandaria!\n\nI have sent an expedition to study some ruins to the west, but they work as slowly as dim-witted peons!\n\nGo speak to Fanlyr Silverthorn, their leader. Tell him that I want to see results immediately.", objectives = "Speak to Fanlyr Silverthorn at Ancestral Rise in the Vale of Eternal Blossoms.", completion = "The Warchief sent you? What does he say?" }
WordHunterWoW_QuestEN[32243] = { title = "The Source of Korune Power", description = "Why hullo there! Have ya ever seen tha like o' these statues? Fascinatin'!\n\nI was scouting up along the ruins earlier, and I spotted somethin' innerestin' up on the highest rise.\n\nI couldn't get close enough, but I think it might be one o' these mogu statues, 'cept it was movin'!\n\nI can't get through all those nasty blood elves, but you look like you could.\n\nWould you mind going up there and bringing me back anything of interest?", objectives = "Collect a Sha-Touched Claw from the Korune Spellweaver.", progress = "Did ya find anything up there?", completion = "Oh my, look at this thing!" }
WordHunterWoW_QuestEN[32244] = { title = "The Korune", description = "These terracotta wardens are fearsome, but not nearly as horrifying as the creature that we found at the top of the ruins.\n\nSome of our surviving scouts reported seeing some kind of mogu spellweaver on the highest rise to the north.\n\nHe practices a type of magic unlike any other we have seen.\n\nWe must learn whatever we can from this creature. Slay him, and bring me anything you find.", objectives = "Collect a Korune Codex from the Korune Spellweaver.", progress = "What did you discover?", completion = "Yes, this is remarkable! This is just the kind of artifact that we came here to find!" }
WordHunterWoW_QuestEN[32246] = { title = "Meet the Scout", description = "It has been two months since the parting of the mists. Alliance scouts, seeking a suitable landing site for the fleet, have engaged Horde forces on a beach in Krasarang Wilds.\n\nMeet with Scout Lynna and help secure the landing site.", objectives = "Speak with Scout Lynna at Krasarang Cove in Krasarang Wilds.", completion = "You have impeccable timing, <class>. King Wrynn is just about to land, and the full might of our fleet will follow soon after." }
WordHunterWoW_QuestEN[32247] = { title = "A King Among Men", description = "There's no time to waste, we need to find Troteman and secure the beach.\n\nWe should check on the dwarves, too - the Explorers' League is tough, but they're no army. They should be along the cliff just north of here.\n\nLet us ride, {class}. For our friends. For the Alliance.", objectives = "Accompany King Varian Wrynn to find Marshal Troteman, Hilda Hornswaggle, and slay 25 Horde.", progress = "The Alliance will be a shield, protecting Pandaria from the Horde.", completion = "I'm satisfied with this site, it's time to bring in our fleet." }
WordHunterWoW_QuestEN[32248] = { title = "A Little Patience", description = "King Varian needs decisive adventurers to help him resolve a showdown between Tyrande Whisperwind and a detachment of Horde warriors holed up in the Temple of the Red Crane.\n\nReport to him immediately!", objectives = "Enter the \"A Little Patience\" scenario and report to King Varian Wrynn.", completion = "Good to see you again, <name>.\n\nWe have a delicate situation on our hands here. We need to plan our next moves carefully." }
WordHunterWoW_QuestEN[32249] = { title = "Meet the Scout", description = "It has been two months since the parting of the mists. Horde scouts, seeking a suitable landing site for the fleet, have engaged Alliance forces on a small island off the coast of Krasarang Wilds.\n\nMeet with Scout Rokla and help secure the landing site.", objectives = "Speak with Scout Rokla at the Horde Landing Site in Krasarang Wilds.", completion = "You are just in time. The Warchief is about to land. Once this site passes his inspection, the fleet will follow." }
WordHunterWoW_QuestEN[32250] = { title = "The Might of the Warchief", description = "Come, {class}! I want to inspect this island and ensure that my landing team has done their job.\n\nBlood Guard Gro'tash should be somewhere on the northern side of the island looking for a suitable place to build our keep. The goblin survey team will have gone up the eastern coast in search of oil.\n\nLet us crush this pitiful display and claim this land for the Horde!", objectives = "Accompany Garrosh Hellscream to find Blood Guard Gro'tash, Grizzle Gearslip, and slay 25 Alliance.", progress = "Gorehowl thirsts for Alliance blood.", completion = "Well done. Our presence here will not be denied!" }
WordHunterWoW_QuestEN[32251] = { title = "Dagger in the Dark", description = "Shadow Hunter Vol'jin has joined a group of Kor'kron scouts on an important mission for the warchief.\n\nOf course a proud member of the Horde such as yourself is welcome to go along, but be warned - it could get ugly.", objectives = "Enter the \"Dagger in the Dark\" scenario and report to Vol'jin.", completion = "Good ta see ya, mon. I be needin' true allies at my side for dis mission." }
WordHunterWoW_QuestEN[32252] = { title = "Harbingers of the Loa", description = "Have you heard of the loa? We do not understand all of what it is, but it seems to be a dark magic with some degree of sentience.\n\nWe do not know what power the loa might possess, but I must ask you to put a stop to their rituals, {class}.", objectives = "Slay 2 Harbingers of the Loa.", completion = "I can only imagine what horrors you witnessed, <name>. Your bravery was put to the test this day, and you did not fail the Horde in your task." }
WordHunterWoW_QuestEN[32253] = { title = "REMOVE (No Longer Used)", description = "", objectives = "" }
WordHunterWoW_QuestEN[32254] = { title = "Manipulating the Saurok", description = "I have three magisters entrenched in Ihgaluk Crag, monitoring the saurok and - where they can - turning them against the mogu. I need you to find them and see if they need any supplies or assistance.\n\nThey will be concealed from view. Look for shimmering columns of light within the saurok village.", objectives = "Check in with Magister Arlan, Magister Sarien, and Magistrix Vesara.", completion = "<The archmage listens carefully to your report.>\n\nI understand. Thank you for your aid, <class>." }
WordHunterWoW_QuestEN[32255] = { title = "De-Constructed", description = "Saurok consistently test our borders, and our constructs usually fend them off. Some constructs, however, have been defeated and dragged back to Ihgaluk Crag.\n\nI want those constructs back. No slithering lizard will steal Sunreaver property under my watch.", objectives = "Recover the four stolen Sunreaver Constructs.", completion = "That's more like it.\n\nThank you, <class>." }
WordHunterWoW_QuestEN[32256] = { title = "Rise Of An Empire", description = "Warchief Garrosh Hellscream travels north with a squad of his most elite soldiers.\n\nReport to him with news of our continued victory against the Alliance.\n\nSpeak to Tak-Tak for transportation.", objectives = "Find Warchief Hellscream at the Shrine of Two Moons. Speak to Tak-Tak at Domination Point for transportation.", completion = "What do you have to report?" }
WordHunterWoW_QuestEN[32257] = { title = "Voice of the Gods", description = "Too slowly!? We are working as quickly as possible for the Warchief!\n\nWe must excavate carefully, catalogue each find, and of course follow safety procedures. He must understand!\n\nWell, we may have something to show him soon. Do you see that stone statue to the west?\n\nWe suspect it is an ancient stone storage vessel. Now we just have to find a way to open it.\n\nIf you would care to help us with our excavation, please go about it carefully.", objectives = "Investigate the Mercurial Guardian and obtain the Ancient Korune Tablet.", progress = "We are quite capable of handling this excavation. I understand the Warchief sent you, but he will get faster results if he leaves us to our work.", completion = "Hmm... very interesting. This tablet will yield many secrets, indeed." }
WordHunterWoW_QuestEN[32258] = { title = "Horde Quest Choice: PvP", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[32259] = { title = "Horde Quest Choice: PvE", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[32260] = { title = "Alliance Quest Choice: PvE", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[32261] = { title = "Alliance Quest Choice: PvP", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[32262] = { title = "Captive Audience", description = "The Kirin Tor have gone too far! Now they hold our fellow Sunreavers as war prisoners!\n\nThere will be no discussion of prisoner exchange. We will handle this ourselves.\n\nGo to Violet Rise and free as many prisoners as you can. Do not get captured yourself. We cannot afford to lose you too.", objectives = "Free 5 Sunreaver Captives around Violet Rise.", completion = "Those you have rescued today would no doubt thank you, if they had the strength.\n\nOur task here will be ongoing. I refuse to leave anyone behind!" }
WordHunterWoW_QuestEN[32263] = { title = "Find scout near enemy camp (injured, port him back)", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[32264] = { title = "Spellbound", description = "Jaina possesses several very powerful magic artifacts. These items travel with her at all times, and are never far from her grasp. I have an interest in one of these items.\n\nA tome, filled with knowledge, passed from one archmage to another. I have only ever seen glimpses of it.\n\nNow that we fight on opposite sides I see no issue in removing the tome from her possession.", objectives = "Retrieve Jaina's Weathered Spellbook from Violet Rise.", progress = "Do you have it? Do you have the book?!", completion = "I have desired this book for many years, <race>. It's power is too immense to describe. You have done me a great service." }
WordHunterWoW_QuestEN[32265] = { title = "Charged Moganite", description = "We have been dispatching spies into the Kirin Tor base of operations on a daily basis. Some had orders to recover charged moganite from the enemy and bring it here.\n\nThey have not returned, and I can confirm they have left the Kirin Tor base.\n\nSearch the jungle between here and there and find any of the charged moganite that might have been lost in transit. Bring it to me and we will put it to good use.", objectives = "Recover a Charged Moganite and bring it to High Arcanist Savor.", completion = "Well done, champion. This artifact will be put to better use in our hands than in the hands of the Kirin Tor." }
WordHunterWoW_QuestEN[32266] = { title = "Mana Manifestations", description = "Manafiends are nasty creatures. Small and easy to underestimate, but deadly to our magic casters. The Kirin Tor have these pests crawling all over Violet Rise.\n\nWe will need to handle them carefully. Alone they are easily managed, but in groups they become a different challenge altogether.\n\nGo to Violet Rise and cut down their numbers.", objectives = "Kill 9 Kirin Tor Manafiends.", completion = "This task will be ongoing, but you have done as a great service, <race>." }
WordHunterWoW_QuestEN[32267] = { title = "Destroy enemy portal near camp (streaming attackers, defended, enemy can use)", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[32268] = { title = "Tactical Mana Bombs", description = "Ah, {name}, just the {race} I was looking for. I have received another batch of tactical mana bombs that I need planted in key positions across Violet Rise to the southeast.\n\nHere, take these. I do not trust our standard soldiers with such firepower. Oh... and don't shake them, whatever you do.\n\nPlant one of the Kirin Tor ships, another one near their supplies, and the last on the construct they are building. ", objectives = "Plant a Tactical Mana Bomb on an Alliance Ship, Alliance Supply Shipment, and on the Construct Ritual.", completion = "I am sure the use of even these smaller mana bombs has Jaina squirming with rage. Serves her right.\n\nDalaran was my home before her grandparents were born. What right did she have to expel me from my home?" }
WordHunterWoW_QuestEN[32269] = { title = "Breaking Down the Defenses", description = "We need to keep a close watch on the Kirin Tor and their day-to-day activities. Normally this would be easy. We would sneak in a spy and have them report back to us.\n\nHowever, we've run into a slight problem I believe you can help us with.\n\nThe Kirin Tor perimeter wards have increased in power. It's next to impossible to get someone past their lines. If they were disabled we might be able to sneak in before they can be repaired.", objectives = "Destroy 6 Kirin Tor Perimeter Wards.", completion = "Good work, <class>. With your help we were able to successfully sneak several spies behind enemy lines." }
WordHunterWoW_QuestEN[32270] = { title = "Disarm mines near enemy camp (poke them with a stick =P)", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[32271] = { title = "Set magical mines around camp (using modern warfare lightning)", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[32272] = { title = "Start and defend summoning ritual near enemy camp", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[32273] = { title = "Destroy summoning circles in enemy camp (BloodElf_PowerOrb_Red)", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[32274] = { title = "The Residents of Ihgaluk", description = "The Skumblade threaten our people, but responding with all-out slaughter would be an overreaction.\n\nA more reasonable response to their threat would be to slay some of their tribal leaders. There will be less bloodshed, and they will still respect our perimeter.", objectives = "Slay a Skumblade Brute, a Skumblade Saur-Priest, and a Skumblade Seadragon.", progress = "The saurok value strength above all else. They only respond to strength.\n\nPeace with the saurok will require some amount of bloodshed. The question is, how much?", completion = "I know the true price of bloodshed. I know the cost of war.\n\nIt would be simpler to blindly massacre our attackers until they yield. But is it right?" }
WordHunterWoW_QuestEN[32275] = { title = "Surgical Death", description = "The Zandalari train skyscreamers to become ferocious beasts in the skies. The spiritbinders require endless sacrifices - of our people - to be brought to them. And, the jaguar warriors venture ever closer toward the heart of our camp.\n\nFind them in Za'Tual and remove the threat.", objectives = "Slay 3 Zandalari Spiritbinders, 3 Zandalari Beastcallers, and 3 Zandalari Jaguar Warriors.", completion = "I shall continue my unrest until the threat is subdued, but your aid brings us closer to that goal. I thank you, <name>." }
WordHunterWoW_QuestEN[32276] = { title = "Tear Down This Wall!", description = "The time has come. Our forces are well-enough entrenched here that we can risk pressing forward, into the Thunder King's lair. Unfortunately, it doesn't look like he'll be opening that gate anytime soon.\n\nI suppose we'll have to make a gate of our own then. Let me know when you're ready, {name}.", objectives = "Speak with Lor'themar Theron, then break into the lower city and secure it for the Horde.", progress = "Let's tear down this wall.", completion = "With your help, we're one giant step closer to our goal." }
WordHunterWoW_QuestEN[32277] = { title = "To the Skies!", description = "We can use the pterrorwing that you found to strike a decisive blow against the mogu. \n\nTheir mining operation is vulnerable to attack from the air, and your pterrorwing is the only beast we have capable of flying out there.\n\nLet me know when you are ready!", objectives = "Gain access to the Lightning Vein Mine.", progress = "It's time to begin your mission!", completion = "Incredible work. This presents us with a monumental opportunity." }
WordHunterWoW_QuestEN[32278] = { title = "Decisive Action", description = "Zandalari warships plunder the seas around this island. They ferry in soldiers and war beasts from Zandalar to bolster Lei Shen's army.\n\nIf we can capture the palace shipyard, the Thunder King's supply line will be cut off, and your foothold here will be secure.\n\nI have a plan to do just that, and it won't take an entire army.", objectives = "Infiltrate Stormsea Landing and open the courtyard gate from within. Speak with Taoshi to begin the mission.", completion = "Excellent work! With that blasted warship out of commission, the bombardments on our forces along the coast will cease.\n\nTaran Zhu has informed me that the Shado-Pan will keep vigil over Stormsea Landing, freeing up Sunreaver resources to press the siege elsewhere. Taoshi will be there. I am sure she will be glad to work with you again.\n\nWe are all grateful for your contributions, <name>. Thank you." }
WordHunterWoW_QuestEN[32279] = { title = "The Fall of Shan Bu", description = "Long ago, Lei Shen found a rare clutch of storm dragon eggs. One of these creatures - Nalak - was particularly brutal, and Lei Shen took it for his own.\n\nThe Thunder King's servant, Shan Bu, works to resurrect Lei Shen's dragon, Nalak.\n\nWe must defeat Shan Bu and, if we are able, prevent him from resurrecting the dragon.", objectives = "Defeat Shan Bu.", progress = "We must defeat Shan Bu while he is exposed!", completion = "Well done, <name>. Shan Bu's fall will weaken the Mogu and your heroism will surely be remembered." }
WordHunterWoW_QuestEN[32280] = { title = "Metalocalypse", description = "You've made a good start, but now it's time to really make a dent in their operations.\n\nTake out Metal Lord Mono-Han,  of the mines.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Kill Metal Lord Mono-Han outside the Ghost Iron Mine on the Isle of the Thunder King." }
WordHunterWoW_QuestEN[32281] = { title = "Fleshcrafter's End", description = "The mogu responsible for the torture of the agents, Fleshcrafter Goju, stands outside the mine.\n\nKilling him would be the only justice for what he's done to your agents.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Kill Fleshcrafter Goju outside the Ghost Iron Mines on the Isle of the Thunder King." }
WordHunterWoW_QuestEN[32282] = { title = "Compy Stomp", description = "The raptors and compies of the Zandalari represent a substantial threat to our forces here. They are superb hunting beasts that can track prey over great distances and are often lethal to encounter when caught unawares.\n\nI need you to head into the Beast Pens and cull their numbers. We need to make sure to slay them before they are fully trained.", objectives = "Kill 5 Raptors and 10 Trained Compies in the Beast Pens.", progress = "Say what you will about the Zandalari but none can contest their ability to turn even the most repellant of creatures into a trained weapon.", completion = "We lost three good soldiers when we first arrived on this island. Killed in their sleep by compies that had snuck into their tent. Some nights I still hear the screams." }
WordHunterWoW_QuestEN[32283] = { title = "Loa-saur", description = "The Zandalari have found a way to bind loa to their beasts giving them impressive and lethal powers.\n\nWe need to put a stop to this.\n\nSearch the Beast Pens for a loa speaker and slay him. You should be able to find them by keeping a look out for their glowing beasts.\n\nWe must not allow these atrocities to continue.", objectives = "Defeat a Loa Speaker.", completion = "Well done, champion. These beasts are strong enough. We don't need them infused with an angry spirit now do we?" }
WordHunterWoW_QuestEN[32284] = { title = "Someone You Should See", description = "{name}? It is good fortune I find you.\n\nChen Stormstout says to give this to you and ask you to meet him at Binan Village of the Kun-Lai Summit.\n\nHe found a friend of yours who needs much luck to get healthy.\n\nChen say speak to Tak-Tak for fast travels.", objectives = "Find Chen Stormstout at Binan Village. Speak to Tak-Tak at Domination Point for transportation.", progress = "It is not my place to choose a side in this war. But I am not going to let a troll who has accomplished so much in his day fall by the wayside.", completion = "Ah! You received my note. Very good. Vol'jin is near death, and I will need your help healing his wounds." }
WordHunterWoW_QuestEN[32285] = { title = "The Sleepless Legion", description = "The Shan'ze are animating an army from the statues in the center of the isle, an army that batters our defenses day and night. Destroy any of the walking statues you see. Our defenders will greatly appreciate it.", objectives = "Kill 6 Animated Warriors.", completion = "Your efforts are appreciated." }
WordHunterWoW_QuestEN[32286] = { title = "Kill Mogu Blood-seekers (Roaming pairs, actively fighting scouts, and performing rituals on corpses)", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[32287] = { title = "Enemies Beneath the Tower", description = "There are mogu in the Diremoor animating the army of statues near the tower. Lor'themar wants them dead. I think you're the one to do it.", objectives = "Kill 7 Shan'ze mogu in the Diremoor.", completion = "Well done, <class>. Thank you for the help." }
WordHunterWoW_QuestEN[32288] = { title = "Bolstering the Defenses", description = "This island holds many dangers for us. Threats loom from every side. We must defend our hold on these shores at all costs.\n\nPerimeter wards have been placed around Dawnseeker Promontory. By default they will inflict damage, but are not fatal in their attack.\n\nNow is not the time to be merciful, {race}. The perimeter wards need to be deadly!\n\nGo and empower the perimeter wards surrounding our camp.", objectives = "Empower 6 Sunreaver Perimeter Wards.", completion = "Now that the wards have been fully armed, we can focus our attention elsewhere. Nothing will be slipping past us now!" }
WordHunterWoW_QuestEN[32289] = { title = "Loot plans, kill boat captain", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[32290] = { title = "Unused", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[32292] = { title = "Forge Ahead!", description = "The forge lies ahead of you, and with it the heart of the mogu's weaponsmithing ability.\n\nAnd beyond that, the mogu gatekeeper, who holds the key to unlocking the gate to the next part of the city.\n\nIt's time to move out!", objectives = "Kill the Master of the Forge and collect a Codex Fragment from Fleshcrafter Hoku in the Isle of Thunder.", progress = "Well?", completion = "Good work. What you did today brings us one step closer to our ultimate goal." }
WordHunterWoW_QuestEN[32293] = { title = "Among the Bones", description = "My scouts have spotted a dangerous Zandalari among the bones west of Ihgaluk Crag. I need someone capable to see him dispatched. Are you up to the task?", objectives = "Kill Zur'chaka the Bonecrafter.", progress = "Is it done?", completion = "It's good to have a man I can trust close at hand." }
WordHunterWoW_QuestEN[32294] = { title = "Raining Bones", description = "We've spotted a Zandalari leader up the central stairs. We need to eliminate him before returning to camp.\n\nWould you be willing to do the deed?", objectives = "Kill Zur'chaka the Bonecrafter.", completion = "You're a good <class> to have around, that's for certain. Thank you." }
WordHunterWoW_QuestEN[32295] = { title = "An Unusual Tome", description = "The tome appears to be written in an ornate, sprawling script that seems to rise off the pages. It vaguely resembles Demonic, but the symbols are far more elaborate than any you've ever seen.\n\nPerhaps one of your demonic companions can tell you more.", objectives = "Speak with your demonic minion to determine the origins of the tome." }
WordHunterWoW_QuestEN[32296] = { title = "Treasures of the Thunder King", description = "My scouts have returned with word that more of the treasures from Lei Shen's tomb are being brought up into the citadel. We have access to a secret sewer entrance, but a door bars us from intercepting the shipment. If we're going to succeed in this raid, we will need a key that only the most trusted of Lei Shen's forces carry.\n\nIf you get your hands on such a key, bring it to me.\n\nYou can keep whatever spoils you steal from our raid. I simply want to see that this shipment never makes it to Lei Shen.", objectives = "Speak to Taoshi to enter the Thunder King's Citadel. Inside, provide her with a Key to the Palace of Lei Shen to begin the timed raid on his treasure convoy.", progress = "We must disrupt Lei Shen in any way we can. Anything to hinder the rise of his power. Anything to hinder his armies from being bolstered.\n\nIf that means highway robbery, I can live with that.", completion = "Not entirely unsuccessful. Still, we'll do better next time.\n\nThanks for providing us with that key. The raid would not have gone off without you." }
WordHunterWoW_QuestEN[32297] = { title = "Direhorn or Devilsaur", description = "We have an opportunity to disrupt the Zandalari war machine as well as have a little fun in the process.\n\nWithin these beast pens, a devilsaur and a direhorn are being outfitted with armor, their minds being enslaved to the Zandalari charms.\n\nGo into the camp and disrupt one of these binding rituals. It doesn't matter which one. Just kill those who are trying to bind the creature. This should let the fully armored beast run mad through the Zandalari camp. Then sit back and watch the hilarity ensue.", objectives = "Disrupt a binding ritual by killing all ritual NPCs around either a Defiant Direhorn or a Defiant Devilsaur.", progress = "So... did you decide the devilsaur or the direhorn?", completion = "Few things in this world and beyond are more entertaining than watching a rampaging ancient beast tearing through an enemy's settlement.\n\nIf times were not so dire I would consider selling tickets to such an event." }
WordHunterWoW_QuestEN[32298] = { title = "Dino Might", description = "The Zandalari use a series of fetishes and charms to maintain their control over their menagerie of beasts.\n\nTwo can play at that game.\n\nI want you to find some of these fetishes and try them out on the various beasts in the Beast Pens.\n\nTake careful note of how each beast responds to each fetish. Then report your results to me.\n\nMaybe this will give us the edge we need against the Zandalari.", objectives = "Find and use Saur Fetishes on 5 raptors, compies, skyscreamers or direhorns in the Beast Pens.", progress = "I heard screaming? Was that your efforts perhaps?", completion = "Very interesting results. I am sure there is a mage somewhere that cares about the specifics. I, on the other hand, am just glad to hear the sound of trolls being assaulted by their own beasts." }
WordHunterWoW_QuestEN[32299] = { title = "Just Some Light Clean-Up Work", description = "This is not a glamorous job. Let me put it to you bluntly.\n\nThe Skumblade saurok pile all of their filth into a pool in the middle of their village. This filth is so concentrated and so rancid that it has congealed into moving, animate matter.\n\nThe saurok can keep their filth-pool, but once it starts spreading outside of the village, I'd say it's time to intervene.", objectives = "Disperse 75 pieces of filth by killing Quivering Filth in Ihgaluk Crag.", completion = "Jobs like this make me glad that I left most of my nose in the tomb." }
WordHunterWoW_QuestEN[32300] = { title = "Disarming Irony", description = "Well, it would seem the Lady Proudmoore has decided to use our own weaponry against us. Our perimeter wards reported several spies slipping through our defenses carrying tactical mana bombs.\n\nI would enjoy the irony if these bombs were less dangerous.\n\nSearch for these bombs and disarm them. Our wards reported one near the horde ships to the north, one on a bridge to the main isle, and one near our scrying crystals on the eastern side of the Promontory.", objectives = "Disarm the Tactical Mana Bombs at the Horde Ships, the Scrying Crystals, and the Bridge within Dawnseeker Promontory.", completion = "Good work. The real irony is had these been normal bombs we would have had a much harder time detecting them. Some gnomish devilry could have spelled the end of our operation here." }
WordHunterWoW_QuestEN[32301] = { title = "Old Enemies", description = "To think, we were once on the same side! The Sunreavers' treachery caught us all off guard. Never again!\n\nThey have shown their true natures to us. Siding with Garrosh and his madness has marked them all for death.\n\nKill any agent of the Sunreavers that you find. We will show them no mercy here.", objectives = "Kill 10 Sunreaver agents or players on the Isle of Thunder.", progress = "How many have been slain?", completion = "You have put a good dent in the Sunreaver forces here. Like vermin, there will always be more. We must be at the ready at all times." }
WordHunterWoW_QuestEN[32302] = { title = "Desconstruction", description = "The Kirin Tor constructs are primitive at best. Nevertheless, they pose a threat.\n\nGo to Violet Rise and dismantle Jaina's pitiful war machines. Show the Kirin Tor how easily they can be defeated!\n\nThis will be a message the Kirin Tor cannot easily ignore.", objectives = "Destroy 3 Kirin Tor Constructs around Violet Rise.", completion = "So the constructs have fallen? Good!\n\nWe will remind Jaina and the Kirin Tor at every turn that the Sunreavers are not to be taken lightly." }
WordHunterWoW_QuestEN[32303] = { title = "Made for War", description = "Jaina thinks this battle will be easily won. I intend to show her how wrong she is!\n\nThe Kirin Tor brought a weapon with them that must be destroyed. The Arcane Destroyer is a large construct capable of turning the tides of war in their favor.\n\nDestroying this monstrosity would send a very clear message to Proudmoore.", objectives = "Kill the Arcane Destroyer.", completion = "I wish I could be there to see the look on Proudmoore's face as she mourns the loss of her death machine!\n\nWe can be certain she will build another, but we have at least set her back." }
WordHunterWoW_QuestEN[32304] = { title = "High Recognition", description = "", objectives = "Your presence on the battlefield cannot be ignored. I would like to give you something extra for your efforts, <class>." }
WordHunterWoW_QuestEN[32305] = { title = "Overpowered", description = "The Kirin Tor are using mana foci to empower their forces. We cannot allow this to continue.\n\nYou'll find these foci scattered around the outskirts of Violet Rise. Use this mana crystal to destroy as many as you can.\n\nEach mana focus we destroy is another small victory for our cause.", objectives = "Destroy 7 Mana Foci around Violet Rise.", completion = "Excellent work, <class>! It will take them days to rebuild those foci." }
WordHunterWoW_QuestEN[32306] = { title = "Lumber Collection Tracking", description = "", objectives = "" }
WordHunterWoW_QuestEN[32307] = { title = "Reader for the Dead Tongue", description = "Return to your capital city and seek out a warlock trainer who may know more about the codex.", objectives = "Bring the codex to a Warlock trainer in your capital city.", completion = "What... where in the great dark did you find this?" }
WordHunterWoW_QuestEN[32309] = { title = "A Tale of Six Masters", description = "This book may be just the leverage we've been seeking... \n\nHow familiar are you with the Council of the Black Harvest, {name}?\n\nAfter Deathwing was defeated, six of the greatest Warlocks gathered together to teach all Warlocks advanced forms of magic stolen from our defeated foes.\n\nTake a look at the tome beside me...", objectives = "Read the first chapter of the Legacy of the Masters.", progress = "Well, what did you think?", completion = "You are ready to learn more..." }
WordHunterWoW_QuestEN[32310] = { title = "A Tale of Six Masters", description = "This book may be just the leverage we've been seeking... \n\nHow familiar are you with the Council of the Black Harvest, {name}?\n\nAfter Deathwing was defeated, six of the greatest Warlocks gathered together to teach all Warlocks advanced forms of magic stolen from our defeated foes.\n\nTake a look at the tome beside me...", objectives = "Read the first chapter of the Legacy of the Masters.", progress = "Well, what did you think?", completion = "You are now ready to learn more..." }
WordHunterWoW_QuestEN[32311] = { title = "Enlistment Orders", description = "After the Council returned from their journey, they passed the knowledge of what they learned to all of the Warlock sects.\n\nHowever, they disappeared shortly afterwards...\n\n{name}! The tome you possess may be just the thing we need to convince them to join us in our assault against the Alliance!\n\nFind General Nazgrim in Domination Point and convince him of the importance of your mission.", objectives = "Find General Nazgrim at Domination Point in Krasarang WildsAfter the Council returned from their journey, they passed the knowledge of what they learned to all of the Warlock sects.\n\nHowever, they disappeared shortly afterwards...\n\n<name>! The tome you possess may be just the thing we need to convince them to join us in our assault against the Alliance!\n\nFind General Nazgrim in Domination Point and convince him of the importance of your mission.You will receive:" }
WordHunterWoW_QuestEN[32312] = { title = "Enlistment Orders", description = "After the Council returned from their journey, they passed the knowledge of what they learned to all of the Warlock sects.\n\nHowever, they disappeared shortly afterwards...\n\n{name}! The tome you possess may be just the thing we need to convince them to join us in our assault against the Horde!\n\nFind Admiral Taylor in Lion's Landing and convince him of the importance of your mission.", objectives = "Find Admiral Taylor in Lion's Landing in Krasarang WildsAfter the Council returned from their journey, they passed the knowledge of what they learned to all of the Warlock sects.\n\nHowever, they disappeared shortly afterwards...\n\n<name>! The tome you possess may be just the thing we need to convince them to join us in our assault against the Horde!\n\nFind Admiral Taylor in Lion's Landing and convince him of the importance of your mission.You will receive:" }
WordHunterWoW_QuestEN[32313] = { title = "Hunt Helheim", description = "{name}... You've heard correctly. Warchief Garrosh tasked me with tracking down this Council of the Black Harvest.\n\nUnfortunately, I have heard word that the Alliance is ahead of us. I heard that some Human Warlock by the name of Hareem Helheim has information which will help us locate them.\n\nHead to Lion's Landing, infiltrate their base and obtain the documents before Helheim's courier departs. Show Helheim no mercy.", objectives = "Obtain the second part of Legacy of the Masters from Hareem Helheim." }
WordHunterWoW_QuestEN[32314] = { title = "Slaughter Selenora", description = "{name}... You've heard correctly. King Varian tasked me with tracking down this Council of the Black Harvest.\n\nUnfortunately, the Horde is seeking them out as well. One of my spies recently sent word that Shadowmancer Selenora has the second piece of their journal.\n\nHead to Domination Point, slaughter Selenora and bring back whatever you find on her rotting cadaver.", objectives = "Obtain the second chapter of Legacy of the Masters from Shadowmancer Selenora in Domination Point." }
